INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d9e9be5-962b-42d5-9190-c156201650f8', '贈別李紛', '贈別李紛', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["頭白乘驢懸布囊，一迴言別泪千行。","兒孫滿眼無歸處，唯到尊前似故鄉。"]', '["头白乘驢懸布囊，一迴言別泪千行。","兒孫满眼無归处，唯到尊前似故乡。"]', '诗', 'shi', '', NULL, '贈別李紛 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c438d6af-aceb-4d5a-a283-02262f35a793', '罪所送苗員外上都', '罪所送苗員外上都', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["謀身當議罪，寧遣友朋聞。","禍近防難及，愁長事未分。","寂寥驚遠語，幽閉望歸雲。","親戚如相見，唯應泣向君。"]', '["謀身當議罪，寧遣友朋闻。","禍近防难及，愁长事未分。","寂寥驚远語，幽閉望归云。","親戚如相见，唯應泣向君。"]', '诗', 'shi', '', NULL, '罪所送苗員外上都 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4b60d2-ed07-456f-bb82-2db027e705ed', '送李校書赴東川幕', '送李校书赴东川幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["泥坂望青城，浮雲與棧平。","字形知國號，眉勢識山名。","編簡塵封閣，戈鋋雪照營。","男兒須聘用，莫信筆堪耕。"]', '["泥坂望青城，浮云與棧平。","字形知国號，眉勢識山名。","編簡塵封閣，戈鋋雪照營。","男兒須聘用，莫信笔堪耕。"]', '诗', 'shi', '', NULL, '送李校書赴東川幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a9fe1c-3f19-4351-9b6a-13d690a366ed', '至德中贈內兄劉贊', '至德中贈內兄劉贊', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["時難訪親戚，相見喜還悲。","好學年空在，從戎事已遲。","聽琴泉落處，步履雪深時。","惆悵多邊信，青山共有期。"]', '["时难訪親戚，相见喜還悲。","好学年空在，從戎事已遲。","听琴泉落处，步履雪深时。","惆悵多邊信，青山共有期。"]', '诗', 'shi', '', NULL, '至德中贈內兄劉贊 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34368466-3d81-438a-a69a-039f47eff812', '春日灞亭同苗員外寄皇甫侍御', '春日灞亭同苗員外寄皇甫侍御', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["坐見春雲暮，無因報所思。","川平人去遠，日暖鴈飛遲。","對酒山長在，看花鬢自衰。","誰堪登灞岸，還作舊鄉悲。"]', '["坐见春云暮，無因報所思。","川平人去远，日暖鴈飞遲。","对酒山长在，看花鬢自衰。","誰堪登灞岸，還作旧乡悲。"]', '诗', 'shi', '', NULL, '春日灞亭同苗員外寄皇甫侍御 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c44d1d7b-e055-4100-8dfd-3b4760edd8e4', '送顏推官遊銀夏謁韓大夫', '送顏推官游銀夏謁韓大夫', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["叢篁叫寒笛，滿眼塞山青。","才子尊前畫，將軍石上銘。","獵聲雲外響，戰血雨中腥。","苦樂從來事，因君一涕零。"]', '["叢篁叫寒笛，满眼塞山青。","才子尊前畫，將軍石上銘。","獵声云外响，戰血雨中腥。","苦乐從来事，因君一涕零。"]', '诗', 'shi', '', NULL, '送顏推官遊銀夏謁韓大夫 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dacfff7a-fffe-423e-9c52-14f2efccae80', '咸陽送房濟侍御歸太原幕', '咸陽送房濟侍御归太原幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["舊居無舊鄰，似見故鄉春。","復對別離酒，欲成衰老人。","客衣頻染淚，軍旅亦多塵。","握手重相勉，平生心所因。"]', '["旧居無旧鄰，似见故乡春。","复对別離酒，欲成衰老人。","客衣頻染泪，軍旅亦多塵。","握手重相勉，平生心所因。"]', '诗', 'shi', '', NULL, '咸陽送房濟侍御歸太原幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda04c39-322e-4e47-9a9c-9b5854795efb', '寶泉寺送李益端公歸邠寧幕', '寶泉寺送李益端公归邠寧幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["參差巖障東，雲日晃龍宮。","石淨非因雨，松涼不爲風。","戀泉將鶴並，偷果與猨同。","眼界塵雖染，心源蔽已通。","蓮花國何限，貝葉字無窮。","早晚登麟閣，慈門欲付公。"]', '["參差巖障东，云日晃龙宮。","石淨非因雨，松涼不爲风。","戀泉將鹤並，偷果與猨同。","眼界塵雖染，心源蔽已通。","蓮花国何限，貝葉字無窮。","早晚登麟閣，慈门欲付公。"]', '诗', 'shi', '', NULL, '寶泉寺送李益端公歸邠寧幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('357b89f6-fc6f-4aa2-b158-6da38f820c6b', '送何召下第後歸蜀', '送何召下第後归蜀', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["襃斜行客過，棧道響危空。","路濕雲初上，山明日正中。","水程通海貨，地利雜吳風。","一別金門遠，何人復薦雄。"]', '["襃斜行客過，棧道响危空。","路濕云初上，山明日正中。","水程通海貨，地利杂吳风。","一別金门远，何人复薦雄。"]', '诗', 'shi', '', NULL, '送何召下第後歸蜀 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d82fab-d24d-41ee-9547-b828eec2e945', '宿定陵寺', '宿定陵寺', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["古塔荒臺出禁牆，磬聲初盡漏聲長。","雲生紫殿幡花濕，月照青山松栢香。","禪室夜聞風過竹，奠筵朝啓露霑裳。","誰悟威靈同寂滅，更堪砧杵發昭陽。"]', '["古塔荒台出禁牆，磬声初尽漏声长。","云生紫殿幡花濕，月照青山松栢香。","禪室夜闻风過竹，奠筵朝啓露霑裳。","誰悟威靈同寂滅，更堪砧杵發昭陽。"]', '诗', 'shi', '', NULL, '宿定陵寺 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddf8afda-8f2c-4bbb-8180-7055321d4a6f', '送彭開府往雲中覲使君兄', '送彭开府往云中覲使君兄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["一門三代貴，非是主恩偏。","破虜山銘在，承家劍藝全。","奪旗貂帳側，射虎雪林前。","鴈塞逢兄弟，雲州發管弦。","凍河光帶日，枯草淨無煙。","儒者曾修武，因貽上將篇。"]', '["一门三代貴，非是主恩偏。","破虜山銘在，承家劍藝全。","奪旗貂帳側，射虎雪林前。","鴈塞逢兄弟，云州發管弦。","凍河光带日，枯草淨無煙。","儒者曾修武，因貽上將篇。"]', '诗', 'shi', '', NULL, '送彭開府往雲中覲使君兄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae03dbb4-7244-43ef-97a9-920813e9c679', '送李緗', '送李緗', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["舊國仍連五將營，儒衣何處謁公卿。","波翻遠水蒹葭動，路入寒村機杼鳴。","嵇康書論多歸興，謝氏家風有學名。","爲問西來雨中客，空山幾處是前程。"]', '["旧国仍連五將營，儒衣何处謁公卿。","波翻远水蒹葭动，路入寒村機杼鳴。","嵇康书論多归兴，謝氏家风有学名。","爲问西来雨中客，空山幾处是前程。"]', '诗', 'shi', '', NULL, '送李緗 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dba31336-8f07-4f4c-809f-06894ceb9ce5', '送內弟韋宗仁歸信州覲省', '送內弟韋宗仁归信州覲省', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["常嗟外族兄弟稀，轉覺心孤是送歸。","醉掩壺觴人有淚，夢驚波浪日無輝。","烹魚綠岸煙浮草，摘橘青溪露濕衣。","聞說江樓長卷幔，幾回風起望胡威。"]', '["常嗟外族兄弟稀，轉覺心孤是送归。","醉掩壺觴人有泪，梦驚波浪日無輝。","烹鱼綠岸煙浮草，摘橘青溪露濕衣。","闻说江楼长卷幔，幾回风起望胡威。"]', '诗', 'shi', '', NULL, '送內弟韋宗仁歸信州覲省 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87b6f483-98c5-4ec5-a715-87e36110e96b', '長安疾後首秋夜即事', '长安疾後首秋夜即事', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["九重深鎖禁城秋，月過南宮漸映樓。","紫陌夜深槐露滴，碧空雲盡火星流。","清風刻漏傳三殿，甲第歌鐘樂五侯。","楚客病來鄉思苦，寂寥燈下不勝愁。"]', '["九重深鎖禁城秋，月過南宮漸映楼。","紫陌夜深槐露滴，碧空云尽火星流。","清风刻漏傳三殿，甲第歌鐘乐五侯。","楚客病来乡思苦，寂寥灯下不勝愁。"]', '诗', 'shi', '', NULL, '長安疾後首秋夜即事 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d8d65c5-372c-4d4d-afae-5ada1d1ff2c7', '送崔琦赴宣州幕', '送崔琦赴宣州幕', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["五馬臨流待幕賓，羨君談笑出風塵。","身閑就養寧辭遠，世難移家莫厭貧。","天際曉山三峽路，津頭臘市九江人。","何處遙知最惆悵，滿湖青草鴈聲春。"]', '["五马臨流待幕賓，羨君談笑出风塵。","身闲就養寧辞远，世难移家莫厭貧。","天際晓山三峽路，津头臘市九江人。","何处遙知最惆悵，满湖青草鴈声春。"]', '诗', 'shi', '', NULL, '送崔琦赴宣州幕 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7eef0a3-b6c6-41bf-9943-ac00dc60f57a', '送楊皞東歸', '送楊皞东归', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["登樓掩泣話歸期，楚樹荆雲發遠思。","日裏揚帆聞戍鼓，舟中酹酒見山祠。","西江風浪何時盡，北客音書欲寄誰。","若說湓城楊司馬，知君望國有新詩。"]', '["登楼掩泣話归期，楚樹荆云發远思。","日裏揚帆闻戍鼓，舟中酹酒见山祠。","西江风浪何时尽，北客音书欲寄誰。","若说湓城楊司马，知君望国有新诗。"]', '诗', 'shi', '', NULL, '送楊皞東歸 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6846805b-01f3-442f-b7be-220466bd9c57', '至德中途中書事却寄李僴', '至德中途中书事却寄李僴', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["亂離無處不傷情，況復看碑對古城。","路遶寒山人獨去，月臨秋水鴈空驚。","顏衰重喜歸鄉國，身賤多慚問姓名。","今日主人還共醉，應憐世故一儒生。"]', '["亂離無处不傷情，況复看碑对古城。","路遶寒山人独去，月臨秋水鴈空驚。","顏衰重喜归乡国，身賤多慚问姓名。","今日主人還共醉，應怜世故一儒生。"]', '诗', 'shi', '', NULL, '至德中途中書事却寄李僴 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('776db07f-66d2-4776-bd49-70f44b8aa67f', '奉和太常王卿酬中書李舍人中書寓直春夜對月見寄', '奉和太常王卿酬中书李舍人中书寓直春夜对月见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["露如輕雨月如霜，不見星河見鴈行。","虛暈入池波自泛，滿輪當苑桂多香。","春臺幾望黃龍闕，雲路寧分白玉郎。","是夜巴歌應金石，豈殊螢影對清光。"]', '["露如轻雨月如霜，不见星河见鴈行。","虛暈入池波自泛，满輪當苑桂多香。","春台幾望黄龙闕，云路寧分白玉郎。","是夜巴歌應金石，豈殊螢影对清光。"]', '诗', 'shi', '', NULL, '奉和太常王卿酬中書李舍人中書寓直春夜對月見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dbaf1a5-195f-4924-845c-b61746bb3d3f', '詶包佶郎中覽拙卷後見寄', '詶包佶郎中覽拙卷後见寄', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["令伯支離晚讀書，豈知詞賦稱相如。","枉逢花木無新思，拙就溪潭損舊居。","禁路看山歌自緩，雲司玩月漏應疎。","沈憂敢望金門召，空媿巴歈並子虛。"]', '["令伯支離晚读书，豈知词賦稱相如。","枉逢花木無新思，拙就溪潭損旧居。","禁路看山歌自緩，云司玩月漏應疎。","沈憂敢望金门召，空媿巴歈並子虛。"]', '诗', 'shi', '', NULL, '詶包佶郎中覽拙卷後見寄 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23abc995-8b4c-4993-adc8-2ed76d03a09a', '送史寀滑州謁賈僕射', '送史寀滑州謁賈僕射', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["朱門洞啓儼行車，金鐍裝囊半是書。","君向東州問徐胤，羊公何事滅吹魚。"]', '["朱门洞啓儼行车，金鐍裝囊半是书。","君向东州问徐胤，羊公何事滅吹鱼。"]', '诗', 'shi', '', NULL, '送史寀滑州謁賈僕射 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90bab4dd-df1b-4079-9c1d-16b826f242ab', '送鮑中丞赴太原', '送鲍中丞赴太原', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["分路引鳴騶，喧喧似隴頭。","暫移西掖望，全解北門憂。","專幕臨都護，分曹制督郵。","積冰營不下，盛雪獵方休。","白草連胡帳，黃雲擁戍樓。","今朝送旌斾，一減魯儒羞。"]', '["分路引鳴騶，喧喧似隴头。","暫移西掖望，全解北门憂。","專幕臨都護，分曹制督郵。","積冰營不下，盛雪獵方休。","白草連胡帳，黄云擁戍楼。","今朝送旌斾，一減魯儒羞。"]', '诗', 'shi', '', NULL, '送鮑中丞赴太原 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02bb777a-fa66-4121-9551-be32bea452df', '送耿拾遺湋充括圖書使往江淮', '送耿拾遺湋充括圖书使往江淮', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["傳令收遺籍，諸儒喜餞君。","孔家唯有地，禹穴但生雲。","編簡知還續，蟲魚亦自分。","如逢北山隱，一爲謝移文。"]', '["傳令收遺籍，諸儒喜餞君。","孔家唯有地，禹穴但生云。","編簡知還續，蟲鱼亦自分。","如逢北山隐，一爲謝移文。"]', '诗', 'shi', '', NULL, '送耿拾遺湋充括圖書使往江淮 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('933c7d8b-2648-46ac-8159-f7788a50d6e6', '送郭判官赴振武', '送郭判官赴振武', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["黃河九曲流，繚繞古邊州。","鳴鴈飛初夜，羌胡正晚秋。","淒涼金管思，迢遰玉人愁。","七葉推多慶，須懷殺敵憂。"]', '["黄河九曲流，繚繞古邊州。","鳴鴈飞初夜，羌胡正晚秋。","淒涼金管思，迢遰玉人愁。","七葉推多慶，須懷殺敵憂。"]', '诗', 'shi', '', NULL, '送郭判官赴振武 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b1a00e-1ae0-42d5-9996-e5bf8beecbb6', '春江夕望', '春江夕望', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["洞庭芳草遍，楚客莫思歸。","經難人空老，逢春鴈自飛。","東西兄弟遠，存沒友朋稀。","獨立還垂淚，天南一布衣。"]', '["洞庭芳草遍，楚客莫思归。","經难人空老，逢春鴈自飞。","东西兄弟远，存沒友朋稀。","独立還垂泪，天南一布衣。"]', '诗', 'shi', '', NULL, '春江夕望 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2c41f70-3904-4f90-b029-bd8d00145d33', '送元昱尉義興', '送元昱尉義兴', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["欲成雲海別，一夜夢天涯。","白浪緣江雨，青山繞縣花。","風標當劇部，冠帶稱儒家。","去矣謝親愛，知予髮已華。"]', '["欲成云海別，一夜梦天涯。","白浪緣江雨，青山繞縣花。","风標當劇部，冠带稱儒家。","去矣謝親愛，知予髮已华。"]', '诗', 'shi', '', NULL, '送元昱尉義興 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf72563-5645-4422-a473-c3629ecfe6b5', '送黎兵曹往陝府結親', '送黎兵曹往陝府結親', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["郎馬兩如龍，春朝上路逢。","鴛鴦初集水，薜荔欲依松。","步帳歌聲轉，妝臺燭影重。","何言在陰者，得是戴侯宗。"]', '["郎马兩如龙，春朝上路逢。","鴛鴦初集水，薜荔欲依松。","步帳歌声轉，妝台燭影重。","何言在陰者，得是戴侯宗。"]', '诗', 'shi', '', NULL, '送黎兵曹往陝府結親 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a239b10c-5bf9-4567-b4e4-981c1cdccc2f', '送樂平苗明府', '送乐平苗明府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["累職比柴桑，清秋入楚鄉。","一船燈照浪，兩岸樹凝霜。","亭吏趨寒霧，山城斂曙光。","無辭折腰久，仲德在鴛行。"]', '["累職比柴桑，清秋入楚乡。","一船灯照浪，兩岸樹凝霜。","亭吏趨寒霧，山城斂曙光。","無辞折腰久，仲德在鴛行。"]', '诗', 'shi', '', NULL, '送樂平苗明府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a648ac2-fe66-438d-b082-2da34f651fe6', '晚到盩厔耆老家', '晚到盩厔耆老家', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["老翁曾舊識，相引出柴門。","苦話別時事，因尋溪上村。","數年何處客，近日幾家存。","冒雨看禾黍，逢人憶子孫。","亂藤穿井口，流水到籬根。","惆悵不堪住，空山月又昏。"]', '["老翁曾旧識，相引出柴门。","苦話別时事，因尋溪上村。","數年何处客，近日幾家存。","冒雨看禾黍，逢人憶子孫。","亂藤穿井口，流水到籬根。","惆悵不堪住，空山月又昏。"]', '诗', 'shi', '', NULL, '晚到盩厔耆老家 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6817cfc5-e3fb-4b7a-bfad-2c0834b25fbd', '臥病書懷', '臥病书懷', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["苦心三十載，白首遇艱難。","舊地成孤客，全家賴釣竿。","貌衰緣藥盡，起晚爲山寒。","老病今如此，無人更問看。"]', '["苦心三十載，白首遇艱难。","旧地成孤客，全家賴釣竿。","貌衰緣藥尽，起晚爲山寒。","老病今如此，無人更问看。"]', '诗', 'shi', '', NULL, '臥病書懷 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f9a289a-d34d-4eb2-b088-101ad715f873', '落第後歸終南別業', '落第後归終南別業', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["久爲名所誤，春盡始歸山。","落羽羞言命，逢人強破顏。","交疎貧病裏，身老是非間。","不及東溪月，漁翁夜往還。"]', '["久爲名所誤，春尽始归山。","落羽羞言命，逢人強破顏。","交疎貧病裏，身老是非间。","不及东溪月，漁翁夜往還。"]', '诗', 'shi', '', NULL, '落第後歸終南別業 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc7ab474-3bbf-45d3-8a4c-e93cb4f7cf26', '送朝邑張明府', '送朝邑張明府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["千室暮山西，浮雲與樹齊。","剖辭雲落紙，擁吏雪成泥。","野火蘆千頃，河田水萬畦。","不知琴月夜，誰得聽烏啼。"]', '["千室暮山西，浮云與樹齊。","剖辞云落紙，擁吏雪成泥。","野火蘆千頃，河田水万畦。","不知琴月夜，誰得听烏啼。"]', '诗', 'shi', '', NULL, '送朝邑張明府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf05512-c1a2-4b61-9003-836641e6d37a', '送李方東歸', '送李方东归', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["故交三四人，聞別共霑巾。","舉目是陳事，滿城無至親。","身從喪日病，家自儉年貧。","此去何堪遠，遺孤在舊鄰。"]', '["故交三四人，闻別共霑巾。","舉目是陳事，满城無至親。","身從喪日病，家自儉年貧。","此去何堪远，遺孤在旧鄰。"]', '诗', 'shi', '', NULL, '送李方東歸 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90fc2eea-4a5c-4bca-8720-23c04d7f523d', '秋晚霽後野望憶夏侯審', '秋晚霽後野望憶夏侯審', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["天晴禾黍平，暢目亦傷情。","野店雲日麗，孤莊砧杵鳴。","川原唯寂寞，岐路自縱橫。","前後無儔侶，此懷誰與呈。"]', '["天晴禾黍平，暢目亦傷情。","野店云日丽，孤莊砧杵鳴。","川原唯寂寞，岐路自縱橫。","前後無儔侶，此懷誰與呈。"]', '诗', 'shi', '', NULL, '秋晚霽後野望憶夏侯審 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d07bc17-063e-495e-bb05-f70bb9af671f', '送王尊師', '送王尊師', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["夢別一仙人，霞衣滿鶴身。","旌幢天路晚，桃杏海山春。","種玉非求稔，燒金不爲貧。","自憐頭白早，難與葛洪親。"]', '["梦別一仙人，霞衣满鹤身。","旌幢天路晚，桃杏海山春。","種玉非求稔，燒金不爲貧。","自怜头白早，难與葛洪親。"]', '诗', 'shi', '', NULL, '送王尊師 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eb449c7-94b0-48e5-a152-5037b4d7f78b', '送撫州周使君', '送撫州周使君', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["周郎三十餘，天子賜魚書。","龍節隨雲水，金鐃動里閭。","松聲三楚遠，鄉思百花初。","若轉弘農守，蕭咸事不如。"]', '["周郎三十餘，天子賜鱼书。","龙節隨云水，金鐃动里閭。","松声三楚远，乡思百花初。","若轉弘農守，蕭咸事不如。"]', '诗', 'shi', '', NULL, '送撫州周使君 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dffd705d-29d2-422f-883a-36ae86876fce', '贈別司空曙', '贈別司空曙', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["有月曾同賞，無秋不共悲。","如何與君別，又是菊花時。"]', '["有月曾同賞，無秋不共悲。","如何與君別，又是菊花时。"]', '诗', 'shi', '', NULL, '贈別司空曙 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8101e679-7510-483b-b032-75f6bfb5529d', '送王錄事赴任蘇州', '送王錄事赴任蘇州', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["古堤迎拜路，萬里一帆前。","潮作澆田雨，雲成煮海煙。","吏閑唯重法，俗富不憂邊。","西掖今宵詠，還應寄阿連。"]', '["古堤迎拜路，万里一帆前。","潮作澆田雨，云成煮海煙。","吏闲唯重法，俗富不憂邊。","西掖今宵詠，還應寄阿連。"]', '诗', 'shi', '', NULL, '送王錄事赴任蘇州 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bd2b585-be71-4b37-be22-a8ce63972b65', '大梵山寺院奉呈趣上人趙中丞', '大梵山寺院奉呈趣上人趙中丞', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["漸欲休人事，僧房學閉關。","伴魚浮水上，看鶴向林間。","寺古秋仍早，松深暮更閑。","月中隨道友，夜夜坐空山。"]', '["漸欲休人事，僧房学閉关。","伴鱼浮水上，看鹤向林间。","寺古秋仍早，松深暮更闲。","月中隨道友，夜夜坐空山。"]', '诗', 'shi', '', NULL, '大梵山寺院奉呈趣上人趙中丞 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1255db2-ff1c-49ff-b4b0-9914fbad280e', '送恆操上人歸江外覲省', '送恆操上人归江外覲省', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["依佛不違親，高堂與寺鄰。","問安雙樹曉，求膳一僧貧。","持呪過龍廟，翻經化海人。","還同惠休去，儒者亦霑巾。"]', '["依佛不違親，高堂與寺鄰。","问安雙樹晓，求膳一僧貧。","持呪過龙廟，翻經化海人。","還同惠休去，儒者亦霑巾。"]', '诗', 'shi', '', NULL, '送恆操上人歸江外覲省 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8592aae-e77c-4393-91b5-30a4db50c8e3', '上巳日陪齊相公花樓宴', '上巳日陪齊相公花楼宴', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["鍾陵暮春月，飛觀延羣英。","晨霞耀中軒，滿席羅金瓊。","持杯凝遠睇，觸物結幽情。","樹色參差綠，湖光瀲灩明。","禮卑瞻絳帳，恩浹廁華纓。","徒記山陰興，祓禊乃爲榮。"]', '["鍾陵暮春月，飞观延羣英。","晨霞耀中軒，满席羅金瓊。","持杯凝远睇，觸物結幽情。","樹色參差綠，湖光瀲灩明。","禮卑瞻絳帳，恩浹廁华纓。","徒記山陰兴，祓禊乃爲榮。"]', '诗', 'shi', '', NULL, '上巳日陪齊相公花樓宴 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64e506a0-6664-49b3-bd7d-826cc4629274', '寒食', '寒食', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["孤客飄飄歲載華，況逢寒食倍思家。","鶯啼遠墅多從柳，人哭荒墳亦有花。","濁水秦渠通渭急，黃埃京洛上原斜。","驅車西近長安好，宮觀參差半隱霞。"]', '["孤客飄飄歲載华，況逢寒食倍思家。","鶯啼远墅多從柳，人哭荒墳亦有花。","濁水秦渠通渭急，黄埃京洛上原斜。","驱车西近长安好，宮观參差半隐霞。"]', '诗', 'shi', '', NULL, '寒食 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6367bd53-1d65-492f-afae-57db79e5c812', '舟中寒食', '舟中寒食', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["寒食空江曲，孤舟渺水前。","鬬雞沙鳥異，禁火岸花然。","日霽開愁望，波喧警醉眠。","因看數莖鬢，倍欲惜芳年。"]', '["寒食空江曲，孤舟渺水前。","鬬雞沙鸟異，禁火岸花然。","日霽开愁望，波喧警醉眠。","因看數莖鬢，倍欲惜芳年。"]', '诗', 'shi', '', NULL, '舟中寒食 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2db743e-ffb6-4ad8-8afe-87d0b5a79633', '元日早朝呈故省諸公', '元日早朝呈故省諸公', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["萬戟淩霜布，森森瑞氣間。","垂衣當曉日，上壽對南山。","濟濟延多士，躚躚舞百蠻。","小臣無事諫，空愧伴鳴環。"]', '["万戟淩霜布，森森瑞氣间。","垂衣當晓日，上壽对南山。","濟濟延多士，躚躚舞百蠻。","小臣無事諫，空愧伴鳴环。"]', '诗', 'shi', '', NULL, '元日早朝呈故省諸公 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f637cfe-2766-4d58-925a-fe3e4ae6b864', '元日朝迴中夜書情寄南宮二故人', '元日朝迴中夜书情寄南宮二故人', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["鳴珮隨鵷鷺，登堦見冕旒。","無能裨聖代，何事別滄洲。","閑夜貧還醉，浮名老漸羞。","鳳城春欲晚，郎吏憶同遊。"]', '["鳴珮隨鵷鷺，登堦见冕旒。","無能裨聖代，何事別滄洲。","闲夜貧還醉，浮名老漸羞。","鳳城春欲晚，郎吏憶同游。"]', '诗', 'shi', '', NULL, '元日朝迴中夜書情寄南宮二故人 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2072e6c8-0902-4c2b-aa89-9fc077a928c2', '裴給事宅白牡丹', '裴給事宅白牡丹', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["長安豪貴惜春殘，爭翫街西紫牡丹。","別有玉盤承露冷，無人起就月中看。"]', '["长安豪貴惜春殘，爭翫街西紫牡丹。","別有玉盤承露冷，無人起就月中看。"]', '诗', 'shi', '', NULL, '裴給事宅白牡丹 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95551421-c7e5-4b3b-9524-2b16e2adfffb', '送韋判官得雨中山', '送韋判官得雨中山', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["前峰後嶺碧濛濛，草擁驚泉樹帶風。","人語馬嘶聽不得，更堪長路在雲中。"]', '["前峰後嶺碧濛濛，草擁驚泉樹带风。","人語马嘶听不得，更堪长路在云中。"]', '诗', 'shi', '', NULL, '送韋判官得雨中山 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9d13a9-948b-485d-ad51-4f562bcddd7a', '送宛丘任少府', '送宛丘任少府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["帶綬別鄉親，東爲千里人。","俗訛唯競祭，地古不留春。","野戍雲藏火，軍城樹擁塵。","少年何所重，才子又清貧。"]', '["带綬別乡親，东爲千里人。","俗訛唯競祭，地古不留春。","野戍云藏火，軍城樹擁塵。","少年何所重，才子又清貧。"]', '诗', 'shi', '', NULL, '送宛丘任少府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7116858-e5b8-49df-a243-7e9b469fd55d', '送永陽崔明府', '送永陽崔明府', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["鶴唳蒹葭曉，中流見楚城。","浪清風乍息，山白月猶明。","廢路開荒木，歸人種古營。","懸聞正訛俗，邴曼更知名。"]', '["鹤唳蒹葭晓，中流见楚城。","浪清风乍息，山白月猶明。","廢路开荒木，归人種古營。","懸闻正訛俗，邴曼更知名。"]', '诗', 'shi', '', NULL, '送永陽崔明府 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19710654-694f-4c8b-a46f-7eaf13ff8570', '割飛二刀子歌', '割飞二刀子歌', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["我家有翦刀，人云鬼國鐵。","裁羅裁綺無鈍時，用來三年一股折。","南中匠人淳用鋼，再令盤屈隨手傷。","改鍛割飛二刀子，色迎霽雪鋒含霜。","兩條神物秋冰薄，刃淬初蟾鞘金錯。","越戟吳鉤不足誇，斬犀切玉應懷怍。","日試曾磨漢水邊，掌中恄慄聲冷然。","神驚魄悸却收得，刃頭已吐微微煙。","刀乎刀乎何燁燁，魑魅須藏怪須懾。","若非良工變爾形，只向裁縫委箱篋。"]', '["我家有翦刀，人云鬼国鐵。","裁羅裁綺無鈍时，用来三年一股折。","南中匠人淳用鋼，再令盤屈隨手傷。","改鍛割飞二刀子，色迎霽雪鋒含霜。","兩條神物秋冰薄，刃淬初蟾鞘金錯。","越戟吳鉤不足誇，斬犀切玉應懷怍。","日試曾磨漢水邊，掌中恄慄声冷然。","神驚魄悸却收得，刃头已吐微微煙。","刀乎刀乎何燁燁，魑魅須藏怪須懾。","若非良工变爾形，只向裁縫委箱篋。"]', '诗', 'shi', '', NULL, '割飛二刀子歌 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95282845-ccd2-4adb-983d-c05d7bd69b1d', '送郎士元使君赴郢州', '送郎士元使君赴郢州', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["賜衣兼授節，行日郢中聞。","花發登山廟，天晴閱水軍。","漁商三楚接，郡邑九江分。","高興應難遂，元戎有大勳。"]', '["賜衣兼授節，行日郢中闻。","花發登山廟，天晴閱水軍。","漁商三楚接，郡邑九江分。","高兴應难遂，元戎有大勳。"]', '诗', 'shi', '', NULL, '送郎士元使君赴郢州 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0732778-7a5f-428b-b5dd-3b0d4b6b4d57', '春詞', '春词', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["北苑羅裙帶，塵衢錦繡鞵。","醉眠芳樹下，半被落花埋。"]', '["北苑羅裙带，塵衢錦繡鞵。","醉眠芳樹下，半被落花埋。"]', '诗', 'shi', '', NULL, '春詞 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0522c67c-f6ed-413b-8e0f-03b1f1d2c8bf', '清如玉壺冰', '清如玉壺冰', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉壺冰始結，循吏政初成。","既有虛心鑒，還如照膽清。","瑤池慙洞澈，金鏡讓澄明。","氣若朝霜動，形隨夜月盈。","臨人能不蔽，待物本無情。","怯對圓光裹，妍蚩自此呈。"]', '["玉壺冰始結，循吏政初成。","既有虛心鑒，還如照膽清。","瑤池慙洞澈，金镜讓澄明。","氣若朝霜动，形隨夜月盈。","臨人能不蔽，待物本無情。","怯对圓光裹，妍蚩自此呈。"]', '诗', 'shi', '', NULL, '清如玉壺冰 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('682673fa-3fe9-4902-bb0a-0588c23ec54e', '山店', '山店', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["登登山路行時盡，決決溪泉到處聞。","風動葉聲山犬吠，一家松火隔秋雲。"]', '["登登山路行时尽，決決溪泉到处闻。","风动葉声山犬吠，一家松火隔秋云。"]', '诗', 'shi', '', NULL, '山店 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6efc7239-d114-47bd-b94d-f5742d60101b', '長至日上公獻壽', '长至日上公獻壽', 'dbf89aa8-7655-4680-9d06-a1a994e27938', '唐', '["應律三陽首，朝天萬國同。","斗邊看子月，臺上候祥風。","五夜鐘初動，千門日正融。","玉階文物盛，仙仗武貔雄。","率舞皆羣辟，稱觴即上公。","南山爲聖壽，長對未央宮。"]', '["應律三陽首，朝天万国同。","斗邊看子月，台上候祥风。","五夜鐘初动，千门日正融。","玉階文物盛，仙仗武貔雄。","率舞皆羣辟，稱觴即上公。","南山爲聖壽，长对未央宮。"]', '诗', 'shi', '', NULL, '長至日上公獻壽 崔琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('276ff801-6047-46aa-9382-61cb0b824e5d', '長至日上公獻壽', '长至日上公獻壽', '9a4c0bf6-7794-4609-9481-6f878544ac01', '唐', '["候曉金門闢，乘時玉曆長。","羽儀瞻上宰，雲物麗初陽。","漢禮方傳珮，堯年正捧觴。","日行臨觀闕，帝錫洽珪璋。","盛美超三代，洪休降百祥。","自憐朝末坐，空此詠無[疆]。"]', '["候晓金门闢，乘时玉曆长。","羽儀瞻上宰，云物丽初陽。","漢禮方傳珮，堯年正捧觴。","日行臨观闕，帝錫洽珪璋。","盛美超三代，洪休降百祥。","自怜朝末坐，空此詠無[疆]。"]', '诗', 'shi', '', NULL, '長至日上公獻壽 李竦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d7e9ee-237a-4b42-b9a8-bf55b3c66246', '賦得西戎獻白玉環', '賦得西戎獻白玉环', '9a4c0bf6-7794-4609-9481-6f878544ac01', '唐', '["當時無外守，方物四夷通。","列土金河北，朝天玉塞東。","自將荆璞比，不與鄭環同。","正朔雖傳漢，衣冠尚帶戎。","幸承提佩寵，多媿琢磨功。","絕域知文教，爭趨上國風。"]', '["當时無外守，方物四夷通。","列土金河北，朝天玉塞东。","自將荆璞比，不與鄭环同。","正朔雖傳漢，衣冠尚带戎。","幸承提佩寵，多媿琢磨功。","絕域知文教，爭趨上国风。"]', '诗', 'shi', '', NULL, '賦得西戎獻白玉環 李竦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('489af613-f3cc-42ad-b304-a4f928917a4e', '新安江行', '新安江行', '5b0dc02e-ee8a-4516-af66-a998dc4be4e5', '唐', '["江源南去永，野渡暫維梢。","古戍懸魚網，空林露鳥巢。","雪晴山脊見，沙淺浪痕交。","自笑無媒者，逢人作解嘲。"]', '["江源南去永，野渡暫維梢。","古戍懸鱼網，空林露鸟巢。","雪晴山脊见，沙淺浪痕交。","自笑無媒者，逢人作解嘲。"]', '诗', 'shi', '', NULL, '新安江行 章八元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d371211-04bf-43d5-a5fd-39d664a176b7', '酬劉員外月下見寄', '酬劉員外月下见寄', '5b0dc02e-ee8a-4516-af66-a998dc4be4e5', '唐', '["夜涼河漢白，卷箔出南軒。","過月鴻爭遠，辭枝葉暗翻。","獨謠聞麗曲，緩步接清言。","宣室思前席，行看拜主恩。"]', '["夜涼河漢白，卷箔出南軒。","過月鴻爭远，辞枝葉暗翻。","独謠闻丽曲，緩步接清言。","宣室思前席，行看拜主恩。"]', '诗', 'shi', '', NULL, '酬劉員外月下見寄 章八元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c228217-7f18-441d-9c3b-539338458cf9', '寄都官劉員外', '寄都官劉員外', '5b0dc02e-ee8a-4516-af66-a998dc4be4e5', '唐', '["舊宅平津邸，槐陰接漢宮。","鳴騶馳道上，寒日直廬中。","白雪歌偏麗，青雲宦早通。","悠然一縫掖，千里限清風。"]', '["旧宅平津邸，槐陰接漢宮。","鳴騶驰道上，寒日直廬中。","白雪歌偏丽，青云宦早通。","悠然一縫掖，千里限清风。"]', '诗', 'shi', '', NULL, '寄都官劉員外 章八元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82531fb-9915-49a7-bb2d-0fc4cec6fd2f', '題慈恩寺塔', '題慈恩寺塔', '5b0dc02e-ee8a-4516-af66-a998dc4be4e5', '唐', '["十層突兀在虛空，四十門開面面風。","却怪鳥飛平地上，自驚人語半天中。","迴梯暗踏如穿洞，絕頂初攀似出籠。","落日鳳城佳氣合，滿城春樹雨濛濛。"]', '["十層突兀在虛空，四十门开面面风。","却怪鸟飞平地上，自驚人語半天中。","迴梯暗踏如穿洞，絕頂初攀似出籠。","落日鳳城佳氣合，满城春樹雨濛濛。"]', '诗', 'shi', '', NULL, '題慈恩寺塔 章八元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f350588-b1b6-455d-b871-e6703f228cea', '歸桐廬舊居寄嚴長史', '归桐廬旧居寄嚴长史', '5b0dc02e-ee8a-4516-af66-a998dc4be4e5', '唐', '["昨辭夫子櫂歸舟，家在桐廬憶舊丘。","三月暖時花競發，兩溪分處水爭流。","近聞江老傳鄉語，遙見家山減旅愁。","或在醉中逢夜雪，懷賢應向剡川遊。"]', '["昨辞夫子櫂归舟，家在桐廬憶旧丘。","三月暖时花競發，兩溪分处水爭流。","近闻江老傳乡語，遙见家山減旅愁。","或在醉中逢夜雪，懷賢應向剡川游。"]', '诗', 'shi', '', NULL, '歸桐廬舊居寄嚴長史 章八元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90dbe859-93fb-4ccb-a5b0-1896eb2da0bb', '天台道中示同行', '天台道中示同行', '5b0dc02e-ee8a-4516-af66-a998dc4be4e5', '唐', '["八重巖崿疊晴空，九色煙霞遶洞宮。","仙道多因迷路得，莫將心事問樵翁。"]', '["八重巖崿叠晴空，九色煙霞遶洞宮。","仙道多因迷路得，莫將心事问樵翁。"]', '诗', 'shi', '', NULL, '天台道中示同行 章八元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a6a438f-ee84-40e8-8e66-56ccc4ace6df', '元日望含元殿御扇開合', '元日望含元殿御扇开合', '5b0dc02e-ee8a-4516-af66-a998dc4be4e5', '唐', '["萬國來朝歲，千年覲聖君。","輦迎仙杖出，扇匝御香焚。","俯對朝容近，先知曙色分。","冕旒開處見，鐘磬合時聞。","影動承朝日，花攢似慶雲。","蒲葵那可比，徒用隔炎氛。"]', '["万国来朝歲，千年覲聖君。","輦迎仙杖出，扇匝御香焚。","俯对朝容近，先知曙色分。","冕旒开处见，鐘磬合时闻。","影动承朝日，花攢似慶云。","蒲葵那可比，徒用隔炎氛。"]', '诗', 'shi', '', NULL, '元日望含元殿御扇開合 章八元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('732defb7-3b46-41cb-b01f-6b77a1bb875b', '清明日賜百僚新火', '清明日賜百僚新火', '2e9cce7c-3eae-4c10-8c6b-e5ad9a6b6d15', '唐', '["上苑連侯第，清明及暮春。","九天初改火，萬井屬良辰。","頒賜恩逾洽，承時慶自均。","翠煙和柳嫩，紅焰出花新。","寵命尊三老，祥光燭萬人。","太平當此日，空復荷陶甄。"]', '["上苑連侯第，清明及暮春。","九天初改火，万井屬良辰。","頒賜恩逾洽，承时慶自均。","翠煙和柳嫩，紅焰出花新。","寵命尊三老，祥光燭万人。","太平當此日，空复荷陶甄。"]', '诗', 'shi', '', NULL, '清明日賜百僚新火 史延 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7648c0c-9b9c-48ce-8737-a857b49d55c4', '清明日賜百僚新火', '清明日賜百僚新火', '1a6fbb32-4933-4f17-b5c4-4c4a1e983d2e', '唐', '["朱騎傳紅燭，天廚賜近臣。","火隨黃道見，煙遶白榆新。","榮耀分他日，恩光共此辰。","更調金鼎膳，還暖玉堂人。","灼灼千門曉，輝輝萬井春。","應憐螢聚夜，瞻望及東鄰。"]', '["朱騎傳紅燭，天廚賜近臣。","火隨黄道见，煙遶白榆新。","榮耀分他日，恩光共此辰。","更調金鼎膳，還暖玉堂人。","灼灼千门晓，輝輝万井春。","應怜螢聚夜，瞻望及东鄰。"]', '诗', 'shi', '', NULL, '清明日賜百僚新火 韓濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c7fe215-f78d-409a-ad00-d0c425df5775', '清明日賜百僚新火', '清明日賜百僚新火', '1a6fbb32-4933-4f17-b5c4-4c4a1e983d2e', '唐', '["改火清明後，優恩賜近臣。","漏殘丹禁晚，燧發白榆新。","瑞彩來雙闕，神光煥四鄰。","氣回侯第暖，煙散帝城春。","利用調羹鼎，餘輝燭縉紳。","皇明如照隱，願及聚螢人。"]', '["改火清明後，優恩賜近臣。","漏殘丹禁晚，燧發白榆新。","瑞彩来雙闕，神光煥四鄰。","氣回侯第暖，煙散帝城春。","利用調羹鼎，餘輝燭縉紳。","皇明如照隐，願及聚螢人。"]', '诗', 'shi', '', NULL, '清明日賜百僚新火 韓濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07921a7f-dd01-4929-852f-8b2d6d213b34', '清明日賜百僚新火', '清明日賜百僚新火', '1a6fbb32-4933-4f17-b5c4-4c4a1e983d2e', '唐', '["御火傳香殿，華光及侍臣。","星流中使馬，燭耀九衢人。","轉影連金屋，分輝麗錦茵。","焰迎紅蘂發，煙染綠條春。","助律和風早，添爐煖氣新。","誰憐一寒士，猶望照東鄰。"]', '["御火傳香殿，华光及侍臣。","星流中使马，燭耀九衢人。","轉影連金屋，分輝丽錦茵。","焰迎紅蘂發，煙染綠條春。","助律和风早，添爐煖氣新。","誰怜一寒士，猶望照东鄰。"]', '诗', 'shi', '', NULL, '清明日賜百僚新火 韓濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09615497-a813-43c2-bcd9-39dc6d386646', '投珠於泉', '投珠於泉', '8a36ddcf-4d54-4a44-bef5-27c08536f142', '唐', '["至道歸淳樸，明珠被棄捐。","天真來照乘，成性却沈泉。","不是靈蛇吐，非緣合浦還。","岸傍隨月落，波底共星懸。","致遠終無脛，懷貪遂息肩。","欲知恭儉德，所寶在惟賢。"]', '["至道归淳樸，明珠被棄捐。","天真来照乘，成性却沈泉。","不是靈蛇吐，非緣合浦還。","岸傍隨月落，波底共星懸。","致远終無脛，懷貪遂息肩。","欲知恭儉德，所寶在惟賢。"]', '诗', 'shi', '', NULL, '投珠於泉 獨孤綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41960329-86d2-4636-83cf-80292b6d1bb9', '秦鏡', '秦镜', '8a36ddcf-4d54-4a44-bef5-27c08536f142', '唐', '["萬古秦時鏡，從來抱至精。","依臺月自吐，在匣水常清。","爛爛金光發，澄澄物象生。","雲天皆洞鑒，表裏盡虛明。","但見人窺膽，全勝響應聲。","妍媸定可識，何處更逃情。"]', '["万古秦时镜，從来抱至精。","依台月自吐，在匣水常清。","爛爛金光發，澄澄物象生。","云天皆洞鑒，表裏尽虛明。","但见人窺膽，全勝响應声。","妍媸定可識，何处更逃情。"]', '诗', 'shi', '', NULL, '秦鏡 獨孤綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0aea48b-98b5-42de-8986-3d2e80540dd5', '秦鏡', '秦镜', 'acea7b94-3aae-4ae7-a693-289c02e9c754', '唐', '["樓上秦時鏡，千秋獨有名。","菱花寒不落，冰質夏長清。","龍在形難掩，人來膽易呈。","昇臺宜遠照，開匣乍藏明。","皎色新磨出，圓規舊鑄成。","愁容如可鑒，當欲拂塵纓。"]', '["楼上秦时镜，千秋独有名。","菱花寒不落，冰質夏长清。","龙在形难掩，人来膽易呈。","昇台宜远照，开匣乍藏明。","皎色新磨出，圓規旧鑄成。","愁容如可鑒，當欲拂塵纓。"]', '诗', 'shi', '', NULL, '秦鏡 張佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b8ded04-d94a-4096-abd3-73993cce7fcf', '憶遊天台寄道流', '憶游天台寄道流', 'acea7b94-3aae-4ae7-a693-289c02e9c754', '唐', '["憶昨天台到赤城，幾朝仙籟耳中生。","雲龍出水風聲急，海鶴鳴臯日色清。","石笋半山移步險，桂花當澗拂衣輕。","今來盡是人間夢，劉阮茫茫何處行。"]', '["憶昨天台到赤城，幾朝仙籟耳中生。","云龙出水风声急，海鹤鳴臯日色清。","石笋半山移步險，桂花當澗拂衣轻。","今来尽是人间梦，劉阮茫茫何处行。"]', '诗', 'shi', '', NULL, '憶遊天台寄道流 張佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e3f5d61-6068-4103-b470-5bccf1eb5127', '龜負圖', '龟負圖', 'acea7b94-3aae-4ae7-a693-289c02e9c754', '唐', '["天意將垂象，神龜出負圖。","五方行有配，八卦義寧孤。","作瑞旌君德，披文叶帝謨。","乘流喜得路，逢聖幸存軀。","蓮葉池通泛，桃花水自浮。","還尋九江去，安肯曳泥途。"]', '["天意將垂象，神龟出負圖。","五方行有配，八卦義寧孤。","作瑞旌君德，披文叶帝謨。","乘流喜得路，逢聖幸存軀。","蓮葉池通泛，桃花水自浮。","還尋九江去，安肯曳泥途。"]', '诗', 'shi', '', NULL, '龜負圖 張佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ad6062-6360-4804-8a85-e123e41c7058', '上元日夢王母獻白玉環', '上元日梦王母獻白玉环', 'acea7b94-3aae-4ae7-a693-289c02e9c754', '唐', '["夢中朝上日，闕下拜天顏。","彷彿瞻王母，分明獻玉環。","靈姿趨甲帳，悟道契玄關。","似見霜姿白，如看月彩彎。","霓裳歸物外，鳳曆曉人寰。","仙聖非相遠，昭昭寤寐間。"]', '["梦中朝上日，闕下拜天顏。","彷彿瞻王母，分明獻玉环。","靈姿趨甲帳，悟道契玄关。","似见霜姿白，如看月彩彎。","霓裳归物外，鳳曆晓人寰。","仙聖非相远，昭昭寤寐间。"]', '诗', 'shi', '', NULL, '上元日夢王母獻白玉環 張佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2a1bfc-9b0c-48ef-a5f1-c6a028bc0837', '良田無晚歲', '良田無晚歲', 'acea7b94-3aae-4ae7-a693-289c02e9c754', '唐', '["人功雖未及，地力信非常。","不任耕耘早，偏宜黍稷良。","無年皆有獲，後種亦先芳。","膴膴盈千畝，青青保萬箱。","何須祭田祖，詎要察農祥。","況是春三月，和風日又長。"]', '["人功雖未及，地力信非常。","不任耕耘早，偏宜黍稷良。","無年皆有獲，後種亦先芳。","膴膴盈千畝，青青保万箱。","何須祭田祖，詎要察農祥。","況是春三月，和风日又长。"]', '诗', 'shi', '', NULL, '良田無晚歲 張佐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1595f1a9-d8fb-4b39-a406-c242b0e47ba7', '下第獻座主張謂', '下第獻座主張謂', 'c60fe377-37f3-4c8f-9068-8d09d75e0f34', '唐', '["謇諤王臣直，文明雅量全。","望爐金自躍，應物鏡何偏。","南國幽沈盡，東堂禮樂宣。","轉令遊藝士，更惜至公年。","芳樹歡新景，青雲泣暮天。","唯愁鳳池拜，孤賤更誰憐。"]', '["謇諤王臣直，文明雅量全。","望爐金自躍，應物镜何偏。","南国幽沈尽，东堂禮乐宣。","轉令游藝士，更惜至公年。","芳樹歡新景，青云泣暮天。","唯愁鳳池拜，孤賤更誰怜。"]', '诗', 'shi', '', NULL, '下第獻座主張謂 閻濟美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b39ea5db-c0a2-4ff9-8f7c-a77e66c902fe', '天津橋望洛城殘雪', '天津橋望洛城殘雪', 'c60fe377-37f3-4c8f-9068-8d09d75e0f34', '唐', '["新霽洛城端，千家積雪寒。","未收清禁色，偏向上陽殘。"]', '["新霽洛城端，千家積雪寒。","未收清禁色，偏向上陽殘。"]', '诗', 'shi', '', NULL, '天津橋望洛城殘雪 閻濟美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67390431-5c05-4de2-8fbc-2fbe19f363b2', '尚書郎上直聞春漏', '尚书郎上直闻春漏', '4bd1f273-d105-402d-be52-8441de25669c', '唐', '["建禮含香處，重城待漏辰。","徐聲傳鳳闕，曉唱辨雞人。","銀箭聽將盡，銅壺滴更新。","催籌當五夜，移刻及三春。","杳杳從天遠，泠泠出禁頻。","直廬殘響曙，肅穆對鉤陳。"]', '["建禮含香处，重城待漏辰。","徐声傳鳳闕，晓唱辨雞人。","銀箭听將尽，銅壺滴更新。","催籌當五夜，移刻及三春。","杳杳從天远，泠泠出禁頻。","直廬殘响曙，肅穆对鉤陳。"]', '诗', 'shi', '', NULL, '尚書郎上直聞春漏 張少博 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fa31522-6b7d-4c10-b9a4-ee278d17a714', '雪夜觀象闕待漏', '雪夜观象闕待漏', '4bd1f273-d105-402d-be52-8441de25669c', '唐', '["殘雪初睛後，鳴珂奉闕庭。","九門傳曉漏，五夜候晨扃。","北斗橫斜漢，東方落曙星。","煙氛初動色，簪佩未分形。","雪重猶垂白，山遙不辨青。","雞人更唱處，偏入此時聽。"]', '["殘雪初睛後，鳴珂奉闕庭。","九门傳晓漏，五夜候晨扃。","北斗橫斜漢，东方落曙星。","煙氛初动色，簪佩未分形。","雪重猶垂白，山遙不辨青。","雞人更唱处，偏入此时听。"]', '诗', 'shi', '', NULL, '雪夜觀象闕待漏 張少博 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0837426-530d-494d-aa6f-65251b567723', '尚書郎上直聞春漏', '尚书郎上直闻春漏', 'e97477c6-f4ed-4f9b-b088-c7d3827397df', '唐', '["建禮通華省，含香直紫宸。","靜聞銅史漏，暗識桂宮春。","滴瀝疑將絕，清泠發更新。","寒聲臨鴈沼，疎韻應雞人。","迥入千門徹，行催五夜頻。","高臺閑自聽，非是駐征輪。"]', '["建禮通华省，含香直紫宸。","静闻銅史漏，暗識桂宮春。","滴瀝疑將絕，清泠發更新。","寒声臨鴈沼，疎韻應雞人。","迥入千门徹，行催五夜頻。","高台闲自听，非是駐征輪。"]', '诗', 'shi', '', NULL, '尚書郎上直聞春漏 周徹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128d20fe-45cc-41dc-8fd2-681d12c4d178', '及第後贈試官', '及第後贈試官', '2cd05daf-a7ee-4cd5-b509-98cf93a453dc', '唐', '["公子求賢未識真，欲將毛遂比常倫。","當時不及三千客，今日何如十九人。"]', '["公子求賢未識真，欲將毛遂比常倫。","當时不及三千客，今日何如十九人。"]', '诗', 'shi', '', NULL, '及第後贈試官 高拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a23377a-f7fc-46c8-adae-1c1c24983c9e', '賦得花發上林', '賦得花發上林', 'd4866ab4-ab56-404f-b529-cad2db88c50f', '唐', '["御苑春何早，繁花已繡林。","笑迎明主仗，香拂美人簪。","地接樓臺近，天垂雨露深。","晴光來戲蝶，夕景動棲禽。","欲托凌雲勢，先開捧日心。","方知桃李樹，從此別成陰。"]', '["御苑春何早，繁花已繡林。","笑迎明主仗，香拂美人簪。","地接楼台近，天垂雨露深。","晴光来戲蝶，夕景动棲禽。","欲托凌云勢，先开捧日心。","方知桃李樹，從此別成陰。"]', '诗', 'shi', '', NULL, '賦得花發上林 王表 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9ff4727-4dec-4fd8-ab61-336c693af7c3', '清明日登城春望寄大夫使君', '清明日登城春望寄大夫使君', 'd4866ab4-ab56-404f-b529-cad2db88c50f', '唐', '["春城閑望愛睛天，何處風光不眼前。","寒食花開千樹雪，清明日出萬家煙。","興來促席唯同舍，醉後狂歌盡少年。","聞說鶯啼却惆悵，詩成不見謝臨川。"]', '["春城闲望愛睛天，何处风光不眼前。","寒食花开千樹雪，清明日出万家煙。","兴来促席唯同舍，醉後狂歌尽少年。","闻说鶯啼却惆悵，诗成不见謝臨川。"]', '诗', 'shi', '', NULL, '清明日登城春望寄大夫使君 王表 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a5ff18-3608-4a2e-8303-9bce326fe4f4', '成德樂', '成德乐', 'd4866ab4-ab56-404f-b529-cad2db88c50f', '唐', '["趙女乘春上畫樓，一聲歌發滿城秋。","無端更唱關山曲，不是征人亦淚流。"]', '["趙女乘春上畫楼，一声歌發满城秋。","無端更唱关山曲，不是征人亦泪流。"]', '诗', 'shi', '', NULL, '成德樂 王表 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07539a31-da11-4f18-a70f-8218274f6e23', '花發上林', '花發上林', 'e05a0ff3-8606-4387-af92-bb81f4a934fa', '唐', '["上苑韶容早，芳菲正吐花。","無言向春日，閑笑任年華。","潤色籠輕靄，睛光豔晚霞。","影連千戶竹，香散萬人家。","幸遶樓臺近，仍懷雨露賒。","願君垂採摘，不使落風沙。"]', '["上苑韶容早，芳菲正吐花。","無言向春日，闲笑任年华。","潤色籠轻靄，睛光豔晚霞。","影連千戶竹，香散万人家。","幸遶楼台近，仍懷雨露賒。","願君垂採摘，不使落风沙。"]', '诗', 'shi', '', NULL, '花發上林 獨孤授 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f20723e8-6704-4fad-8888-66ca7ddda248', '賦得花發上林', '賦得花發上林', '37c2fe61-18dd-42b0-a298-0f7d648edc87', '唐', '["東陸和風至，先開上苑花。","穠枝藏宿鳥，香蘂拂行車。","散白憐睛日，舒紅愛晚霞。","桃間留御馬，梅處入胡笳。","城郭連增媚，樓臺映轉華。","豈同幽谷草，春至發猶賒。"]', '["东陸和风至，先开上苑花。","穠枝藏宿鸟，香蘂拂行车。","散白怜睛日，舒紅愛晚霞。","桃间留御马，梅处入胡笳。","城郭連增媚，楼台映轉华。","豈同幽谷草，春至發猶賒。"]', '诗', 'shi', '', NULL, '賦得花發上林 王儲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32b0c752-58ae-419d-abc2-c4bbc69e0632', '賦得花發上林', '賦得花發上林', 'a6234b1b-a192-473e-98ba-753daf76e535', '唐', '["灼灼花凝雪，春來發上林。","向風初散蘂，垂葉欲成陰。","人過香隨遠，煙晴色自深。","淨時空結霧，疎處未藏禽。","菶茸何年植，間關幾日吟。","一枝如可冀，不負折芳心。"]', '["灼灼花凝雪，春来發上林。","向风初散蘂，垂葉欲成陰。","人過香隨远，煙晴色自深。","淨时空結霧，疎处未藏禽。","菶茸何年植，间关幾日吟。","一枝如可冀，不負折芳心。"]', '诗', 'shi', '', NULL, '賦得花發上林 周渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('022a1d72-1028-493e-897e-42b6cdb47e84', '贈龍興觀主吳崇岳', '贈龙兴观主吳崇岳', 'a6234b1b-a192-473e-98ba-753daf76e535', '唐', '["楮爲冠子布爲裳，吞得丹霞壽最長。","混俗性靈常樂道，出塵風格早休糧。","枕中經妙誰傳與，肘後方新自寫將。","百尺松梢幾飛步，鶴棲板上禮虛皇。"]', '["楮爲冠子布爲裳，吞得丹霞壽最长。","混俗性靈常乐道，出塵风格早休糧。","枕中經妙誰傳與，肘後方新自寫將。","百尺松梢幾飞步，鹤棲板上禮虛皇。"]', '诗', 'shi', '', NULL, '贈龍興觀主吳崇岳 周渭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('515db1b8-0e77-479d-b284-337960ed594c', '從軍有苦樂行', '從軍有苦乐行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["勞者且莫歌，我欲送君觴。","從軍有苦樂，此曲樂未央。","僕居在隴上，隴水斷人腸。","東過秦宮路，宮路入咸陽。","時逢漢帝出，諫獵至長楊。","詎馳遊俠窟，非結少年場。","一旦承嘉惠，輕身重恩光。","秉筆參帷帟，從軍至朔方。","邊地多陰風，草木自淒涼。","斷絕海雲去，出沒胡沙長。","參差引雁翼，隱轔騰軍裝。","劒文夜如水，馬汗凍成霜。","俠氣五都少，矜功六郡良。","山河起目前，睚眥死路傍。","北逐驅獯虜，西臨復舊疆。","昔還賦餘資，今出乃贏糧。","一矢弢夏服，我弓不再張。","寄語丈夫雄，苦樂身自當。"]', '["勞者且莫歌，我欲送君觴。","從軍有苦乐，此曲乐未央。","僕居在隴上，隴水斷人腸。","东過秦宮路，宮路入咸陽。","时逢漢帝出，諫獵至长楊。","詎驰游俠窟，非結少年場。","一旦承嘉惠，轻身重恩光。","秉笔參帷帟，從軍至朔方。","邊地多陰风，草木自淒涼。","斷絕海云去，出沒胡沙长。","參差引雁翼，隐轔腾軍裝。","劒文夜如水，马汗凍成霜。","俠氣五都少，矜功六郡良。","山河起目前，睚眥死路傍。","北逐驱獯虜，西臨复旧疆。","昔還賦餘資，今出乃贏糧。","一矢弢夏服，我弓不再張。","寄語丈夫雄，苦乐身自當。"]', '诗', 'shi', '', NULL, '從軍有苦樂行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9fa15f5-c7ac-40b3-998f-6ae03ba52122', '登長城', '登长城', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["漢家今上郡，秦塞古長城。","有日雲長慘，無風沙自驚。","當今聖天子，不戰四夷平。"]', '["漢家今上郡，秦塞古长城。","有日云长慘，無风沙自驚。","當今聖天子，不戰四夷平。"]', '诗', 'shi', '', NULL, '登長城 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab07dac2-299a-485a-bc5f-41450e4a41e0', '雜曲', '杂曲', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["妾本蠶家女，不識貴門儀。","藁砧持玉斧，交結五陵兒。","十日或一見，九日在路岐。","人生此夫壻，富貴欲何爲。","楊柳徒可折，南山不可移。","婦人貴結髮，寧有再嫁資。","嫁女莫望高，女心願所宜。","寧從賤相守，不願貴相離。","藍葉鬱重重，藍花若榴色。","少婦歸少年，華光自相得。","誰言配君子，以奉百年身。","有義即夫壻，無義還他人。","愛如寒爐火，棄若秋風扇。","山嶽起面前，相看不相見。","丈夫非小兒，何用強相知。","不見朝生菌，易成還易衰。","征客欲臨路，居人還出門。","北風河梁上，四野愁雲繁。","豈不戀我家，夫壻多感恩。","前程有日月，勳績在河源。","少婦馬前立，請君聽一言。","春至草亦生，誰能無別情。","殷勤展心素，見新莫忘故。","遙望孟門山，殷勤報君子。","既爲隨陽雁，勿學西流水。","嘗聞生別離，悲莫悲於此。","同器不同榮，堂下即千里。","與君貧賤交，何異萍上水。","託身天使然，同生復同死。"]', '["妾本蠶家女，不識貴门儀。","藁砧持玉斧，交結五陵兒。","十日或一见，九日在路岐。","人生此夫壻，富貴欲何爲。","楊柳徒可折，南山不可移。","婦人貴結髮，寧有再嫁資。","嫁女莫望高，女心願所宜。","寧從賤相守，不願貴相離。","藍葉鬱重重，藍花若榴色。","少婦归少年，华光自相得。","誰言配君子，以奉百年身。","有義即夫壻，無義還他人。","愛如寒爐火，棄若秋风扇。","山嶽起面前，相看不相见。","丈夫非小兒，何用強相知。","不见朝生菌，易成還易衰。","征客欲臨路，居人還出门。","北风河梁上，四野愁云繁。","豈不戀我家，夫壻多感恩。","前程有日月，勳績在河源。","少婦马前立，請君听一言。","春至草亦生，誰能無別情。","殷勤展心素，见新莫忘故。","遙望孟门山，殷勤報君子。","既爲隨陽雁，勿学西流水。","嘗闻生別離，悲莫悲於此。","同器不同榮，堂下即千里。","與君貧賤交，何異萍上水。","託身天使然，同生复同死。"]', '诗', 'shi', '', NULL, '雜曲 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9afbbdc-a953-44c7-93c6-dd133a03a2cd', '送遼陽使還軍', '送遼陽使還軍', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["征人歌且行，北上遼陽城。","二月戎馬息，悠悠邊草生。","青山出塞斷，代地入雲平。","昔者匈奴戰，多聞殺漢兵。","平生報國憤，日夜角弓鳴。","勉君萬里去，勿使虜塵驚。"]', '["征人歌且行，北上遼陽城。","二月戎马息，悠悠邊草生。","青山出塞斷，代地入云平。","昔者匈奴戰，多闻殺漢兵。","平生報国憤，日夜角弓鳴。","勉君万里去，勿使虜塵驚。"]', '诗', 'shi', '', NULL, '送遼陽使還軍 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca620fc-0a9c-426b-95f1-041c6091da71', '賦得早燕送別', '賦得早燕送別', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["碧草縵如綫，去來雙[飛燕]。","長門未有春，先入班姬殿。","梁空繞不息，簷寒窺欲遍。","今至隨紅萼，昔還悲素扇。","一別與秋鴻，差池詎相見。"]', '["碧草縵如綫，去来雙[飞燕]。","长门未有春，先入班姬殿。","梁空繞不息，簷寒窺欲遍。","今至隨紅萼，昔還悲素扇。","一別與秋鴻，差池詎相见。"]', '诗', 'shi', '', NULL, '賦得早燕送別 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee2d9ff4-6312-41b4-b3b1-51096b8bfac7', '秋晚溪中寄懷大理齊司直', '秋晚溪中寄懷大理齊司直', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["鳳翔屬明代，羽翼文葳蕤。","崑崙進琪樹，飛舞下瑤池。","振儀自西睠，東夏復分釐。","國典唯平法，伊人方在斯。","荒嶽寧桁楊肅，芳輝蘭玉滋。","明質鶩高景，飄颻服纓綏。","天寒清洛苑，秋夕白雲司。","況復空巖側，蒼蒼幽桂期。","歲寒坐流霰，山川猶別離。","浩思憑尊酒，氛氳獨含辭。"]', '["鳳翔屬明代，羽翼文葳蕤。","崑崙進琪樹，飞舞下瑤池。","振儀自西睠，东夏复分釐。","国典唯平法，伊人方在斯。","荒嶽寧桁楊肅，芳輝蘭玉滋。","明質鶩高景，飄颻服纓綏。","天寒清洛苑，秋夕白云司。","況复空巖側，蒼蒼幽桂期。","歲寒坐流霰，山川猶別離。","浩思憑尊酒，氛氳独含辞。"]', '诗', 'shi', '', NULL, '秋晚溪中寄懷大理齊司直 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ea0d141-1f1f-4a54-b38e-bc62fb19b466', '溪中月下寄楊子尉封亮', '溪中月下寄楊子尉封亮', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["蘅若奪幽色，銜思恍無悰。","宵長霜霧多，歲晏淮海風。","團團山中月，三五離夕同。","露凝朱弦絕，觴至蘭玉空。","清光液流波，盛明難再逢。","嘗恐河漢遠，坐窺烟景窮。","小人諒處陰，君子樹大功。","永願厲高翼，慰我丹桂叢。"]', '["蘅若奪幽色，銜思恍無悰。","宵长霜霧多，歲晏淮海风。","團團山中月，三五離夕同。","露凝朱弦絕，觴至蘭玉空。","清光液流波，盛明难再逢。","嘗恐河漢远，坐窺烟景窮。","小人諒处陰，君子樹大功。","永願厲高翼，慰我丹桂叢。"]', '诗', 'shi', '', NULL, '溪中月下寄楊子尉封亮 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e70823e0-fc5f-4037-be83-4cbe7c64dbe4', '春晚賦得餘花落', '春晚賦得餘花落', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["留春春竟去，春去花如此。","蝶舞遶應稀，鳥驚飛詎已。","衰紅辭故萼，繁綠扶彫蕊。","自委不勝愁，庭風那更起。"]', '["留春春竟去，春去花如此。","蝶舞遶應稀，鸟驚飞詎已。","衰紅辞故萼，繁綠扶彫蕊。","自委不勝愁，庭风那更起。"]', '诗', 'shi', '', NULL, '春晚賦得餘花落 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad33b922-6943-43a1-9359-c07d8d9b5901', '聞亡友王七嘉禾寺得素琴', '闻亡友王七嘉禾寺得素琴', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["故人惜此去，留琴明月前。","今來我訪舊，淚灑白雲天。","詎欲匣孤響，送君歸夜泉。","撫琴猶可絕，況此故無弦。","何必雍門奏，然後淚潺湲。"]', '["故人惜此去，留琴明月前。","今来我訪旧，泪灑白云天。","詎欲匣孤响，送君归夜泉。","撫琴猶可絕，況此故無弦。","何必雍门奏，然後泪潺湲。"]', '诗', 'shi', '', NULL, '聞亡友王七嘉禾寺得素琴 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ade51752-8b55-4531-a8c5-d791afa59916', '校書郎楊凝往年以古鏡貺別今追贈以詩', '校书郎楊凝往年以古镜貺別今追贈以诗', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["明鏡出匣時，明如雲間月。","一別青春鑑，回光照華髪。","美人昔自愛，鞶帶手中結。","願以三五期，經天無玷缺。"]', '["明镜出匣时，明如云间月。","一別青春鑑，回光照华髪。","美人昔自愛，鞶带手中結。","願以三五期，經天無玷缺。"]', '诗', 'shi', '', NULL, '校書郎楊凝往年以古鏡貺別今追贈以詩 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5e5716-f3f4-4b1f-9f73-f0468647a683', '置酒行', '置酒行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["置酒命所歡，憑觴遂爲戚。","日往不再來，茲辰坐成昔。","百齡非久長，五十將半百。","胡爲勞我形，已鬚還復白。","西山鸞鶴羣，矯矯煙霧翮。","明霞發金丹，陰洞潛水碧。","安得凌風羽，崦嵫駐靈魄。","無然坐衰老，慙歎東陵柏。"]', '["置酒命所歡，憑觴遂爲戚。","日往不再来，茲辰坐成昔。","百齡非久长，五十將半百。","胡爲勞我形，已鬚還复白。","西山鸾鹤羣，矯矯煙霧翮。","明霞發金丹，陰洞潛水碧。","安得凌风羽，崦嵫駐靈魄。","無然坐衰老，慙歎东陵柏。"]', '诗', 'shi', '', NULL, '置酒行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733b1783-2f55-486d-9ee8-92ac305b8f87', '長社竇明府宅夜送王屋道士常究子', '长社竇明府宅夜送王屋道士常究子', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["旦隨三鳥去，羽節凌霞光。","暮與雙鳧宿，雲車下紫陽。","天壇臨月近，洞水出山長。","海嶠年年別，丘陵徒自傷。"]', '["旦隨三鸟去，羽節凌霞光。","暮與雙鳧宿，云车下紫陽。","天壇臨月近，洞水出山长。","海嶠年年別，丘陵徒自傷。"]', '诗', 'shi', '', NULL, '長社竇明府宅夜送王屋道士常究子 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d330002-71b0-4c14-a73d-ed005b3fd550', '觀回軍三韻', '观回軍三韻', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["行行上隴頭，隴月暗悠悠。","萬里將軍沒，回旌隴戍秋。","誰令嗚咽水，重入故營流。"]', '["行行上隴头，隴月暗悠悠。","万里將軍沒，回旌隴戍秋。","誰令嗚咽水，重入故營流。"]', '诗', 'shi', '', NULL, '觀回軍三韻 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a993cb9d-5032-49bc-be23-e9e3fda3de76', '華山南廟', '华山南廟', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["陰山臨古道，古廟閉山碧。","落日春草中，搴芳薦瑤席。","明靈達精意，髣髴如不隔。","巖雨神降時，回飆入松栢。","常聞坑儒後，此地返秦璧。","自古害忠良，神其輔宗祏。"]', '["陰山臨古道，古廟閉山碧。","落日春草中，搴芳薦瑤席。","明靈達精意，髣髴如不隔。","巖雨神降时，回飆入松栢。","常闻坑儒後，此地返秦璧。","自古害忠良，神其輔宗祏。"]', '诗', 'shi', '', NULL, '華山南廟 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3a39ad1-5f25-463c-a4a3-09c0dd7c814c', '喜邢校書遠至對雨同賦遠晚飯阮返五韻', '喜邢校书远至对雨同賦远晚飯阮返五韻', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["雀噪空城陰，木衰羇思遠。","已蔽青山望，徒悲白雲晚。","別離千里風，雨中同一飯。","開徑說逢康，臨觴方接阮。","旅宦竟何如，勞飛思自返。"]', '["雀噪空城陰，木衰羇思远。","已蔽青山望，徒悲白云晚。","別離千里风，雨中同一飯。","开徑说逢康，臨觴方接阮。","旅宦竟何如，勞飞思自返。"]', '诗', 'shi', '', NULL, '喜邢校書遠至對雨同賦遠晚飯阮返五韻 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e15dd3-3621-46ff-be2a-145555ed2593', '城西竹園送裴佶王達', '城西竹园送裴佶王達', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["葳蕤凌風竹，寂寞離人觴。","愴懷非外至，沈鬱自中腸。","遠行從此始，別袂重淒霜。"]', '["葳蕤凌风竹，寂寞離人觴。","愴懷非外至，沈鬱自中腸。","远行從此始，別袂重淒霜。"]', '诗', 'shi', '', NULL, '城西竹園送裴佶王達 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47b1955-1d2d-4229-abd2-13f63dc48b33', '月下喜邢校書至自洛', '月下喜邢校书至自洛', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["天河夜未央，漫漫復蒼蒼。","重君遠行至，及此明目光。","華星暎衰柳，暗水入寒塘。","客心定何似，餘歡方自長。"]', '["天河夜未央，漫漫复蒼蒼。","重君远行至，及此明目光。","华星暎衰柳，暗水入寒塘。","客心定何似，餘歡方自长。"]', '诗', 'shi', '', NULL, '月下喜邢校書至自洛 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8500c255-d23f-45d9-9e39-740d3db74207', '北至太原', '北至太原', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["炎祚昔昏替，皇基此鬱盤。","玄命久已集，撫運良乃艱。","南阨羊腸險，北走雁門寒。","始於一戎定，垂此億世安。","唐風本憂思，王業寔艱難。","中曆雖橫潰，天紀未可干。","聖明所興國，靈嶽固不殫。","咄咄薄遊客，斯言殊不刊。"]', '["炎祚昔昏替，皇基此鬱盤。","玄命久已集，撫運良乃艱。","南阨羊腸險，北走雁门寒。","始於一戎定，垂此億世安。","唐风本憂思，王業寔艱难。","中曆雖橫潰，天紀未可干。","聖明所兴国，靈嶽固不殫。","咄咄薄游客，斯言殊不刊。"]', '诗', 'shi', '', NULL, '北至太原 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d093922e-8afb-4b35-a3dd-be3fca63e29c', '入華山訪隱者經仙人石壇', '入华山訪隐者經仙人石壇', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["三考四嶽下，官曹少休沐。","久負青山諾，今還獲所欲。","嘗聞玉清洞，金簡受玄籙。","夙駕昇天行，雲遊恣霞宿。","平明矯輕策，捫石入空曲。","仙人古石壇，苔遶青瑤局。","陽桂凌煙紫，陰蘿冒水綠。","隔世聞丹經，懸泉注明玉。","前驚羽人會，白日天居肅。","問我將致辭，笑之自相目。","竦身雲遂起，仰見雙白鵠。","墮其一紙書，文字類鳥足。","視之了不識，三返又三復。","歸來問方士，舉世莫解讀。","何必若蜉蝣，然後爲跼促。","鄙哉宦遊子，身志俱降辱。","再往不及期，勞歌叩山木。"]', '["三考四嶽下，官曹少休沐。","久負青山諾，今還獲所欲。","嘗闻玉清洞，金簡受玄籙。","夙駕昇天行，云游恣霞宿。","平明矯轻策，捫石入空曲。","仙人古石壇，苔遶青瑤局。","陽桂凌煙紫，陰蘿冒水綠。","隔世闻丹經，懸泉注明玉。","前驚羽人會，白日天居肅。","问我將致辞，笑之自相目。","竦身云遂起，仰见雙白鵠。","墮其一紙书，文字類鸟足。","視之了不識，三返又三复。","归来问方士，舉世莫解读。","何必若蜉蝣，然後爲跼促。","鄙哉宦游子，身志俱降辱。","再往不及期，勞歌叩山木。"]', '诗', 'shi', '', NULL, '入華山訪隱者經仙人石壇 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad4dd7c8-f86a-44ec-b83c-bd90010336ac', '罷鏡', '罷镜', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["手中青銅鏡，照我少年時。","衰颯一如此，清光難復持。","欲令孤月掩，從遣半心疑。","縱使逢人見，猶勝自見悲。"]', '["手中青銅镜，照我少年时。","衰颯一如此，清光难复持。","欲令孤月掩，從遣半心疑。","縱使逢人见，猶勝自见悲。"]', '诗', 'shi', '', NULL, '罷鏡 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a42e87f4-178e-4efe-b243-97c7c076921b', '華陰東泉同張處士詣藏律師兼簡縣內同官因寄齊中書', '华陰东泉同張处士詣藏律師兼簡縣內同官因寄齊中书', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["蒼崖抱寒泉，淪照洞金碧。","潛鱗孕明晦，山靈閟幽賾。","前峯何其詭，萬變窮日夕。","松老風易悲，山秋雲更白。","故人邑中吏，五里仙霧隔。","美質簡瓊瑤，英聲鏗金石。","煩君竟相問，問我此何適。","我因贊時理，書寄西飛翮。","哲匠熙百工，日月被光澤。","大國本多士，荆岑無遺璧。","高網彌八紘，皇圖明四闢。","羣材既兼暢，顧我在草澤。","貴無身外名，賤有區中役。","忽忽百齡內，殷殷千慮迫。","人生已如寄，在寄復爲客。","舊國不得歸，風塵滿阡陌。"]', '["蒼崖抱寒泉，淪照洞金碧。","潛鱗孕明晦，山靈閟幽賾。","前峯何其詭，万变窮日夕。","松老风易悲，山秋云更白。","故人邑中吏，五里仙霧隔。","美質簡瓊瑤，英声鏗金石。","煩君竟相问，问我此何適。","我因贊时理，书寄西飞翮。","哲匠熙百工，日月被光澤。","大国本多士，荆岑無遺璧。","高網彌八紘，皇圖明四闢。","羣材既兼暢，顧我在草澤。","貴無身外名，賤有區中役。","忽忽百齡內，殷殷千慮迫。","人生已如寄，在寄复爲客。","旧国不得归，风塵满阡陌。"]', '诗', 'shi', '', NULL, '華陰東泉同張處士詣藏律師兼簡縣內同官因寄齊中書 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e57bc6-5287-4794-a099-e361b004ff83', '答郭黃中孤雲首章見贈', '答郭黄中孤云首章见贈', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["孤雲生西北，從風東南飄。","帝鄉日已遠，蒼梧無還飆。","已矣玄鳳歎，嚴霜集靈苕。","君其勉我懷，歲暮孰不彫。"]', '["孤云生西北，從风东南飄。","帝乡日已远，蒼梧無還飆。","已矣玄鳳歎，嚴霜集靈苕。","君其勉我懷，歲暮孰不彫。"]', '诗', 'shi', '', NULL, '答郭黃中孤雲首章見贈 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0412e81a-6c61-423a-9822-8c728327f315', '合源溪期張計不至', '合源溪期張計不至', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["霜露肅時序，緬然方獨尋。","暗溪遲仙侶，寒澗聞松禽。","寂歷茲夜永，清明秋序深。","微波澹澄夕，煙景含虛林。","素志久淪否，幽懷方自吟。"]', '["霜露肅时序，緬然方独尋。","暗溪遲仙侶，寒澗闻松禽。","寂歷茲夜永，清明秋序深。","微波澹澄夕，煙景含虛林。","素志久淪否，幽懷方自吟。"]', '诗', 'shi', '', NULL, '合源溪期張計不至 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bfe2432-2fa9-4733-a72a-45030c30a391', '竹溪', '竹溪', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["訪竹越雲崖，即林若溪絕。","寧知修幹下，漠漠秋苔潔。","清光溢空曲，茂色臨幽澈。","採摘愧芳鮮，奉君歲暮節。"]', '["訪竹越云崖，即林若溪絕。","寧知修幹下，漠漠秋苔潔。","清光溢空曲，茂色臨幽澈。","採摘愧芳鲜，奉君歲暮節。"]', '诗', 'shi', '', NULL, '竹溪 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5994ba67-0113-4080-9b77-0cb3ef0f6c68', '送諸曁王主簿之任', '送諸曁王主簿之任', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["別愁已萬緒，離曲方三奏。","遠宦一辭鄉，南天異風候。","秦城歲芳老，越國春山秀。","落日望寒濤，公門閉清晝。","何用慰相思，裁書寄關右。"]', '["別愁已万緒，離曲方三奏。","远宦一辞乡，南天異风候。","秦城歲芳老，越国春山秀。","落日望寒濤，公门閉清晝。","何用慰相思，裁书寄关右。"]', '诗', 'shi', '', NULL, '送諸曁王主簿之任 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae9a08c-a98f-44c7-a836-499214f972c7', '罷秩後入華山採茯苓逢道者', '罷秩後入华山採茯苓逢道者', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["委綬來名山，觀奇恣所停。","山中若有聞，言此不死庭。","遂逢五老人，一謂西嶽靈。","或聞樵人語，飛去入昴星。","授我出雲路，蒼然凌石屏。","視之有文字，乃古黃庭經。","左右長松列，動搖風露零。","上蟠千年枝，陰虯負青冥。","下結九秋霰，流膏爲茯苓。","取之砂石間，異若龜鶴形。","況聞秦宮女，華髮變已青。","有如上帝心，與我千萬齡。","始疑有仙骨，鍊魂可永寧。","何事逐豪遊，飲啄以羶腥。","神物亦自閟，風雷護此扃。","欲傳山中寶，回策忽已暝。","乃悲世上人，求醒終不醒。"]', '["委綬来名山，观奇恣所停。","山中若有闻，言此不死庭。","遂逢五老人，一謂西嶽靈。","或闻樵人語，飞去入昴星。","授我出云路，蒼然凌石屏。","視之有文字，乃古黄庭經。","左右长松列，动搖风露零。","上蟠千年枝，陰虯負青冥。","下結九秋霰，流膏爲茯苓。","取之砂石间，異若龟鹤形。","況闻秦宮女，华髮变已青。","有如上帝心，與我千万齡。","始疑有仙骨，鍊魂可永寧。","何事逐豪游，饮啄以羶腥。","神物亦自閟，风雷護此扃。","欲傳山中寶，回策忽已暝。","乃悲世上人，求醒終不醒。"]', '诗', 'shi', '', NULL, '罷秩後入華山採茯苓逢道者 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3ccab07-1c3c-458b-97ef-db1e536c324e', '自朔方還與鄭式瞻崔稱鄭子周岑贊同會法雲寺三門避暑', '自朔方還與鄭式瞻崔稱鄭子周岑贊同會法云寺三门避暑', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["予本疎放士，朅來非外矯。","誤落邊塵中，愛山見山少。","始投清涼宇，門值煙岫表。","參差互明滅，彩翠竟昏曉。","泠泠遠風來，過此羣木杪。","英英二三彥，襟曠去煩擾。","遊川出潛魚，息陰倦飛鳥。","徇物不可窮，唯於此心了。"]', '["予本疎放士，朅来非外矯。","誤落邊塵中，愛山见山少。","始投清涼宇，门值煙岫表。","參差互明滅，彩翠竟昏晓。","泠泠远风来，過此羣木杪。","英英二三彥，襟曠去煩擾。","游川出潛鱼，息陰倦飞鸟。","徇物不可窮，唯於此心了。"]', '诗', 'shi', '', NULL, '自朔方還與鄭式瞻崔稱鄭子周岑贊同會法雲寺三門避暑 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4e193a-a232-4a00-b6b2-65e8489a0853', '來從竇車騎行', '来從竇车騎行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["束髮逢世屯，懷恩抱明義。","讀書良有感，學劒慙非智。","遂別魯諸生，來從竇車騎。","追兵赴邊急，絡馬黃金轡。","出入燕南陲，由來重意氣。","自經臯蘭戰，又破樓煩地。","西北護三邊，東南留一尉。","時過歘如雲，參差不自意。","將軍失恩澤，萬事從此異。","置酒高臺上，薄暮秋風至。","長戟與我歸，歸來同棄置。","自酌還自飲，非名又非利。","歌出易水寒，琴下雍門淚。","出逢平樂舊，言在天階侍。","問我從軍苦，自陳少年貴。","丈夫交四海，徒論身自致。","漢將不封侯，蘇卿勞遠使。","今我終此曲，此曲誠不易。","貴人難識心，何由知忌諱。"]', '["束髮逢世屯，懷恩抱明義。","读书良有感，学劒慙非智。","遂別魯諸生，来從竇车騎。","追兵赴邊急，絡马黄金轡。","出入燕南陲，由来重意氣。","自經臯蘭戰，又破楼煩地。","西北護三邊，东南留一尉。","时過歘如云，參差不自意。","將軍失恩澤，万事從此異。","置酒高台上，薄暮秋风至。","长戟與我归，归来同棄置。","自酌還自饮，非名又非利。","歌出易水寒，琴下雍门泪。","出逢平乐旧，言在天階侍。","问我從軍苦，自陳少年貴。","丈夫交四海，徒論身自致。","漢將不封侯，蘇卿勞远使。","今我終此曲，此曲誠不易。","貴人难識心，何由知忌諱。"]', '诗', 'shi', '', NULL, '來從竇車騎行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a6b502b-cb9c-497a-9d54-9ba097e0ea2d', '夜發軍中', '夜發軍中', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["邊馬櫪上驚，雄劒匣中鳴。","半夜軍書致，匈奴寇六城。","中堅分暗陣，太乙起神兵。","出沒風雲合，蒼黃豺虎爭。","今日邊庭戰，緣賞不緣名。"]', '["邊马櫪上驚，雄劒匣中鳴。","半夜軍书致，匈奴寇六城。","中堅分暗陣，太乙起神兵。","出沒风云合，蒼黄豺虎爭。","今日邊庭戰，緣賞不緣名。"]', '诗', 'shi', '', NULL, '夜發軍中 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cedafb62-7ae2-4a70-a2db-f48facd08f36', '將赴朔方早發漢武泉', '將赴朔方早發漢武泉', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["弭蓋出故關，窮秋首邊路。","問我此何爲，平生重一顧。","風吹山下草，繫馬河邊樹。","奉役良有期，回瞻終未屢。","去鄉幸未遠，戎衣今已故。","豈惟幽朔寒，念我機中素。","去矣勿復言，所酬知音遇。"]', '["弭蓋出故关，窮秋首邊路。","问我此何爲，平生重一顧。","风吹山下草，繫马河邊樹。","奉役良有期，回瞻終未屢。","去乡幸未远，戎衣今已故。","豈惟幽朔寒，念我機中素。","去矣勿复言，所酬知音遇。"]', '诗', 'shi', '', NULL, '將赴朔方早發漢武泉 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9438f77-6c30-4d0d-bd59-8048625585a1', '城傍少年', '城傍少年', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["長生邊城傍，出身事弓馬。","少年有膽氣，獨獵陰山下。","偶與匈奴逢，曾擒射鵰者。","名懸壯士籍，請君少相假。"]', '["长生邊城傍，出身事弓马。","少年有膽氣，独獵陰山下。","偶與匈奴逢，曾擒射鵰者。","名懸壯士籍，請君少相假。"]', '诗', 'shi', '', NULL, '城傍少年 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c50617c3-db50-4e02-a04f-c875072e9a89', '游子吟', '游子吟', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["女羞夫壻薄，客耻主人賤。","遭遇同衆流，低回媿相見。","君非青銅鏡，何事空照面。","莫以衣上塵，不謂心如練。","人生當榮盛，待士勿言倦。","君看白日馳，何異弦上箭。"]', '["女羞夫壻薄，客耻主人賤。","遭遇同衆流，低回媿相见。","君非青銅镜，何事空照面。","莫以衣上塵，不謂心如練。","人生當榮盛，待士勿言倦。","君看白日驰，何異弦上箭。"]', '诗', 'shi', '', NULL, '游子吟 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a299bc6f-f1c3-49dd-b450-c6a86c070155', '飲馬歌', '饮马歌', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["百馬飲一泉，一馬爭上游。","一馬噴成泥，百馬飲濁流。","上有滄浪客，對之空歎息。","自顧纓上塵，裴回終日夕。","爲問泉上翁，何時見沙石。"]', '["百马饮一泉，一马爭上游。","一马噴成泥，百马饮濁流。","上有滄浪客，对之空歎息。","自顧纓上塵，裴回終日夕。","爲问泉上翁，何时见沙石。"]', '诗', 'shi', '', NULL, '飲馬歌 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c0f4e33-d046-48ce-bf7f-0aaf1d7f85dc', '蓮塘驛', '蓮塘驛', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["五月渡淮水，南行遶山陂。","江村遠雞應，竹裏聞繰絲。","楚女肌髮美，蓮塘煙露滋。","菱花覆碧渚，黃鳥雙飛時。","渺渺泝洄遠，憑風託微詞。","斜光動流睇，此意難自持。","女歌本輕豔，客行多怨思。","女蘿蒙幽蔓，擬上青桐枝。"]', '["五月渡淮水，南行遶山陂。","江村远雞應，竹裏闻繰絲。","楚女肌髮美，蓮塘煙露滋。","菱花覆碧渚，黄鸟雙飞时。","渺渺泝洄远，憑风託微词。","斜光动流睇，此意难自持。","女歌本轻豔，客行多怨思。","女蘿蒙幽蔓，擬上青桐枝。"]', '诗', 'shi', '', NULL, '蓮塘驛 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab87ffd-4188-4986-9367-e47bfafb7e13', '五城道中', '五城道中', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["金鐃隨玉節，落日河邊路。","沙鳴後騎來，雁起前軍度。","五城鳴斥堠，三秦新召募。","天寒白登道，塞濁陰山霧。","仍聞舊兵老，尚在烏蘭戍。","笳簫漢思繁，旌旗邊色故。","寢興倦弓甲，勤役傷風露。","來遠賞不行，鋒交勳乃茂。","未知朔方道，何年罷兵賦。"]', '["金鐃隨玉節，落日河邊路。","沙鳴後騎来，雁起前軍度。","五城鳴斥堠，三秦新召募。","天寒白登道，塞濁陰山霧。","仍闻旧兵老，尚在烏蘭戍。","笳簫漢思繁，旌旗邊色故。","寢兴倦弓甲，勤役傷风露。","来远賞不行，鋒交勳乃茂。","未知朔方道，何年罷兵賦。"]', '诗', 'shi', '', NULL, '五城道中 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0635bc3b-9aab-41e0-92d9-9fee8a31a838', '與王楚同登青龍寺上方', '與王楚同登青龙寺上方', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["連岡出古寺，流睇移芳讌。","鳥沒漢諸陵，草平秦故殿。","搖光淺深樹，拂木參差燕。","春心斷易迷，遠目傷難徧。","壯日各輕年，暮年方自見。"]', '["連岡出古寺，流睇移芳讌。","鸟沒漢諸陵，草平秦故殿。","搖光淺深樹，拂木參差燕。","春心斷易迷，远目傷难徧。","壯日各轻年，暮年方自见。"]', '诗', 'shi', '', NULL, '與王楚同登青龍寺上方 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8879571b-91bc-47a4-b2f8-4094ed1440ed', '登夏州城觀送行人賦得六州胡兒歌', '登夏州城观送行人賦得六州胡兒歌', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["六州胡兒六蕃語，十歲騎羊逐沙鼠。","沙頭牧馬孤雁飛，漢軍遊騎貂錦衣。","雲中征戍三千里，今日征行何歲歸。","無定河邊數株柳，共送行人一杯酒。","胡兒起作和蕃歌，齊唱嗚嗚盡垂手。","心知舊國西州遠，西向胡天望鄉久。","回頭忽作異方聲，一聲回盡征人首。","蕃音虜曲一難分，似說邊情向塞雲。","故國關山無限路，風沙滿眼堪斷魂。","不見天邊青作冢，古來愁殺漢昭君。"]', '["六州胡兒六蕃語，十歲騎羊逐沙鼠。","沙头牧马孤雁飞，漢軍游騎貂錦衣。","云中征戍三千里，今日征行何歲归。","無定河邊數株柳，共送行人一杯酒。","胡兒起作和蕃歌，齊唱嗚嗚尽垂手。","心知旧国西州远，西向胡天望乡久。","回头忽作異方声，一声回尽征人首。","蕃音虜曲一难分，似说邊情向塞云。","故国关山無限路，风沙满眼堪斷魂。","不见天邊青作冢，古来愁殺漢昭君。"]', '诗', 'shi', '', NULL, '登夏州城觀送行人賦得六州胡兒歌 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e7eeac9-cf7a-4b57-af7d-60ac5ab60ad3', '從軍夜次六胡北飲馬磨劒石爲祝殤辭', '從軍夜次六胡北饮马磨劒石爲祝殤辞', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["我行空磧，見沙之磷磷，與草之冪冪。","半沒胡兒磨劒石，當時洗劒血成川。","至今草與沙皆赤，我因扣石問以言。","水流嗚咽幽草根，君寧獨不怪陰燐。","吹火熒熒又爲碧，有鳥自稱蜀帝魂。","南人伐竹湘山下，交根接葉滿淚痕。","請君先問湘江水，然我此恨乃可論。","秦亡漢絕三十國，關山戰死知何極。","風飄雨灑水自流，此中有冤消不得。","爲之彈劒作哀吟，風沙四起雲沈沈。","滿營戰馬嘶欲盡，畢昴不見胡天陰。","東征曾弔長平苦，往往睛明獨風雨。","年移代去感精魂，空山月暗聞鼙鼓。","秦坑趙卒四十萬，未若格鬬傷戎虜。","聖君破胡爲六州，六州又盡爲胡丘。","韓公三城斷胡路，漢甲百萬屯邊秋。","乃分司空授朔土，擁以玉節臨諸侯。","漢爲一雪萬世讐，我今抽刀勒劒石，告爾萬世爲唐休。","又聞招魂有美酒，爲我澆酒祝東流。","殤爲魂兮，可以歸還故鄉些。","沙場地無人兮，爾獨不可以久留。"]', '["我行空磧，见沙之磷磷，與草之冪冪。","半沒胡兒磨劒石，當时洗劒血成川。","至今草與沙皆赤，我因扣石问以言。","水流嗚咽幽草根，君寧独不怪陰燐。","吹火熒熒又爲碧，有鸟自稱蜀帝魂。","南人伐竹湘山下，交根接葉满泪痕。","請君先问湘江水，然我此恨乃可論。","秦亡漢絕三十国，关山戰死知何極。","风飄雨灑水自流，此中有冤消不得。","爲之彈劒作哀吟，风沙四起云沈沈。","满營戰马嘶欲尽，畢昴不见胡天陰。","东征曾弔长平苦，往往睛明独风雨。","年移代去感精魂，空山月暗闻鼙鼓。","秦坑趙卒四十万，未若格鬬傷戎虜。","聖君破胡爲六州，六州又尽爲胡丘。","韓公三城斷胡路，漢甲百万屯邊秋。","乃分司空授朔土，擁以玉節臨諸侯。","漢爲一雪万世讐，我今抽刀勒劒石，告爾万世爲唐休。","又闻招魂有美酒，爲我澆酒祝东流。","殤爲魂兮，可以归還故乡些。","沙場地無人兮，爾独不可以久留。"]', '诗', 'shi', '', NULL, '從軍夜次六胡北飲馬磨劒石爲祝殤辭 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd7ee0fc-78eb-4b7c-86e3-efe3e65ffda9', '登天壇夜見海', '登天壇夜见海', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["朝遊碧峯三十六，夜上天壇月邊宿。","仙人攜我搴玉英，壇上夜半東方明。","僊鐘撞撞近海日，海中離離三山出。","霞梯赤城遙可分，霓旌絳節倚彤雲。","八鸞五鳳紛在御，王母欲上朝元君。","羣仙指此爲我說，幾見塵飛滄海竭。","竦身別我期丹宮，空山處處遺清風。","九州下視杳未旦，一半浮生皆夢中。","始知武皇求不死，去逐瀛洲羨門子。"]', '["朝游碧峯三十六，夜上天壇月邊宿。","仙人携我搴玉英，壇上夜半东方明。","僊鐘撞撞近海日，海中離離三山出。","霞梯赤城遙可分，霓旌絳節倚彤云。","八鸾五鳳紛在御，王母欲上朝元君。","羣仙指此爲我说，幾见塵飞滄海竭。","竦身別我期丹宮，空山处处遺清风。","九州下視杳未旦，一半浮生皆梦中。","始知武皇求不死，去逐瀛洲羨门子。"]', '诗', 'shi', '', NULL, '登天壇夜見海 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53507dd1-ecdc-459b-ad7f-18951aa1751b', '大禮畢皇帝御丹鳳門改元建中大赦', '大禮畢皇帝御丹鳳门改元建中大赦', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["大明曈曈天地分，六龍負日升天門。","鳳凰飛來銜帝籙，言我萬代金皇孫。","靈雞鼓舞承天赦，高翔百尺垂朱幡。","宸居穆清受天曆，建中甲子合上元。","昊穹景命即已至，王事乃可酬乾坤。","升中告成答玄貺，泥金檢玉昭鴻恩。","云亭之事略可記，七十二君寧獨尊。","小臣欲上封禪表，久而未就歸文園。"]', '["大明曈曈天地分，六龙負日升天门。","鳳凰飞来銜帝籙，言我万代金皇孫。","靈雞鼓舞承天赦，高翔百尺垂朱幡。","宸居穆清受天曆，建中甲子合上元。","昊穹景命即已至，王事乃可酬乾坤。","升中告成答玄貺，泥金檢玉昭鴻恩。","云亭之事略可記，七十二君寧独尊。","小臣欲上封禪表，久而未就归文园。"]', '诗', 'shi', '', NULL, '大禮畢皇帝御丹鳳門改元建中大赦 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baf32153-80f8-4276-835e-ad216726ee00', '輕薄篇', '轻薄篇', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["豪不必馳千騎，雄不在垂雙鞬。","天生俊氣自相逐，出與鵰鶚同飛翻。","朝行九衢不得意，下鞭走馬城西原。","忽聞燕雁一聲去，回鞍挾彈平陵園。","歸來青樓曲未半，美人玉色當金尊。","淮陰少年不相下，酒酣半笑倚市門。","安知我有不平色，白日欲落紅塵昏。","死生容易如反掌，得意失意由一言。","少年但飲莫相問，此中報讐亦報恩。"]', '["豪不必驰千騎，雄不在垂雙鞬。","天生俊氣自相逐，出與鵰鶚同飞翻。","朝行九衢不得意，下鞭走马城西原。","忽闻燕雁一声去，回鞍挾彈平陵园。","归来青楼曲未半，美人玉色當金尊。","淮陰少年不相下，酒酣半笑倚市门。","安知我有不平色，白日欲落紅塵昏。","死生容易如反掌，得意失意由一言。","少年但饮莫相问，此中報讐亦報恩。"]', '诗', 'shi', '', NULL, '輕薄篇 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64efbf7a-0bf7-4d4c-bdfa-66a6868ca3df', '野田行', '野田行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["日沒出古城，野田何茫茫。","寒狐嘯青冢，鬼火燒白楊。","昔人未爲泉下客，行到此中曾斷腸。"]', '["日沒出古城，野田何茫茫。","寒狐嘯青冢，鬼火燒白楊。","昔人未爲泉下客，行到此中曾斷腸。"]', '诗', 'shi', '', NULL, '野田行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c1e4978-6cc4-4de9-86d1-f7dcc8cce6e1', '古別離', '古別離', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["雙劒欲別風淒然，雌沈水底雄上天。","江回漢轉兩不見，雲交雨合知何年。","古來萬事皆由命，何用臨岐苦涕漣。"]', '["雙劒欲別风淒然，雌沈水底雄上天。","江回漢轉兩不见，云交雨合知何年。","古来万事皆由命，何用臨岐苦涕漣。"]', '诗', 'shi', '', NULL, '古別離 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ce804ea-013c-4af4-a4c3-4e1e4fb89500', '效古促促曲爲河上思婦作', '效古促促曲爲河上思婦作', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["促促何促促，黃河九回曲。","嫁與棹船郎，空牀將影宿。","不道君心不如石，那教妾貌長如玉。"]', '["促促何促促，黄河九回曲。","嫁與棹船郎，空牀將影宿。","不道君心不如石，那教妾貌长如玉。"]', '诗', 'shi', '', NULL, '效古促促曲爲河上思婦作 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31fa0be9-47e6-424d-8d1a-c31a00492172', '漢宮少年行', '漢宮少年行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["君不見上宮警夜營八屯，鼕鼕街鼓朝朱軒。","玉堦霜仗擁未合，少年排入銅龍門。","暗聞弦管九天上，宮漏沈沈清吹繁。","平明走馬絕馳道，呼鷹挾彈通繚垣。","玉籠金鎖養黃口，探雛取卵伴王孫。","分曹陸博快一擲，迎歡先意笑語喧。","巧爲柔媚學優孟，儒衣嬉戲冠沐猿。","晚來香街經柳市，行過倡舍宿桃根。","相逢杯酒一言失，迴朱點白聞至尊。","金張許史伺顏色，王侯將相莫敢論。","豈知人事無定勢，朝歡暮戚如掌翻。","椒房寵移子愛奪，一夕秋風生戾園。","徒用黃金將買賦，寧知白玉暗成痕。","持杯收水水已覆，徙薪避火火更燔。","欲求四老張丞相，南山如天不可上。"]', '["君不见上宮警夜營八屯，鼕鼕街鼓朝朱軒。","玉堦霜仗擁未合，少年排入銅龙门。","暗闻弦管九天上，宮漏沈沈清吹繁。","平明走马絕驰道，呼鷹挾彈通繚垣。","玉籠金鎖養黄口，探雛取卵伴王孫。","分曹陸博快一擲，迎歡先意笑語喧。","巧爲柔媚学優孟，儒衣嬉戲冠沐猿。","晚来香街經柳市，行過倡舍宿桃根。","相逢杯酒一言失，迴朱点白闻至尊。","金張許史伺顏色，王侯將相莫敢論。","豈知人事無定勢，朝歡暮戚如掌翻。","椒房寵移子愛奪，一夕秋风生戾园。","徒用黄金將買賦，寧知白玉暗成痕。","持杯收水水已覆，徙薪避火火更燔。","欲求四老張丞相，南山如天不可上。"]', '诗', 'shi', '', NULL, '漢宮少年行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b501b42-fe79-4c87-97bc-7ff610629698', '竹窗聞風寄苗發司空曙', '竹窗闻风寄苗發司空曙', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["微風驚暮坐，臨牖思悠哉。","開門復動竹，疑是故人來。","時滴枝上露，稍沾堦下苔。","何當一入幌，爲拂綠琴埃。"]', '["微风驚暮坐，臨牖思悠哉。","开门复动竹，疑是故人来。","时滴枝上露，稍沾堦下苔。","何當一入幌，爲拂綠琴埃。"]', '诗', 'shi', '', NULL, '竹窗聞風寄苗發司空曙 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0f6c98-600f-490d-aab0-8e2eedcf33b4', '賦得垣衣', '賦得垣衣', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["漠漠復霏霏，爲君垣上衣。","昭陽輦下草，應笑此生非。","掩藹青春去，蒼茫白露稀。","猶勝萍逐水，流浪不相依。"]', '["漠漠复霏霏，爲君垣上衣。","昭陽輦下草，應笑此生非。","掩藹青春去，蒼茫白露稀。","猶勝萍逐水，流浪不相依。"]', '诗', 'shi', '', NULL, '賦得垣衣 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a2250c9-1c3b-46ec-8872-f0decaa82b7d', '送人流貶', '送人流貶', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["漢章雖約法，秦律已除名。","謗遠人多惑，官微不自明。","霜風先獨樹，瘴雨失荒城。","疇昔長沙事，三年召賈生。"]', '["漢章雖約法，秦律已除名。","謗远人多惑，官微不自明。","霜风先独樹，瘴雨失荒城。","疇昔长沙事，三年召賈生。"]', '诗', 'shi', '', NULL, '送人流貶 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b4c8085-3507-4d7d-b0d0-23b86cde36d1', '送人南歸', '送人南归', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["人言下江疾，君道下江遲。","五月江路惡，南風驚浪時。","應知近家喜，還有異鄉悲。","無奈孤舟夕，山歌聞竹枝。"]', '["人言下江疾，君道下江遲。","五月江路惡，南风驚浪时。","應知近家喜，還有異乡悲。","無奈孤舟夕，山歌闻竹枝。"]', '诗', 'shi', '', NULL, '送人南歸 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2baaeb98-3c3e-4474-a224-9e251f9f440d', '水亭夜坐賦得曉霧', '水亭夜坐賦得晓霧', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["月落寒霧起，沈思浩通川。","宿禽囀木散，山澤一蒼然。","漠漠沙上路，沄沄洲外田。","猶當依遠樹，斷續欲窮天。"]', '["月落寒霧起，沈思浩通川。","宿禽囀木散，山澤一蒼然。","漠漠沙上路，沄沄洲外田。","猶當依远樹，斷續欲窮天。"]', '诗', 'shi', '', NULL, '水亭夜坐賦得曉霧 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7796060-d3ba-48f2-ae1b-75d75215548d', '送常曾侍御使西蕃寄題西川', '送常曾侍御使西蕃寄題西川', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["涼王宮殿盡，蕪沒隴雲西。","今日聞君使，雄心逐鼓鼙。","行當收漢壘，直可取蒲泥。","舊國無由到，煩君下馬題。"]', '["涼王宮殿尽，蕪沒隴云西。","今日闻君使，雄心逐鼓鼙。","行當收漢壘，直可取蒲泥。","旧国無由到，煩君下马題。"]', '诗', 'shi', '', NULL, '送常曾侍御使西蕃寄題西川 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dba323d-1fb0-4e7c-9631-1756f73cb66c', '入南山至全師蘭若', '入南山至全師蘭若', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["木隕水歸壑，寂然無念心。","南行有真子，被褐息山陰。","石路瑤草散，松門寒景深。","吾師亦何愛，自起定中吟。"]', '["木隕水归壑，寂然無念心。","南行有真子，被褐息山陰。","石路瑤草散，松门寒景深。","吾師亦何愛，自起定中吟。"]', '诗', 'shi', '', NULL, '入南山至全師蘭若 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8990d048-1892-4577-b4d7-1fb4b01573d8', '送韓將軍還邊', '送韓將軍還邊', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["白馬羽林兒，揚鞭薄暮時。","獨將輕騎出，暗與伏兵期。","雨雪移軍遠，旌旗上壠遲。","聖心戎寄重，未許讓恩私。"]', '["白马羽林兒，揚鞭薄暮时。","独將轻騎出，暗與伏兵期。","雨雪移軍远，旌旗上壠遲。","聖心戎寄重，未許讓恩私。"]', '诗', 'shi', '', NULL, '送韓將軍還邊 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ed55057-2952-43ca-9480-449f2750d6e2', '晚春臥病喜振上人見訪', '晚春臥病喜振上人见訪', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["臥牀如舊日，窺戶易傷春。","靈壽扶衰力，芭蕉對病身。","道心空寂寞，時物自芳新。","旦夕誰相訪，唯當攝上人。"]', '["臥牀如旧日，窺戶易傷春。","靈壽扶衰力，芭蕉对病身。","道心空寂寞，时物自芳新。","旦夕誰相訪，唯當攝上人。"]', '诗', 'shi', '', NULL, '晚春臥病喜振上人見訪 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ac0c91-1a6a-497e-b9e0-888d5864ef98', '春行', '春行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["侍臣朝謁罷，戚里自相過。","落日青絲騎，春風白紵歌。","恩承三殿近，獵向五陵多。","歸路南橋望，垂楊拂細波。"]', '["侍臣朝謁罷，戚里自相過。","落日青絲騎，春风白紵歌。","恩承三殿近，獵向五陵多。","归路南橋望，垂楊拂細波。"]', '诗', 'shi', '', NULL, '春行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c003d0a4-d608-4d4f-b9fc-7b87b4202d53', '洛陽河亭奉酬留守羣公追送', '洛陽河亭奉酬留守羣公追送', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["離亭餞落暉，臘酒減春衣。","歲晚煙霞重，川寒雲樹微。","戎裝千里至，舊路十年歸。","還似汀洲雁，相逢又背飛。"]', '["離亭餞落暉，臘酒減春衣。","歲晚煙霞重，川寒云樹微。","戎裝千里至，旧路十年归。","還似汀洲雁，相逢又背飞。"]', '诗', 'shi', '', NULL, '洛陽河亭奉酬留守羣公追送 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa3d4999-dde9-40af-958d-0a79eb4d2171', '尋紀道士偶會諸叟', '尋紀道士偶會諸叟', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["山陰尋道士，暎竹羽衣新。","侍坐雙童子，陪遊五老人。","水花松下靜，壇草雪中春。","見說桃源洞，如今猶避秦。"]', '["山陰尋道士，暎竹羽衣新。","侍坐雙童子，陪游五老人。","水花松下静，壇草雪中春。","见说桃源洞，如今猶避秦。"]', '诗', 'shi', '', NULL, '尋紀道士偶會諸叟 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd1f5183-318f-40d2-ac1c-fe5b12415a25', '同蕭鍊師宿太乙廟', '同蕭鍊師宿太乙廟', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["微月空山曙，春祠謁少君。","落花壇上拂，流水洞中聞。","酒引芝童奠，香餘桂子焚。","鶴飛將羽節，遙向赤城分。"]', '["微月空山曙，春祠謁少君。","落花壇上拂，流水洞中闻。","酒引芝童奠，香餘桂子焚。","鹤飞將羽節，遙向赤城分。"]', '诗', 'shi', '', NULL, '同蕭鍊師宿太乙廟 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ed9dbf-ff4b-49ee-b3bd-6d621c5f5766', '送同落第者東歸', '送同落第者东归', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["東門有行客，落日滿前山。","聖代誰知者，滄洲今獨還。","片雲歸海暮，流水背城閑。","余亦依嵩潁，松花深閉關。"]', '["东门有行客，落日满前山。","聖代誰知者，滄洲今独還。","片云归海暮，流水背城闲。","余亦依嵩潁，松花深閉关。"]', '诗', 'shi', '', NULL, '送同落第者東歸 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4dfb15-6a50-428f-8ce8-121b853cce12', '送柳判官赴振武', '送柳判官赴振武', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["邊庭漢儀重，旌甲似雲中。","虜地山川壯，單于鼓角雄。","關寒塞榆落，月白胡天風。","君逐嫖姚將，麒麟有戰功。"]', '["邊庭漢儀重，旌甲似云中。","虜地山川壯，單于鼓角雄。","关寒塞榆落，月白胡天风。","君逐嫖姚將，麒麟有戰功。"]', '诗', 'shi', '', NULL, '送柳判官赴振武 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66d3a87d-2758-4bd0-8e07-927f9e722afc', '述懷寄衡州令狐相公', '述懷寄衡州令狐相公', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["調元方翼聖，軒蓋忽言東。","道以中樞密，心將外理同。","白頭生遠浪，丹葉下高楓。","江上蕭疎雨，何人對謝公。"]', '["調元方翼聖，軒蓋忽言东。","道以中樞密，心將外理同。","白头生远浪，丹葉下高楓。","江上蕭疎雨，何人对謝公。"]', '诗', 'shi', '', NULL, '述懷寄衡州令狐相公 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('566b6a8b-7a12-4b35-a277-f9b4a530c908', '喜入蘭陵望紫閣峯呈宣上人', '喜入蘭陵望紫閣峯呈宣上人', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["薙草開三徑，巢林喜一枝。","地寬留種竹，泉淺欲開池。","紫閣當疎牖，青松入壞籬。","從今安僻陋，蕭相是吾師。"]', '["薙草开三徑，巢林喜一枝。","地寬留種竹，泉淺欲开池。","紫閣當疎牖，青松入壞籬。","從今安僻陋，蕭相是吾師。"]', '诗', 'shi', '', NULL, '喜入蘭陵望紫閣峯呈宣上人 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d755f74b-18fd-44d1-a6e1-43e77490bb09', '喜見外弟又言別', '喜见外弟又言別', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["十年離亂後，長大一相逢。","問姓驚初見，稱名憶舊容。","別來滄海事，語罷暮天鐘。","明日巴陵道，秋山又幾重。"]', '["十年離亂後，长大一相逢。","问姓驚初见，稱名憶旧容。","別来滄海事，語罷暮天鐘。","明日巴陵道，秋山又幾重。"]', '诗', 'shi', '', NULL, '喜見外弟又言別 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17e7a317-f30f-4f25-ac0f-d43111ce9da1', '立春日寧州行營因賦朔風吹飛雪', '立春日寧州行營因賦朔风吹飞雪', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["邊聲日夜合，朔風驚復來。","龍山不可望，千里一裴回。","捐扇破誰執，素紈輕欲裁。","非時妬桃李，自是舞陽臺。"]', '["邊声日夜合，朔风驚复来。","龙山不可望，千里一裴回。","捐扇破誰執，素紈轻欲裁。","非时妬桃李，自是舞陽台。"]', '诗', 'shi', '', NULL, '立春日寧州行營因賦朔風吹飛雪 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ece861e-f4da-4663-9ca7-22ed69e049dd', '獻劉濟', '獻劉濟', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["草綠古燕州，鶯聲引獨遊。","雁歸天北畔，春盡海西頭。","向日花偏落，馳年水自流。","感恩知有地，不上望京樓。"]', '["草綠古燕州，鶯声引独游。","雁归天北畔，春尽海西头。","向日花偏落，驰年水自流。","感恩知有地，不上望京楼。"]', '诗', 'shi', '', NULL, '獻劉濟 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f99ee05c-2dff-4dc0-9a51-22f8168b5427', '哭柏巖禪師', '哭柏巖禪師', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["遍與傍人別，臨終盡不愁。","影堂誰爲掃，坐塔自看修。","白日鐘邊晚，青苔鉢上秋。","天涯禪弟子，空到柏巖遊。"]', '["遍與傍人別，臨終尽不愁。","影堂誰爲掃，坐塔自看修。","白日鐘邊晚，青苔鉢上秋。","天涯禪弟子，空到柏巖游。"]', '诗', 'shi', '', NULL, '哭柏巖禪師 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73165d09-7d28-4501-8b78-3770ebca3914', '赴邠寧留別', '赴邠寧留別', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["身承漢飛將，束髮即言兵。","俠少何相問，從來事不平。","黃雲斷朔吹，白雪擁沙城。","幸應邊書募，橫戈會取名。"]', '["身承漢飞將，束髮即言兵。","俠少何相问，從来事不平。","黄云斷朔吹，白雪擁沙城。","幸應邊书募，橫戈會取名。"]', '诗', 'shi', '', NULL, '赴邠寧留別 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c00d44f-c654-4483-94e0-bdb85cd6f977', '紫騮馬', '紫騮马', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["爭場看鬬雞，白鼻紫騮嘶。","漳水春閨晚，叢臺日向低。","歇鞍珠作汗，試劒玉如泥。","爲謝紅梁燕，年年妾獨棲。"]', '["爭場看鬬雞，白鼻紫騮嘶。","漳水春閨晚，叢台日向低。","歇鞍珠作汗，試劒玉如泥。","爲謝紅梁燕，年年妾独棲。"]', '诗', 'shi', '', NULL, '紫騮馬 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ab5d59-0df0-48f6-8830-9086b4915a9b', '夜上受降城聞笛', '夜上受降城闻笛', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["入夜思歸切，笛聲清更哀。","愁人不願聽，自到枕前來。","風起塞雲斷，夜深關月開。","平明獨惆悵，落盡一庭梅。"]', '["入夜思归切，笛声清更哀。","愁人不願听，自到枕前来。","风起塞云斷，夜深关月开。","平明独惆悵，落尽一庭梅。"]', '诗', 'shi', '', NULL, '夜上受降城聞笛 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf81ba1-a18f-4e42-9bad-ac68cae86da4', '同崔邠登鸛雀樓', '同崔邠登鸛雀楼', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["鸛雀樓西百尺檣，汀洲雲樹共茫茫。","漢家簫鼓空流水，魏國山河半夕陽。","事去千年猶恨速，愁來一日即爲長。","風煙倂起思歸望，遠目非春亦自傷。"]', '["鸛雀楼西百尺檣，汀洲云樹共茫茫。","漢家簫鼓空流水，魏国山河半夕陽。","事去千年猶恨速，愁来一日即爲长。","风煙倂起思归望，远目非春亦自傷。"]', '诗', 'shi', '', NULL, '同崔邠登鸛雀樓 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13bfd558-12d2-49c1-8968-a94c7246c83a', '奉酬崔員外副使攜琴宿使院見示', '奉酬崔員外副使携琴宿使院见示', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["忽聞此夜攜琴宿，遂歎常時塵吏喧。","庭木已衰空月亮，城砧自急對霜繁。","猶持副節留軍府，未薦高詞直掖垣。","誰問南飛長繞樹，官微同在謝公門。"]', '["忽闻此夜携琴宿，遂歎常时塵吏喧。","庭木已衰空月亮，城砧自急对霜繁。","猶持副節留軍府，未薦高词直掖垣。","誰问南飞长繞樹，官微同在謝公门。"]', '诗', 'shi', '', NULL, '奉酬崔員外副使攜琴宿使院見示 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030307a8-0ef0-4e9a-b7c0-5f1d5240b322', '送賈校書東歸寄振上人', '送賈校书东归寄振上人', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["北風吹雁數聲悲，況指前林是別時。","秋草不堪頻送遠，白雲何處更相期。","山隨匹馬行看暮，路入寒城獨去遲。","爲向東州故人道，江淹已擬惠休詩。"]', '["北风吹雁數声悲，況指前林是別时。","秋草不堪頻送远，白云何处更相期。","山隨匹马行看暮，路入寒城独去遲。","爲向东州故人道，江淹已擬惠休诗。"]', '诗', 'shi', '', NULL, '送賈校書東歸寄振上人 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9657c24a-5dc0-409d-af80-ab182a7d336f', '過馬嵬二首 一', '過马嵬二首 一', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["路至牆垣問樵者，顧予云是太真宮。","太真血染馬蹄盡，朱閣影隨天際空。","丹壑不聞歌吹夜，玉堦唯有薜蘿風。","世人莫重霓裳曲，曾致干戈是此中。"]', '["路至牆垣问樵者，顧予云是太真宮。","太真血染马蹄尽，朱閣影隨天際空。","丹壑不闻歌吹夜，玉堦唯有薜蘿风。","世人莫重霓裳曲，曾致干戈是此中。"]', '诗', 'shi', '', NULL, '過馬嵬二首 一 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c599d603-fd7c-4711-a36c-155893c365a9', '過馬嵬二首 二', '過马嵬二首 二', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["金甲銀旌盡已回，蒼茫羅袖隔風埃。","濃香猶自隨鸞輅，恨魄無由離馬嵬。","南內真人悲帳殿，東溟方士問蓬萊。","唯留坡畔彎環月，時送殘輝入夜臺。"]', '["金甲銀旌尽已回，蒼茫羅袖隔风埃。","濃香猶自隨鸾輅，恨魄無由離马嵬。","南內真人悲帳殿，东溟方士问蓬萊。","唯留坡畔彎环月，时送殘輝入夜台。"]', '诗', 'shi', '', NULL, '過馬嵬二首 二 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63aed9a9-4229-4f68-8fe9-e626ae91b5a0', '鹽州過胡兒飲馬泉', '鹽州過胡兒饮马泉', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["綠楊著水草如煙，舊是胡兒飲馬泉。","幾處吹笳明月夜，何人倚劒白雲天。","從來凍合關山路，今日分流漢使前。","莫遣行人照容鬢，恐驚憔悴入新年。"]', '["綠楊著水草如煙，旧是胡兒饮马泉。","幾处吹笳明月夜，何人倚劒白云天。","從来凍合关山路，今日分流漢使前。","莫遣行人照容鬢，恐驚憔悴入新年。"]', '诗', 'shi', '', NULL, '鹽州過胡兒飲馬泉 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa25ad03-1308-4c66-a2cf-351bbc3d22cf', '宿馮翊夜雨贈主人', '宿馮翊夜雨贈主人', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["危心驚夜雨，起望漫悠悠。","氣耿殘燈暗，聲繁高樹秋。","涼軒辭夏扇，風幌攬輕裯。","思緒蓬初斷，歸期燕暫留。","關山藹已失，臉淚逬難收。","賴君時一笑，方能解四愁。"]', '["危心驚夜雨，起望漫悠悠。","氣耿殘灯暗，声繁高樹秋。","涼軒辞夏扇，风幌攬轻裯。","思緒蓬初斷，归期燕暫留。","关山藹已失，臉泪逬难收。","賴君时一笑，方能解四愁。"]', '诗', 'shi', '', NULL, '宿馮翊夜雨贈主人 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b22cb818-b07a-4024-855d-c3734cd1d237', '送襄陽李尚書', '送襄陽李尚书', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["天寒發梅柳，憶昔到襄州。","樹暖然紅燭，江清展碧油。","風煙臨峴首，雲水接昭丘。","俗尚春秋學，詞稱文選樓。","都門送旌節，符竹領諸侯。","漢沔分戎寄，黎元減聖憂。","時追山簡興，本自習家流。","莫廢思康樂，詩情滿沃洲。"]', '["天寒發梅柳，憶昔到襄州。","樹暖然紅燭，江清展碧油。","风煙臨峴首，云水接昭丘。","俗尚春秋学，词稱文選楼。","都门送旌節，符竹領諸侯。","漢沔分戎寄，黎元減聖憂。","时追山簡兴，本自習家流。","莫廢思康乐，诗情满沃洲。"]', '诗', 'shi', '', NULL, '送襄陽李尚書 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('344bb72a-dec5-427d-b523-bc60d71bc8ee', '春日晉祠同聲會集得疎字韻', '春日晉祠同声會集得疎字韻', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["風壤瞻唐本，山祠閱晉餘。","水亭開帟幕，巖榭引簪裾。","地綠苔猶少，林黃柳尚疎。","菱苕生皎鏡，金碧照澄虛。","翰苑聲何舊，賓筵醉止初。","中州有遼雁，好爲繫邊書。"]', '["风壤瞻唐本，山祠閱晉餘。","水亭开帟幕，巖榭引簪裾。","地綠苔猶少，林黄柳尚疎。","菱苕生皎镜，金碧照澄虛。","翰苑声何旧，賓筵醉止初。","中州有遼雁，好爲繫邊书。"]', '诗', 'shi', '', NULL, '春日晉祠同聲會集得疎字韻 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d0a1909-8650-4d3f-bd5e-ef4c1b69bb8a', '再赴渭北使府留別', '再赴渭北使府留別', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["結髮逐鳴鼙，連兵追谷蠡。","山川搜伏虜，鎧甲被重犀。","故府旌旗在，新軍羽校齊。","報恩身未死，識路馬還嘶。","列嶂高烽舉，當營太白低。","平戎七尺劒，封檢一丸泥。","截海取蒲類，跑泉飲鸊鵜。","漢庭中選重，更事五原西。"]', '["結髮逐鳴鼙，連兵追谷蠡。","山川搜伏虜，鎧甲被重犀。","故府旌旗在，新軍羽校齊。","報恩身未死，識路马還嘶。","列嶂高烽舉，當營太白低。","平戎七尺劒，封檢一丸泥。","截海取蒲類，跑泉饮鸊鵜。","漢庭中選重，更事五原西。"]', '诗', 'shi', '', NULL, '再赴渭北使府留別 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16057a4a-3812-4449-8ade-86f71a10b88e', '送歸中丞使新羅冊立弔祭', '送归中丞使新羅冊立弔祭', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["東望扶桑日，何年是到時。","片帆通雨露，積水隔華夷。","浩渺風來遠，虛明鳥去遲。","長波靜雲月，孤島宿旌旗。","別葉傳秋意，迴潮動客思。","滄溟無舊路，何處問前期。"]', '["东望扶桑日，何年是到时。","片帆通雨露，積水隔华夷。","浩渺风来远，虛明鸟去遲。","长波静云月，孤島宿旌旗。","別葉傳秋意，迴潮动客思。","滄溟無旧路，何处问前期。"]', '诗', 'shi', '', NULL, '送歸中丞使新羅冊立弔祭 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2571f14e-0c02-4fa0-a52c-f3b75069e0b6', '賦得路傍一株柳送邢校書赴延州使府', '賦得路傍一株柳送邢校书赴延州使府', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["路傍一株柳，此路向延州。","延州在何處，此路起悠悠。"]', '["路傍一株柳，此路向延州。","延州在何处，此路起悠悠。"]', '诗', 'shi', '', NULL, '賦得路傍一株柳送邢校書赴延州使府 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e649844-ac06-47a4-96a7-baa2db22ea1b', '重贈邢校書', '重贈邢校书', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["俱從四方事，共會九秋中。","斷蓬與落葉，相值各因風。"]', '["俱從四方事，共會九秋中。","斷蓬與落葉，相值各因风。"]', '诗', 'shi', '', NULL, '重贈邢校書 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66322ac8-46e8-4561-9858-ece254a0de59', '照鏡', '照镜', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["衰鬢朝臨鏡，將看却自疑。","慙君明似月，照我白如絲。"]', '["衰鬢朝臨镜，將看却自疑。","慙君明似月，照我白如絲。"]', '诗', 'shi', '', NULL, '照鏡 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45b2a162-7434-46de-8d60-84a3f2aff8d9', '書院無曆日以詩代書問路侍御六月大小', '书院無曆日以诗代书问路侍御六月大小', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["野性迷堯曆，松窗有道經。","故人爲柱史，爲我數堦蓂。"]', '["野性迷堯曆，松窗有道經。","故人爲柱史，爲我數堦蓂。"]', '诗', 'shi', '', NULL, '書院無曆日以詩代書問路侍御六月大小 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32e1f5b6-ef99-421b-a27a-005cfcab4a58', '聞雞贈主人', '闻雞贈主人', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["膠膠司晨鳴，報爾東方旭。","無事戀君軒，今君重鳧鵠。"]', '["膠膠司晨鳴，報爾东方旭。","無事戀君軒，今君重鳧鵠。"]', '诗', 'shi', '', NULL, '聞雞贈主人 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df9d56f5-78e1-44ca-993d-dcf464c5ab49', '登白樓見白鳥席上命鷓鴣辭', '登白楼见白鸟席上命鷓鴣辞', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["一鳥如霜雪，飛向白樓前。","問君何以至，天子太平年。"]', '["一鸟如霜雪，飞向白楼前。","问君何以至，天子太平年。"]', '诗', 'shi', '', NULL, '登白樓見白鳥席上命鷓鴣辭 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b05c06-42e5-4802-84e5-67d0f804f91e', '石樓山見月', '石楼山见月', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["紫塞連年戍，黃砂磧路窮。","故人今夜宿，見月石樓中。"]', '["紫塞連年戍，黄砂磧路窮。","故人今夜宿，见月石楼中。"]', '诗', 'shi', '', NULL, '石樓山見月 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98125ab-4707-4368-96e8-349c1678b363', '惜春傷同幕故人孟郎中兼呈去年看花友', '惜春傷同幕故人孟郎中兼呈去年看花友', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["畏老身全老，逢春解惜春。","今年看花伴，已少去年人。"]', '["畏老身全老，逢春解惜春。","今年看花伴，已少去年人。"]', '诗', 'shi', '', NULL, '惜春傷同幕故人孟郎中兼呈去年看花友 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4679a379-67a4-4359-b2c6-2fcac0cb20f0', '嘉禾寺見亡友王七題壁', '嘉禾寺见亡友王七題壁', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["今日憶君處，憶君君豈知。","空餘暗塵字，讀罷淚仍垂。"]', '["今日憶君处，憶君君豈知。","空餘暗塵字，读罷泪仍垂。"]', '诗', 'shi', '', NULL, '嘉禾寺見亡友王七題壁 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d4a2e2-28ae-42d1-84ce-306a9b4df039', '聽唱赤白桃李花', '听唱赤白桃李花', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["赤白桃李花，先皇在時曲。","欲向西宮唱，西宮[宮]樹綠。"]', '["赤白桃李花，先皇在时曲。","欲向西宮唱，西宮[宮]樹綠。"]', '诗', 'shi', '', NULL, '聽唱赤白桃李花 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bd49546-5289-4351-97f4-d69296720dfc', '江南詞', '江南词', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["嫁得瞿塘賈，朝朝悞妾期。","早知潮有信，嫁與弄潮兒。"]', '["嫁得瞿塘賈，朝朝悞妾期。","早知潮有信，嫁與弄潮兒。"]', '诗', 'shi', '', NULL, '江南詞 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d713a6-c56e-4f5c-9dbc-87806a7d9f51', '贈內兄盧綸', '贈內兄盧綸', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["世故中年別，餘生此會同。","却將悲與病，來對朗陵翁。"]', '["世故中年別，餘生此會同。","却將悲與病，来对朗陵翁。"]', '诗', 'shi', '', NULL, '贈內兄盧綸 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7d970e1-655a-4f2d-b68d-f05424a35bba', '答竇二曹長留酒還榼', '答竇二曹长留酒還榼', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["榼小非由榼，星朗是酒星。","解酲元有數，不用嚇劉伶。"]', '["榼小非由榼，星朗是酒星。","解酲元有數，不用嚇劉伶。"]', '诗', 'shi', '', NULL, '答竇二曹長留酒還榼 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7abc1d7-3d6f-4e7a-9d00-399c4d6879c9', '答廣宣供奉問蘭陵居', '答廣宣供奉问蘭陵居', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["居北有朝路，居南無住人。","勞師問家第，山色是南鄰。"]', '["居北有朝路，居南無住人。","勞師问家第，山色是南鄰。"]', '诗', 'shi', '', NULL, '答廣宣供奉問蘭陵居 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60d8de49-e393-4470-bae6-6a7ce35c5d29', '乞寬禪師癭山罍呈宣供奉', '乞寬禪師癭山罍呈宣供奉', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["石色凝秋蘚，峰形若夏雲。","誰留秦苑地，好贈杏溪君。"]', '["石色凝秋蘚，峰形若夏云。","誰留秦苑地，好贈杏溪君。"]', '诗', 'shi', '', NULL, '乞寬禪師癭山罍呈宣供奉 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa31994-11ad-4080-8373-81b05d155b6e', '觀騎射', '观騎射', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["邊頭射鵰將，走馬出中軍。","遠見平原上，翻身向暮雲。"]', '["邊头射鵰將，走马出中軍。","远见平原上，翻身向暮云。"]', '诗', 'shi', '', NULL, '觀騎射 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f307977-4e4b-4524-b9a7-f5cdf4c4bbe4', '幽州賦詩見意時佐劉幕', '幽州賦诗见意时佐劉幕', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["征戍在桑乾，年年薊水寒。","殷勤驛西路，北去向長安。"]', '["征戍在桑乾，年年薊水寒。","殷勤驛西路，北去向长安。"]', '诗', 'shi', '', NULL, '幽州賦詩見意時佐劉幕 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cfd97dc-c9ce-47c0-81d1-d6fcf8af6859', '軍次陽城烽舍北流泉', '軍次陽城烽舍北流泉', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["何地可潸然，陽城烽樹邊。","今朝望鄉客，不飲北流泉。"]', '["何地可潸然，陽城烽樹邊。","今朝望乡客，不饮北流泉。"]', '诗', 'shi', '', NULL, '軍次陽城烽舍北流泉 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb6e33b6-6c5c-4994-8e76-163dfa886998', '金吾子', '金吾子', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["繡帳博山鑪，銀鞍馮子都。","黃昏莫攀折，驚起欲棲烏。"]', '["繡帳博山鑪，銀鞍馮子都。","黄昏莫攀折，驚起欲棲烏。"]', '诗', 'shi', '', NULL, '金吾子 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('097a5a64-1fd3-4307-94a0-f81bf732e94b', '山鷓鴣詞', '山鷓鴣词', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["湘江斑竹枝，錦翅鷓鴣飛。","處處湘雲合，郎從何處歸。"]', '["湘江斑竹枝，錦翅鷓鴣飞。","处处湘云合，郎從何处归。"]', '诗', 'shi', '', NULL, '山鷓鴣詞 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fd85a05-3d4d-4f65-9a54-9f1f598ad091', '立秋前一日覽鏡', '立秋前一日覽镜', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["萬事銷身外，生涯在鏡中。","唯將滿鬢雪，明日對秋風。"]', '["万事銷身外，生涯在镜中。","唯將满鬢雪，明日对秋风。"]', '诗', 'shi', '', NULL, '立秋前一日覽鏡 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e25d24b0-a03f-4e3e-943c-8ca4ce2d917e', '代人乞花', '代人乞花', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["繡戶朝眠起，開簾滿地花。","春風解人意，欲落妾西家。"]', '["繡戶朝眠起，开簾满地花。","春风解人意，欲落妾西家。"]', '诗', 'shi', '', NULL, '代人乞花 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40a9fe70-40d2-4718-a1af-09193449508a', '上洛橋', '上洛橋', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["金谷園中柳，春來似舞腰。","何堪好風景，獨上洛陽橋。"]', '["金谷园中柳，春来似舞腰。","何堪好风景，独上洛陽橋。"]', '诗', 'shi', '', NULL, '上洛橋 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f62397a-8eef-4408-81dc-2cb54b55a866', '揚州懷古', '揚州懷古', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["故國歌鐘地，長橋車馬塵。","彭城閣邊柳，偏似不勝春。"]', '["故国歌鐘地，长橋车马塵。","彭城閣邊柳，偏似不勝春。"]', '诗', 'shi', '', NULL, '揚州懷古 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc6cab7b-c3ed-4645-9573-368a962ac03e', '水宿聞雁', '水宿闻雁', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["早雁忽爲雙，驚秋風水窗。","夜長人自起，星月滿空江。"]', '["早雁忽爲雙，驚秋风水窗。","夜长人自起，星月满空江。"]', '诗', 'shi', '', NULL, '水宿聞雁 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eae2f1b-936a-4b82-9998-512b02a110e6', '揚州早雁', '揚州早雁', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["江上三千雁，年年過故宮。","可憐江上月，偏照斷根蓬。"]', '["江上三千雁，年年過故宮。","可怜江上月，偏照斷根蓬。"]', '诗', 'shi', '', NULL, '揚州早雁 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44852ba9-ebb5-4651-8b5a-62e293438389', '下樓', '下楼', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["話舊全應老，逢春喜又悲。","看花行拭淚，倍覺下樓遲。"]', '["話旧全應老，逢春喜又悲。","看花行拭泪，倍覺下楼遲。"]', '诗', 'shi', '', NULL, '下樓 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6be79308-f67c-4d92-80eb-a4f206bc5b83', '度破訥沙二首 一', '度破訥沙二首 一', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["眼見風來沙旋移，經年不省草生時。","莫言塞北無春到，總有春來何處知。"]', '["眼见风来沙旋移，經年不省草生时。","莫言塞北無春到，總有春来何处知。"]', '诗', 'shi', '', NULL, '度破訥沙二首 一 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72247708-1ff1-4fac-b17b-88cc88a9b553', '度破訥沙二首 二', '度破訥沙二首 二', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["破訥沙頭雁正飛，鸊鵜泉上戰初歸。","平明日出東南地，滿磧寒光生鐵衣。"]', '["破訥沙头雁正飞，鸊鵜泉上戰初归。","平明日出东南地，满磧寒光生鐵衣。"]', '诗', 'shi', '', NULL, '度破訥沙二首 二 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86e7df62-54b0-476d-9722-478c6bb6d8ce', '拂雲堆', '拂云堆', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["漢將新從虜地來，旌旗半上拂雲堆。","單于每近沙場獵，南望陰山哭始回。"]', '["漢將新從虜地来，旌旗半上拂云堆。","單于每近沙場獵，南望陰山哭始回。"]', '诗', 'shi', '', NULL, '拂雲堆 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('877d4ad7-11a3-4595-b86c-50052ef738d2', '中橋北送穆質兄弟應制戲贈蕭二策', '中橋北送穆質兄弟應制戲贈蕭二策', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["洛水橋邊雁影疎，陸機兄弟駐行車。","欲陳漢帝登封草，猶待蕭郎寄內書。"]', '["洛水橋邊雁影疎，陸機兄弟駐行车。","欲陳漢帝登封草，猶待蕭郎寄內书。"]', '诗', 'shi', '', NULL, '中橋北送穆質兄弟應制戲贈蕭二策 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f32abfa-6459-4020-b79d-5f96a026c945', '九月十日雨中過張伯佳期柳鎮未至以詩招之', '九月十日雨中過張伯佳期柳鎮未至以诗招之', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["柳吳興近無消息，張長公貧苦寂寥。","唯有角巾霑雨至，手持殘菊向西招。"]', '["柳吳兴近無消息，張长公貧苦寂寥。","唯有角巾霑雨至，手持殘菊向西招。"]', '诗', 'shi', '', NULL, '九月十日雨中過張伯佳期柳鎮未至以詩招之 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ba500f4-7cd5-4e87-91e0-b23ec74228e1', '汴河曲', '汴河曲', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["汴水東流無限春，隋家宮闕已成塵。","行人莫上長堤望，風起楊花愁殺人。"]', '["汴水东流無限春，隋家宮闕已成塵。","行人莫上长堤望，风起楊花愁殺人。"]', '诗', 'shi', '', NULL, '汴河曲 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7874e72a-34c7-4fb4-9564-0005c67bb596', '塞下曲 一', '塞下曲 一', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["蕃州部落能結束，朝暮馳獵黃河曲。","燕歌未斷塞鴻飛，牧馬羣嘶邊草綠。"]', '["蕃州部落能結束，朝暮驰獵黄河曲。","燕歌未斷塞鴻飞，牧马羣嘶邊草綠。"]', '诗', 'shi', '', NULL, '塞下曲 一 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29fbdce1-7be4-40c6-8653-8dbe6009ce49', '塞下曲 二', '塞下曲 二', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["秦築長城城已摧，漢武北上單于臺。","古來征戰虜不盡，今日還復天兵來。"]', '["秦築长城城已摧，漢武北上單于台。","古来征戰虜不尽，今日還复天兵来。"]', '诗', 'shi', '', NULL, '塞下曲 二 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7c28260-45f1-466e-b5fb-901240b9bee5', '塞下曲 三', '塞下曲 三', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["黃河東流流九折，沙場埋恨何時絕。","蔡琰沒去造胡笳，蘇武歸來持漢節。"]', '["黄河东流流九折，沙場埋恨何时絕。","蔡琰沒去造胡笳，蘇武归来持漢節。"]', '诗', 'shi', '', NULL, '塞下曲 三 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04b1e32a-44da-4530-b953-2db87e4c9d5e', '塞下曲 四', '塞下曲 四', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["爲報如今都護雄，匈奴且莫下雲中。","請書塞北陰山石，願比燕然車騎功。"]', '["爲報如今都護雄，匈奴且莫下云中。","請书塞北陰山石，願比燕然车騎功。"]', '诗', 'shi', '', NULL, '塞下曲 四 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1a1f44-9ea2-45a8-876a-57a374479897', '夜上西城聽梁州曲二首 一', '夜上西城听梁州曲二首 一', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["行人夜上西城宿，聽唱梁州雙筦逐。","此時秋月滿關山，何處關山無此曲。"]', '["行人夜上西城宿，听唱梁州雙筦逐。","此时秋月满关山，何处关山無此曲。"]', '诗', 'shi', '', NULL, '夜上西城聽梁州曲二首 一 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c4586db-d898-4587-96fa-3a41883587b3', '夜上西城聽梁州曲二首 二', '夜上西城听梁州曲二首 二', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["鴻雁新從北地來，聞聲一半却飛回。","金河戍客腸應斷，更在秋風百尺臺。"]', '["鴻雁新從北地来，闻声一半却飞回。","金河戍客腸應斷，更在秋风百尺台。"]', '诗', 'shi', '', NULL, '夜上西城聽梁州曲二首 二 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7315d4f1-4a61-43f8-ad46-6477d8dd50e1', '暖川', '暖川', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["胡風凍合鸊鵜泉，牧馬千羣逐暖川。","塞外征行無盡日，年年移帳雪中天。"]', '["胡风凍合鸊鵜泉，牧马千羣逐暖川。","塞外征行無尽日，年年移帳雪中天。"]', '诗', 'shi', '', NULL, '暖川 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9444dea4-3ec6-4ba6-b571-d569e203670e', '過馬嵬', '過马嵬', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["漢將如雲不直言，寇來翻罪綺羅恩。","託君休洗蓮花血，留記千年妾淚痕。"]', '["漢將如云不直言，寇来翻罪綺羅恩。","託君休洗蓮花血，留記千年妾泪痕。"]', '诗', 'shi', '', NULL, '過馬嵬 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('299a6ee7-7b3b-4ae4-9ea7-bdd82d956c9e', '答許五端公馬上口號', '答許五端公马上口號', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["晚逐旌旗俱白首，少遊京洛共緇塵。","不堪身外悲前事，強向杯中覓舊春。"]', '["晚逐旌旗俱白首，少游京洛共緇塵。","不堪身外悲前事，強向杯中覓旧春。"]', '诗', 'shi', '', NULL, '答許五端公馬上口號 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62bde81-05f7-447b-b605-de65e96056e6', '牡丹', '牡丹', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["紫蕊叢開未到家，却教遊客賞繁華。","始知年少求名處，滿眼空中別有花。"]', '["紫蕊叢开未到家，却教游客賞繁华。","始知年少求名处，满眼空中別有花。"]', '诗', 'shi', '', NULL, '牡丹 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d63850-8805-4c14-8f2a-843fc441ec0a', '邊思', '邊思', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["腰懸錦帶佩吳鉤，走馬曾防玉塞秋。","莫笑關西將家子，秪將詩思入涼州。"]', '["腰懸錦带佩吳鉤，走马曾防玉塞秋。","莫笑关西將家子，秪將诗思入涼州。"]', '诗', 'shi', '', NULL, '邊思 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('663ad068-30f8-4b38-816c-eecead23bc7e', '奉和武相公春曉聞鶯', '奉和武相公春晓闻鶯', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["蜀道山川心易驚，緣窗殘夢曉聞鶯。","分明似寫文君恨，萬怨千愁弦上聲。"]', '["蜀道山川心易驚，緣窗殘梦晓闻鶯。","分明似寫文君恨，万怨千愁弦上声。"]', '诗', 'shi', '', NULL, '奉和武相公春曉聞鶯 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f09de1-23c6-4900-8cfc-c9086e07ae5f', '送客還幽州', '送客還幽州', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["惆悵秦城送獨歸，薊門雲樹遠依依。","秋來莫射南飛雁，從遣乘春更北飛。"]', '["惆悵秦城送独归，薊门云樹远依依。","秋来莫射南飞雁，從遣乘春更北飞。"]', '诗', 'shi', '', NULL, '送客還幽州 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f07da970-0a2f-4b34-a09f-ff47b6830769', '柳楊送客', '柳楊送客', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["青楓江畔白蘋洲，楚客傷離不待秋。","君見隋朝更何事，柳楊南渡水悠悠。"]', '["青楓江畔白蘋洲，楚客傷離不待秋。","君见隋朝更何事，柳楊南渡水悠悠。"]', '诗', 'shi', '', NULL, '柳楊送客 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd1d28af-6231-4446-9d6a-fb76840dde90', '從軍北征', '從軍北征', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["天山雪後海風寒，橫笛偏吹行路難。","磧裏征人三十萬，一時回向月明看。"]', '["天山雪後海风寒，橫笛偏吹行路难。","磧裏征人三十万，一时回向月明看。"]', '诗', 'shi', '', NULL, '從軍北征 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('426eea46-266e-472d-8fe4-a558b28d18f9', '聽曉角', '听晓角', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["邊霜昨夜墮關榆，吹角當城漢月孤。","無限塞鴻飛不度，秋風卷入小單于。"]', '["邊霜昨夜墮关榆，吹角當城漢月孤。","無限塞鴻飞不度，秋风卷入小單于。"]', '诗', 'shi', '', NULL, '聽曉角 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ba7240c-f2c7-47b2-aab4-df61036655ca', '宮怨', '宮怨', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["露溼晴花春殿香，月明歌吹在昭陽。","似將海水添宮漏，共滴長門一夜長。"]', '["露溼晴花春殿香，月明歌吹在昭陽。","似將海水添宮漏，共滴长门一夜长。"]', '诗', 'shi', '', NULL, '宮怨 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d52cf95-a86a-4041-831f-3c16d568ccde', '暮過回樂烽', '暮過回乐烽', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["烽火高飛百尺臺，黃昏遙自磧西來。","昔時征戰回應樂，今日從軍樂未回。"]', '["烽火高飞百尺台，黄昏遙自磧西来。","昔时征戰回應乐，今日從軍乐未回。"]', '诗', 'shi', '', NULL, '暮過回樂烽 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef71c49c-0e5f-421e-b8da-f2a64606930e', '奉和武相公郊居寓目', '奉和武相公郊居寓目', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["黃扉晚下禁垣鐘，歸坐南闈山萬重。","獨有月中高興盡，雪峯明處見寒松。"]', '["黄扉晚下禁垣鐘，归坐南闈山万重。","独有月中高兴尽，雪峯明处见寒松。"]', '诗', 'shi', '', NULL, '奉和武相公郊居寓目 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a26bdee-c60a-47d7-8a6d-1d9d51783899', '詣紅樓院尋廣宣不遇留題', '詣紅楼院尋廣宣不遇留題', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["柿葉翻紅霜景秋，碧天如水倚紅樓。","隔窗愛竹無人問，遣向鄰房覓戶鉤。"]', '["柿葉翻紅霜景秋，碧天如水倚紅楼。","隔窗愛竹無人问，遣向鄰房覓戶鉤。"]', '诗', 'shi', '', NULL, '詣紅樓院尋廣宣不遇留題 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a841cfca-0ac2-4271-9ff0-34f87e837bbe', '回軍行', '回軍行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["關城榆葉早疎黃，日暮沙雲古戰場。","表請回軍掩塵骨，莫教士卒哭龍荒。"]', '["关城榆葉早疎黄，日暮沙云古戰場。","表請回軍掩塵骨，莫教士卒哭龙荒。"]', '诗', 'shi', '', NULL, '回軍行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a692edc-d3bd-4be8-8142-42e9d058030c', '邠寧春日', '邠寧春日', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["桃李年年上國新，風沙日日塞垣人。","傷心更見庭前柳，忽有千條欲占春。"]', '["桃李年年上国新，风沙日日塞垣人。","傷心更见庭前柳，忽有千條欲占春。"]', '诗', 'shi', '', NULL, '邠寧春日 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('699800d5-6ce3-4f34-8f68-78b6c32f7202', '古瑟怨', '古瑟怨', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["破瑟悲秋已減弦，湘靈沈怨不知年。","感君拂拭遺音在，更奏新聲明月天。"]', '["破瑟悲秋已減弦，湘靈沈怨不知年。","感君拂拭遺音在，更奏新声明月天。"]', '诗', 'shi', '', NULL, '古瑟怨 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f68fbbd0-6729-40b1-8707-b8349dd44177', '夜宴觀石將軍舞', '夜宴观石將軍舞', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["微月東南上戍樓，琵琶起舞錦纏頭。","更聞橫笛關山遠，白草胡沙西塞秋。"]', '["微月东南上戍楼，琵琶起舞錦纏头。","更闻橫笛关山远，白草胡沙西塞秋。"]', '诗', 'shi', '', NULL, '夜宴觀石將軍舞 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('590153bb-2f4d-419d-84ac-c4b9cb785a48', '春夜聞笛', '春夜闻笛', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["寒山吹笛喚春歸，遷客相看淚滿衣。","洞庭一夜無窮雁，不待天明盡北飛。"]', '["寒山吹笛喚春归，遷客相看泪满衣。","洞庭一夜無窮雁，不待天明尽北飞。"]', '诗', 'shi', '', NULL, '春夜聞笛 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6795f7bd-7a8b-452c-9c2a-ccf693710c85', '揚州送客', '揚州送客', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["南行直入鷓鴣羣，萬歲橋邊一送君。","聞道望鄉聞不得，梅花暗落嶺頭雲。"]', '["南行直入鷓鴣羣，万歲橋邊一送君。","闻道望乡闻不得，梅花暗落嶺头云。"]', '诗', 'shi', '', NULL, '揚州送客 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('772f7f55-f920-4217-9024-4b5232e96d57', '統漢峰下', '統漢峰下', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["統漢峰西降戶營，黃河戰骨擁長城。","只今已勒燕然石，北地無人空月明。"]', '["統漢峰西降戶營，黄河戰骨擁长城。","只今已勒燕然石，北地無人空月明。"]', '诗', 'shi', '', NULL, '統漢峰下 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83981b3-b9e0-4b94-9e63-a6392929acd6', '避暑女冠', '避暑女冠', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["霧袖煙裾雲母冠，碧琉璃簟井冰寒。","焚香欲使三清鳥，靜拂桐陰上玉壇。"]', '["霧袖煙裾云母冠，碧琉璃簟井冰寒。","焚香欲使三清鸟，静拂桐陰上玉壇。"]', '诗', 'shi', '', NULL, '避暑女冠 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3c1357-9b8c-4d13-aa5e-067758de57d0', '行舟', '行舟', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["柳花飛入正行舟，臥引菱花信碧流。","聞道風光滿揚子，天晴共上望鄉樓。"]', '["柳花飞入正行舟，臥引菱花信碧流。","闻道风光满揚子，天晴共上望乡楼。"]', '诗', 'shi', '', NULL, '行舟 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc5525c-1c63-4f1f-ac67-6aed44885d6e', '隋宮燕', '隋宮燕', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["燕語如傷舊國春，宮花一落已成塵。","自從一閉風光後，幾度飛來不見人。"]', '["燕語如傷旧国春，宮花一落已成塵。","自從一閉风光後，幾度飞来不见人。"]', '诗', 'shi', '', NULL, '隋宮燕 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48684889-1cbd-4b19-9768-be3c6b22d97e', '送人歸岳陽', '送人归岳陽', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["煙草連天楓樹齊，岳陽歸路子規啼。","春江萬里巴陵戍，落日看沈碧水西。"]', '["煙草連天楓樹齊，岳陽归路子規啼。","春江万里巴陵戍，落日看沈碧水西。"]', '诗', 'shi', '', NULL, '送人歸岳陽 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73b9a9a6-8fcf-47bf-a8f2-f4aaf3a1419a', '上汝州郡樓', '上汝州郡楼', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["黃昏鼓角似邊州，三十年前上此樓。","今日山城對垂淚，傷心不獨爲悲秋。"]', '["黄昏鼓角似邊州，三十年前上此楼。","今日山城对垂泪，傷心不独爲悲秋。"]', '诗', 'shi', '', NULL, '上汝州郡樓 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8806295e-05bb-40d8-9776-e4eaeee89d1a', '臨滹沱見蕃使列名', '臨滹沱见蕃使列名', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["漠南春色到滹沱，碧柳青青塞馬多。","萬里關山今不閉，漢家頻許郅支和。"]', '["漠南春色到滹沱，碧柳青青塞马多。","万里关山今不閉，漢家頻許郅支和。"]', '诗', 'shi', '', NULL, '臨滹沱見蕃使列名 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cb66aa8-e665-40b5-af59-253d8592f137', '寫情', '寫情', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["水紋珍簟思悠悠，千里佳期一夕休。","從此無心愛良夜，任他明月下西樓。"]', '["水紋珍簟思悠悠，千里佳期一夕休。","從此無心愛良夜，任他明月下西楼。"]', '诗', 'shi', '', NULL, '寫情 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('992df222-c445-4925-a656-0caa4447d5bb', '夜上受降城聞笛', '夜上受降城闻笛', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["回樂峰前沙似雪，受降城下月如霜。","不知何處吹蘆管，一夜征人盡望鄉。"]', '["回乐峰前沙似雪，受降城下月如霜。","不知何处吹蘆管，一夜征人尽望乡。"]', '诗', 'shi', '', NULL, '夜上受降城聞笛 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0b13311-ab59-4dc6-86e7-d201003dd201', '赴渭北宿石泉驛南望黃堆烽', '赴渭北宿石泉驛南望黄堆烽', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["邊城已在虜城中，烽火南飛入漢宮。","漢庭議事先黃老，麟閣何人定戰功。"]', '["邊城已在虜城中，烽火南飞入漢宮。","漢庭議事先黄老，麟閣何人定戰功。"]', '诗', 'shi', '', NULL, '赴渭北宿石泉驛南望黃堆烽 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed7f860f-572b-468f-a70a-d6b233f0cbc6', '逢歸信偶寄', '逢归信偶寄', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["無事將心寄柳條，等閑書字滿芭蕉。","鄉關若有東流信，遣送揚州近驛橋。"]', '["無事將心寄柳條，等闲书字满芭蕉。","乡关若有东流信，遣送揚州近驛橋。"]', '诗', 'shi', '', NULL, '逢歸信偶寄 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace9546f-5d4e-42ac-8f07-d4707030f7a4', '贈毛仙翁', '贈毛仙翁', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["玉樹溶溶仙氣深，含光混俗似無心。","長愁忽作鶴飛去，一片孤雲何處尋。"]', '["玉樹溶溶仙氣深，含光混俗似無心。","长愁忽作鹤飞去，一片孤云何处尋。"]', '诗', 'shi', '', NULL, '贈毛仙翁 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ce1049a-e49a-4c44-8092-8147c5b8efb3', '長干行', '长干行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["憶妾深閨裏，煙塵不曾識。","嫁與長干人，沙頭候風色。","五月南風興，思君下巴陵。","八月西風起，想君發揚子。","去來悲如何，見少離別多。","湘潭幾日到，妾夢越風波。","昨夜狂風度，吹折江頭樹。","渺渺暗無邊，行人在何處。","好乘浮雲驄，佳期蘭渚東。","鴛鴦綠浦上，翡翠錦屏中。","自憐十五餘，顏色桃花紅。","那作商人婦，愁水復愁風。"]', '["憶妾深閨裏，煙塵不曾識。","嫁與长干人，沙头候风色。","五月南风兴，思君下巴陵。","八月西风起，想君發揚子。","去来悲如何，见少離別多。","湘潭幾日到，妾梦越风波。","昨夜狂风度，吹折江头樹。","渺渺暗無邊，行人在何处。","好乘浮云驄，佳期蘭渚东。","鴛鴦綠浦上，翡翠錦屏中。","自怜十五餘，顏色桃花紅。","那作商人婦，愁水复愁风。"]', '诗', 'shi', '', NULL, '長干行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44376f7d-a0d4-415d-a846-ec6da52ba651', '和丘員外題湛長史舊居', '和丘員外題湛长史旧居', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["昔降英王顧。","屏身幽巖曲，靈波結繁笳。","爽籟赴鳴玉，運轉春華至。","歲來山草綠，青松掩落暉。","白雲竟空谷，伊人撫遺歎。","惻惻芳又縟，云誰斅美香。","分毫寄明牧。"]', '["昔降英王顧。","屏身幽巖曲，靈波結繁笳。","爽籟赴鳴玉，運轉春华至。","歲来山草綠，青松掩落暉。","白云竟空谷，伊人撫遺歎。","惻惻芳又縟，云誰斅美香。","分毫寄明牧。"]', '诗', 'shi', '', NULL, '和丘員外題湛長史舊居 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e0cd4ce-4297-420f-a4bf-92e48b38e5d2', '送客歸振武', '送客归振武', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["駿馬事輕車，軍行萬里沙。","胡山通嗢落，漢節繞渾邪。","桂滿天西月，蘆吹塞北笳。","別離俱報主，路極不爲賒。"]', '["駿马事轻车，軍行万里沙。","胡山通嗢落，漢節繞渾邪。","桂满天西月，蘆吹塞北笳。","別離俱報主，路極不爲賒。"]', '诗', 'shi', '', NULL, '送客歸振武 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7456cfc7-afe2-4f55-a95a-b6868ab10533', '府試古鏡', '府試古镜', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["舊是秦時鏡，今藏古匣中。","龍盤初挂月，鳳舞欲生風。","石黛曾留殿，朱光適在宮。","應祥知道泰，鑑物覺神通。","肝膽誠難隱，妍媸信易窮。","幸居君子室，長願免塵蒙。"]', '["旧是秦时镜，今藏古匣中。","龙盤初挂月，鳳舞欲生风。","石黛曾留殿，朱光適在宮。","應祥知道泰，鑑物覺神通。","肝膽誠难隐，妍媸信易窮。","幸居君子室，长願免塵蒙。"]', '诗', 'shi', '', NULL, '府試古鏡 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a937bf2-db04-4f01-8af7-4d0ea02c9657', '贈宣大師', '贈宣大師', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["一國沙彌獨解詩，人人道勝惠林師。","先皇詔下徵還日，今上龍飛入內時。","看月憶來松寺宿，尋花思作杏溪期。","因論佛地求心地，秪說常吟是住持。"]', '["一国沙彌独解诗，人人道勝惠林師。","先皇詔下徵還日，今上龙飞入內时。","看月憶来松寺宿，尋花思作杏溪期。","因論佛地求心地，秪说常吟是住持。"]', '诗', 'shi', '', NULL, '贈宣大師 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03aceab2-1bbe-4c0f-850b-b98d3760e35a', '漢宮詞', '漢宮词', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["漢室長陵小市東，珠簾繡戶對春風。","君王昨日移仙仗，玉輦將迎入漢中。"]', '["漢室长陵小市东，珠簾繡戶对春风。","君王昨日移仙仗，玉輦將迎入漢中。"]', '诗', 'shi', '', NULL, '漢宮詞 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b28eace-a2e8-4627-a7ef-02e3b901be8f', '江南曲', '江南曲', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["長樂花枝雨點銷，江城日暮好相邀。","春樓不閉葳蕤鎖，綠水回連宛轉橋。"]', '["长乐花枝雨点銷，江城日暮好相邀。","春楼不閉葳蕤鎖，綠水回連宛轉橋。"]', '诗', 'shi', '', NULL, '江南曲 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d171072-47a3-4daf-ba8f-202d4c47ce49', '宿石邑山中', '宿石邑山中', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["浮雲不共此山齊，山靄蒼蒼望轉迷。","曉月暫飛高樹裏，秋河隔在數峯西。"]', '["浮云不共此山齊，山靄蒼蒼望轉迷。","晓月暫飞高樹裏，秋河隔在數峯西。"]', '诗', 'shi', '', NULL, '宿石邑山中 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc1bf6ee-a6d6-4018-a194-1d6e084d36ab', '寄贈衡州楊使君', '寄贈衡州楊使君', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["湘竹斑斑湘水春，衡陽太守虎符新。","朝來笑向歸鴻道，早晚南飛見主人。"]', '["湘竹斑斑湘水春，衡陽太守虎符新。","朝来笑向归鴻道，早晚南飞见主人。"]', '诗', 'shi', '', NULL, '寄贈衡州楊使君 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d49e76-fc92-40cb-81cb-458828cdaf8d', '途中寄李二', '途中寄李二', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["楊柳含煙灞岸春，年年攀折爲行人。","好風若借低枝便，莫遣青絲掃路塵。"]', '["楊柳含煙灞岸春，年年攀折爲行人。","好风若借低枝便，莫遣青絲掃路塵。"]', '诗', 'shi', '', NULL, '途中寄李二 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b12f0f8a-a36e-446d-9607-e30772d52730', '寄許鍊師', '寄許鍊師', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["掃石焚香禮碧空，露華偏溼蕊珠宮。","如何說得天壇上，萬里無雲月在中。"]', '["掃石焚香禮碧空，露华偏溼蕊珠宮。","如何说得天壇上，万里無云月在中。"]', '诗', 'shi', '', NULL, '寄許鍊師 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3f3a8b5-83d2-4e36-a1c1-20d6d1a0d465', '失題', '失題', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["世故相逢各未閑，百年多在別離間。","昨夜秋風今夜雨，不知何處入空山。"]', '["世故相逢各未闲，百年多在別離间。","昨夜秋风今夜雨，不知何处入空山。"]', '诗', 'shi', '', NULL, '失題 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60adfcbb-87e0-4a68-851c-bb92ccc2f05a', '塞下曲', '塞下曲', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["伏波惟願裹尸還，定遠何須生入關。","莫遣隻輪歸海窟，仍留一箭射天山。"]', '["伏波惟願裹尸還，定远何須生入关。","莫遣隻輪归海窟，仍留一箭射天山。"]', '诗', 'shi', '', NULL, '塞下曲 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a17902-eb44-4244-9cd8-d60a4ac55f82', '上黃堆烽', '上黄堆烽', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["心期紫閣山中月，身過黃堆烽上雲。","年髮已從書劒老，戎衣更逐霍將軍。"]', '["心期紫閣山中月，身過黄堆烽上云。","年髮已從书劒老，戎衣更逐霍將軍。"]', '诗', 'shi', '', NULL, '上黃堆烽 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ab7b24-b25e-4492-88de-16a5eb4c2008', '句', '句', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["閑庭草色能留馬，當路楊花不避人。"]', '["闲庭草色能留马，當路楊花不避人。"]', '诗', 'shi', '', NULL, '句 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff6d2d68-17c4-4204-8d54-0203177c730b', '古別離二首 一', '古別離二首 一', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["水國葉黃時，洞庭霜落夜。","行舟聞商估，宿在楓林下。","此地送君還，茫茫似夢間。","後期知幾日，前路轉多山。","巫峽通湘浦，迢迢隔雲雨。","天晴見海檣，月落聞津鼓。","人老自多愁，水深難急流。","清宵歌一曲，白首對汀洲。"]', '["水国葉黄时，洞庭霜落夜。","行舟闻商估，宿在楓林下。","此地送君還，茫茫似梦间。","後期知幾日，前路轉多山。","巫峽通湘浦，迢迢隔云雨。","天晴见海檣，月落闻津鼓。","人老自多愁，水深难急流。","清宵歌一曲，白首对汀洲。"]', '诗', 'shi', '', NULL, '古別離二首 一 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c3ab4a7-a3d1-46bc-a942-1bb035d0e86b', '古別離二首 二', '古別離二首 二', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["與君桂陽別，令君岳陽待。","後事忽差池，前期日空在。","木落雁嗷嗷，洞庭波浪高。","遠山雲似蓋，極浦樹如毫。","朝發能幾里，暮來風又起。","如何兩處愁，皆在孤舟裏。","昨夜天月明，長川寒且清。","菊花開欲盡，薺菜泊來生。","下江帆勢速，五兩遙相逐。","欲問去時人，知投何處宿。","空令猿嘯時泣對湘簟竹。"]', '["與君桂陽別，令君岳陽待。","後事忽差池，前期日空在。","木落雁嗷嗷，洞庭波浪高。","远山云似蓋，極浦樹如毫。","朝發能幾里，暮来风又起。","如何兩处愁，皆在孤舟裏。","昨夜天月明，长川寒且清。","菊花开欲尽，薺菜泊来生。","下江帆勢速，五兩遙相逐。","欲问去时人，知投何处宿。","空令猿嘯时泣对湘簟竹。"]', '诗', 'shi', '', NULL, '古別離二首 二 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61194804-f2d2-41bc-a43e-a774f80f26dd', '折楊柳', '折楊柳', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["東城攀柳葉，柳葉低着草。","少壯莫輕年，輕年有衰老。","柳發遍川岡，登高堪斷腸。","雨煙輕漠漠，何樹近君鄉。","贈君折楊柳，顏色豈能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳傷君情。","突兀臨荒渡，婆娑出舊營。","隋家兩岸盡，陶宅五株榮。","日暮偏愁望，春山有鳥聲。"]', '["东城攀柳葉，柳葉低着草。","少壯莫轻年，轻年有衰老。","柳發遍川岡，登高堪斷腸。","雨煙轻漠漠，何樹近君乡。","贈君折楊柳，顏色豈能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳傷君情。","突兀臨荒渡，婆娑出旧營。","隋家兩岸尽，陶宅五株榮。","日暮偏愁望，春山有鸟声。"]', '诗', 'shi', '', NULL, '折楊柳 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d528ff85-134d-4d1d-86ba-e6053487bd8a', '留別柳中庸', '留別柳中庸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["惆悵流水時，蕭條背城路。","離人出古亭，嘶馬入寒樹。","江海正風波，相逢在何處。"]', '["惆悵流水时，蕭條背城路。","離人出古亭，嘶马入寒樹。","江海正风波，相逢在何处。"]', '诗', 'shi', '', NULL, '留別柳中庸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('553ab62d-c697-480c-96a3-c9f93da53fc1', '野亭三韻送錢員外', '野亭三韻送錢員外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["野菊開欲稀，寒泉流漸淺。","幽人步林後，歎此年華晚。","倚杖送行雲，尋思故山遠。"]', '["野菊开欲稀，寒泉流漸淺。","幽人步林後，歎此年华晚。","倚杖送行云，尋思故山远。"]', '诗', 'shi', '', NULL, '野亭三韻送錢員外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96851a23-f8c1-49ea-8e6b-1d7063b8d0ad', '歸山招王逵', '归山招王逵', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["日長原野靜，杖策步幽巘。","雉雊麥苗陰，蝶飛溪草晚。","我生好閒放，此去殊未返。","自是君不來，非關故山遠。"]', '["日长原野静，杖策步幽巘。","雉雊麦苗陰，蝶飞溪草晚。","我生好閒放，此去殊未返。","自是君不来，非关故山远。"]', '诗', 'shi', '', NULL, '歸山招王逵 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa9dfb2-4e4a-4c51-bd1f-bb28049777d9', '過谷口元贊善所居', '過谷口元贊善所居', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["入谷訪君來，秋泉已堪涉。","林間人獨坐，月下山相接。","重露濕蒼苔，明燈照黃葉。","故交一不見，素髮何稠疊。"]', '["入谷訪君来，秋泉已堪涉。","林间人独坐，月下山相接。","重露濕蒼苔，明灯照黄葉。","故交一不见，素髮何稠叠。"]', '诗', 'shi', '', NULL, '過谷口元贊善所居 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b829019-582f-4b44-8e25-f6ef247fcb6b', '旅次岐山得山友書却寄鳳翔張尹', '旅次岐山得山友书却寄鳳翔張尹', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["本與戴徵君，同師竹上坐。","偶爲名利引，久廢論真果。","昨日山信迴，寄書來責我。"]', '["本與戴徵君，同師竹上坐。","偶爲名利引，久廢論真果。","昨日山信迴，寄书来責我。"]', '诗', 'shi', '', NULL, '旅次岐山得山友書却寄鳳翔張尹 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('169db1f4-0f3e-49d4-b6a7-ac3d6ddea9ed', '九日贈司空文明', '九日贈司空文明', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["我有惆悵詞，待君醉時說。","長來逢九日，難與菊花別。","摘却正開花，暫言花未發。"]', '["我有惆悵词，待君醉时说。","长来逢九日，难與菊花別。","摘却正开花，暫言花未發。"]', '诗', 'shi', '', NULL, '九日贈司空文明 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1187b7da-e4e4-4d63-800b-3e6e9d99d57e', '蕪城', '蕪城', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["昔人登此地，丘隴已前悲。","今日又非昔，春風能幾時。","風吹城上樹，草沒城邊路。","城裏月明時，精靈自來去。"]', '["昔人登此地，丘隴已前悲。","今日又非昔，春风能幾时。","风吹城上樹，草沒城邊路。","城裏月明时，精靈自来去。"]', '诗', 'shi', '', NULL, '蕪城 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dde00080-96a2-45aa-a780-f19ced0019c5', '送吉中孚拜官歸楚州', '送吉中孚拜官归楚州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["才子神骨清，虛竦眉眼明。","貌應同衞玠，鬢且異潘生。","初戴莓苔幘，來過丞相宅。","滿堂歸道師，衆口宗詩伯。","須臾里巷傳，天子亦知賢。","出詔升高士，馳聲在少年。","自爲才哲愛，日與侯王會。","匡主一言中，榮親千里外。","更聞仙士友，往往東回首。","驅石不成羊，指丹空斃狗。","孤帆淮上歸，商估夜相依。","海霧寒將盡，天星曉欲稀。","潮頭來始歇，浦口喧爭發。","鄉樹尚和雲，鄰船猶帶月。","到洞必傷情，巡房見舊名。","醮疎壇路澀，汲少井欄傾。","別我長安道，前期共須老。","方隨水向山，肯惜花辭島。","悵望執君衣，今朝風景好。"]', '["才子神骨清，虛竦眉眼明。","貌應同衞玠，鬢且異潘生。","初戴莓苔幘，来過丞相宅。","满堂归道師，衆口宗诗伯。","須臾里巷傳，天子亦知賢。","出詔升高士，驰声在少年。","自爲才哲愛，日與侯王會。","匡主一言中，榮親千里外。","更闻仙士友，往往东回首。","驱石不成羊，指丹空斃狗。","孤帆淮上归，商估夜相依。","海霧寒將尽，天星晓欲稀。","潮头来始歇，浦口喧爭發。","乡樹尚和云，鄰船猶带月。","到洞必傷情，巡房见旧名。","醮疎壇路澀，汲少井欄傾。","別我长安道，前期共須老。","方隨水向山，肯惜花辞島。","悵望執君衣，今朝风景好。"]', '诗', 'shi', '', NULL, '送吉中孚拜官歸楚州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a9c152-dc44-4c44-a610-c84ca4d1d2e3', '荆州泊', '荆州泊', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["南樓西下時，月裏聞來棹。","桂水舳艫迴，荆州津濟鬧。","移帷望星漢，引帶思容貌。","今夜一江人，唯應妾身覺。"]', '["南楼西下时，月裏闻来棹。","桂水舳艫迴，荆州津濟鬧。","移帷望星漢，引带思容貌。","今夜一江人，唯應妾身覺。"]', '诗', 'shi', '', NULL, '荆州泊 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2859c7f7-5ebd-4ed0-8b4a-2d8212dbcc14', '春遊樂', '春游乐', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["遊童蘇合彈，倡女蒲葵扇。","初日映城時，相思忽相見。","褰裳蹋路草，理鬢回花面。","薄暮不同歸，留情此芳甸。"]', '["游童蘇合彈，倡女蒲葵扇。","初日映城时，相思忽相见。","褰裳蹋路草，理鬢回花面。","薄暮不同归，留情此芳甸。"]', '诗', 'shi', '', NULL, '春遊樂 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de1797c7-0c10-4d76-aac3-68dbfbf82b77', '千里思', '千里思', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["涼州風月美，遙望居延路。","汎汎下天雲，青青緣塞樹。","燕山蘇武上，海島田橫住。","更是草生時，行人出門去。"]', '["涼州风月美，遙望居延路。","汎汎下天云，青青緣塞樹。","燕山蘇武上，海島田橫住。","更是草生时，行人出门去。"]', '诗', 'shi', '', NULL, '千里思 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b2a69d8-3a60-4fea-b23b-eb83f81622f6', '白鷺詠', '白鷺詠', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["迥起來應近，高飛去自遙。","映林同落雪，拂水狀飜潮。","猶有幽人興，相逢到碧霄。"]', '["迥起来應近，高飞去自遙。","映林同落雪，拂水狀飜潮。","猶有幽人兴，相逢到碧霄。"]', '诗', 'shi', '', NULL, '白鷺詠 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a7e803-e3b8-4ebe-9dc1-2869c23122e9', '冬夜與故友聚送吉校書', '冬夜與故友聚送吉校书', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["途窮別則怨，何必天涯去。","共作出門人，不見歸鄉路。","殷勤執杯酒，悵望送親故。","月色入閒軒，風聲落高樹。","雲霄望且遠，齒髮行應暮。","九日泣黃花，三秋悲白露。","君行過洛陽，莫向青山度。"]', '["途窮別則怨，何必天涯去。","共作出门人，不见归乡路。","殷勤執杯酒，悵望送親故。","月色入閒軒，风声落高樹。","云霄望且远，齒髮行應暮。","九日泣黄花，三秋悲白露。","君行過洛陽，莫向青山度。"]', '诗', 'shi', '', NULL, '冬夜與故友聚送吉校書 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314d0c08-7c56-47a8-bc40-f48ef0742396', '與苗員外山行', '與苗員外山行', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["古人留路去，今日共君行。","若待青山盡，應逢白髮生。","誰知到蘭若，流落一書名。"]', '["古人留路去，今日共君行。","若待青山尽，應逢白髮生。","誰知到蘭若，流落一书名。"]', '诗', 'shi', '', NULL, '與苗員外山行 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e8854d8-650e-4e80-b95a-6a40679681cd', '早春同庾侍郎題青龍上方院', '早春同庾侍郎題青龙上方院', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["相見惜餘輝，齊行登古寺。","風煙結遠恨，山水含芳意。","車馬莫前歸，留看巢鶴至。"]', '["相见惜餘輝，齊行登古寺。","风煙結远恨，山水含芳意。","车马莫前归，留看巢鹤至。"]', '诗', 'shi', '', NULL, '早春同庾侍郎題青龍上方院 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98956e6-9415-4374-bfca-925ca2b91243', '送從叔赴洪州', '送從叔赴洪州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["榮家兼佐幕，叔父似還鄉。","王粲名雖重，郄超髯未長。","鳴橈過夏口，斂笏見潯陽。","後夜相思處，中庭月一方。"]', '["榮家兼佐幕，叔父似還乡。","王粲名雖重，郄超髯未长。","鳴橈過夏口，斂笏见潯陽。","後夜相思处，中庭月一方。"]', '诗', 'shi', '', NULL, '送從叔赴洪州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da45d665-c7b9-4403-b2f8-e2c30bfbd188', '送路司諫侍從叔赴洪州', '送路司諫侍從叔赴洪州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["郄超本絕倫，得意在芳春。","勳業耿家盛，風流荀氏均。","聲名金作賦，白皙玉爲身。","斂笏辭天子，乘龜從丈人。","度關行且獵，鞍馬何躞蹀。","猿嘯暮應愁，湖流春好涉。","潯陽水分送，于越山相接。","梅雨細如絲，蒲帆輕似葉。","逢風燕不定，值石波先疊。","樓見遠公廬，船經徐穉業。","邑人多秉筆，州吏亦負笈。","村女解收魚，津童能用檝。","唯我有荆扉，無成未得歸。","見君兄弟出，今日自霑衣。"]', '["郄超本絕倫，得意在芳春。","勳業耿家盛，风流荀氏均。","声名金作賦，白皙玉爲身。","斂笏辞天子，乘龟從丈人。","度关行且獵，鞍马何躞蹀。","猿嘯暮應愁，湖流春好涉。","潯陽水分送，于越山相接。","梅雨細如絲，蒲帆轻似葉。","逢风燕不定，值石波先叠。","楼见远公廬，船經徐穉業。","邑人多秉笔，州吏亦負笈。","村女解收鱼，津童能用檝。","唯我有荆扉，無成未得归。","见君兄弟出，今日自霑衣。"]', '诗', 'shi', '', NULL, '送路司諫侍從叔赴洪州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64ab14be-6565-4ac9-aa39-4a9e40d92023', '病後遊青龍寺', '病後游青龙寺', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["病來形貌穢，齋沫入東林。","境靜聞神遠，身羸向道深。","芭蕉高自折，荷葉大先沈。"]', '["病来形貌穢，斋沫入东林。","境静闻神远，身羸向道深。","芭蕉高自折，荷葉大先沈。"]', '诗', 'shi', '', NULL, '病後遊青龍寺 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e802bf07-532a-4c10-a92a-baf6eaa25c29', '夜尋司空文明逢深上人因寄晉侍御', '夜尋司空文明逢深上人因寄晉侍御', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["鶴裘筇竹杖，語笑過林中。","正是月明夜，陶家見遠公。","自嫌山客務，不與漢官同。"]', '["鹤裘筇竹杖，語笑過林中。","正是月明夜，陶家见远公。","自嫌山客務，不與漢官同。"]', '诗', 'shi', '', NULL, '夜尋司空文明逢深上人因寄晉侍御 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc66b4b1-8c6f-4b27-8abb-27028bd76e2a', '長安書事寄薛戴', '长安书事寄薛戴', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["朔雁去成行，哀蟬響如昨。","時芳一憔悴，暮序何蕭索。","笑語且無聊，逢迎多約略。","三山不可見，百歲空揮霍。","故事盡爲愁，新知無復樂。","夫君又離別，而我加寂寞。","惠遠縱相尋，陶潛祗獨酌。","主人恩則厚，客子才自薄。","委曲見提攜，因循成蹇剝。","論邊書未上，招隱詩還作。","貴者已朝餐，豈能敦宿諾。","飛禽雖失樹，流水長思壑。","千里寄瓊枝，夢寐青山郭。"]', '["朔雁去成行，哀蟬响如昨。","时芳一憔悴，暮序何蕭索。","笑語且無聊，逢迎多約略。","三山不可见，百歲空揮霍。","故事尽爲愁，新知無复乐。","夫君又離別，而我加寂寞。","惠远縱相尋，陶潛祗独酌。","主人恩則厚，客子才自薄。","委曲见提携，因循成蹇剝。","論邊书未上，招隐诗還作。","貴者已朝餐，豈能敦宿諾。","飞禽雖失樹，流水长思壑。","千里寄瓊枝，梦寐青山郭。"]', '诗', 'shi', '', NULL, '長安書事寄薛戴 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac0a7d0-2347-4647-8165-9dca1bef2530', '鮮于少府宅看花', '鲜于少府宅看花', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["謝家能植藥，萬簇相縈倚。","爛熳綠苔前，嬋娟青草裏。","垂欄復照戶，映竹仍臨水。","驟雨發芳香，迴風舒錦綺。","孤光雜新故，衆色更重累。","散碧出疎莖，分黃成細蘂。","遊蜂高更下，驚蝶坐還起。","玉貌對應慙，霞標方不似。","春陰憐弱蔓，夏日同短晷。","迴落報榮衰，交關鬬紅紫。","花時苟未賞，老至誰能止。","上客屢移牀，幽僧勞憑几。","初合雖薄劣，却得陪君子。","敢問賢主人，何如種桃李。"]', '["謝家能植藥，万簇相縈倚。","爛熳綠苔前，嬋娟青草裏。","垂欄复照戶，映竹仍臨水。","驟雨發芳香，迴风舒錦綺。","孤光杂新故，衆色更重累。","散碧出疎莖，分黄成細蘂。","游蜂高更下，驚蝶坐還起。","玉貌对應慙，霞標方不似。","春陰怜弱蔓，夏日同短晷。","迴落報榮衰，交关鬬紅紫。","花时苟未賞，老至誰能止。","上客屢移牀，幽僧勞憑几。","初合雖薄劣，却得陪君子。","敢问賢主人，何如種桃李。"]', '诗', 'shi', '', NULL, '鮮于少府宅看花 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('667d65f5-9f24-4abd-b635-214ba34533bb', '慈恩寺懷舊', '慈恩寺懷旧', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["去者不可憶，舊遊相見時。","凌霄徒更發，非是看花期。","倚玉交文友，登龍年月久。","東閣許聯牀，西郊亦攜手。","彼蒼何暖昧，薄劣翻居後。","重入遠師谿，誰嘗陶令酒。","伊昔會禪宮，容輝在眼中。","籃輿來問道，玉柄解談空。","孔席亡顏子，僧堂失謝公。","遺文一書壁，新竹再移叢。","始聚終成散，朝歡暮不同。","春霞方照日，夜燭忽迎風。","蟻鬬聲猶在，鴞災道已窮。","問天應默默，歸宅太匆匆。","淒其履還路，莽蒼雲林暮。","九陌似無人，五陵空有霧。","緬懷山陽笛，永恨平原賦。","錯莫過門欄，分明識行路。","上智本全真，郄公況重臣。","唯應撫靈運，暫是憶嘉賓。","存信松猶小，緘哀草尚新。","鯉庭埋玉樹，那忍見門人。"]', '["去者不可憶，旧游相见时。","凌霄徒更發，非是看花期。","倚玉交文友，登龙年月久。","东閣許聯牀，西郊亦携手。","彼蒼何暖昧，薄劣翻居後。","重入远師谿，誰嘗陶令酒。","伊昔會禪宮，容輝在眼中。","籃輿来问道，玉柄解談空。","孔席亡顏子，僧堂失謝公。","遺文一书壁，新竹再移叢。","始聚終成散，朝歡暮不同。","春霞方照日，夜燭忽迎风。","蟻鬬声猶在，鴞災道已窮。","问天應默默，归宅太匆匆。","淒其履還路，莽蒼云林暮。","九陌似無人，五陵空有霧。","緬懷山陽笛，永恨平原賦。","錯莫過门欄，分明識行路。","上智本全真，郄公況重臣。","唯應撫靈運，暫是憶嘉賓。","存信松猶小，緘哀草尚新。","鯉庭埋玉樹，那忍见门人。"]', '诗', 'shi', '', NULL, '慈恩寺懷舊 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e5d503c-12ee-4e2c-a645-80e5e892316b', '贈薛戴', '贈薛戴', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["曉霧忽爲霜，寒蟬還罷響。","行人在長道，日暮多歸想。","射策本何功，名登絳帳中。","遂矜丘室重，不料阮途窮。","交結慙時輩，龍鍾似老翁。","機非鄙夫正，懶是平生性。","欹枕鴻雁高，閉關花藥盛。","廚煙當雨絕，階竹連窗暝。","欲賦苦饑行，無如消渴病。","舊業歷胡塵，荒原少四鄰。","田園空有處，兄弟未成人。","毛義心長苦，袁安家轉貧。","今呈胸臆事，當爲淚沾巾。"]', '["晓霧忽爲霜，寒蟬還罷响。","行人在长道，日暮多归想。","射策本何功，名登絳帳中。","遂矜丘室重，不料阮途窮。","交結慙时輩，龙鍾似老翁。","機非鄙夫正，懶是平生性。","欹枕鴻雁高，閉关花藥盛。","廚煙當雨絕，階竹連窗暝。","欲賦苦饑行，無如消渴病。","旧業歷胡塵，荒原少四鄰。","田园空有处，兄弟未成人。","毛義心长苦，袁安家轉貧。","今呈胸臆事，當爲泪沾巾。"]', '诗', 'shi', '', NULL, '贈薛戴 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd9a856-d137-4760-8431-47fd482be3d3', '東門送客', '东门送客', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["綠楊新草路，白髮故鄉人。","既壯還應老，遊梁復滯秦。","逢花莫漫折，能有幾多春。"]', '["綠楊新草路，白髮故乡人。","既壯還應老，游梁复滯秦。","逢花莫漫折，能有幾多春。"]', '诗', 'shi', '', NULL, '東門送客 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3df845a-eee5-4b84-beb4-0bdeb09cf264', '送韓紳卿', '送韓紳卿', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["春雨昨開花，秋霜忽霑草。","榮枯催日夕，去住皆須老。","君望漢家原，高墳漸成道。"]', '["春雨昨开花，秋霜忽霑草。","榮枯催日夕，去住皆須老。","君望漢家原，高墳漸成道。"]', '诗', 'shi', '', NULL, '送韓紳卿 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77076b15-6e9b-4d55-81c8-89f66b33a428', '襄陽曲', '襄陽曲', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["襄陽堤路長，草碧柳枝黃。","誰家女兒臨夜妝，紅羅帳裏有燈光。","雀釵翠羽動明璫，欲出不出脂粉香。","同居女伴正衣裳，中庭寒月白如霜。","賈生十八稱才子，空得門前一斷腸。"]', '["襄陽堤路长，草碧柳枝黄。","誰家女兒臨夜妝，紅羅帳裏有灯光。","雀釵翠羽动明璫，欲出不出脂粉香。","同居女伴正衣裳，中庭寒月白如霜。","賈生十八稱才子，空得门前一斷腸。"]', '诗', 'shi', '', NULL, '襄陽曲 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2a2bee8-b67a-47b5-a061-3e571e8371c9', '胡騰兒', '胡腾兒', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["胡騰身是涼州兒，肌膚如玉鼻如錐。","桐布輕衫前後卷，葡萄長帶一邊垂。","帳前跪作本音語，拾襟攪袖爲君舞。","安西舊牧收淚看，洛下詞人抄曲與。","揚眉動目踏花氈，紅汗交流珠帽偏。","醉却東傾又西倒，雙靴柔弱滿燈前。","環行急蹴皆應節，反手叉腰如却月。","絲桐忽奏一曲終，嗚嗚畫角城頭發。","胡騰兒，胡騰兒，故鄉路斷知不知。"]', '["胡腾身是涼州兒，肌膚如玉鼻如錐。","桐布轻衫前後卷，葡萄长带一邊垂。","帳前跪作本音語，拾襟攪袖爲君舞。","安西旧牧收泪看，洛下词人抄曲與。","揚眉动目踏花氈，紅汗交流珠帽偏。","醉却东傾又西倒，雙靴柔弱满灯前。","环行急蹴皆應節，反手叉腰如却月。","絲桐忽奏一曲終，嗚嗚畫角城头發。","胡腾兒，胡腾兒，故乡路斷知不知。"]', '诗', 'shi', '', NULL, '胡騰兒 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86909f2e-2ccb-40d2-8773-8bdec8006cce', '贈康洽', '贈康洽', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["黃鬚康兄酒泉客，平生出入王侯宅。","今朝醉臥又明朝，忽憶故鄉頭已白。","流年恍惚瞻西日，陳事蒼茫指南陌。","聲名恆壓鮑參軍，班位不過揚執戟。","邇來七十遂無機，空是咸陽一布衣。","後輩輕肥賤衰朽，五侯門館許因依。","自言萬物有移改，始信桑田變成海。","同時獻賦人皆盡，共壁題詩君獨在。","步出東城風景和，青山滿眼少年多。","漢家尚壯今則老，髮短心長知奈何。","華堂舉杯白日晚，龍鍾相見誰能免。","君今已反我正來，朱顏宜笑能幾回。","借問朦朧花樹下，誰家畚插築高臺。"]', '["黄鬚康兄酒泉客，平生出入王侯宅。","今朝醉臥又明朝，忽憶故乡头已白。","流年恍惚瞻西日，陳事蒼茫指南陌。","声名恆壓鲍參軍，班位不過揚執戟。","邇来七十遂無機，空是咸陽一布衣。","後輩轻肥賤衰朽，五侯门館許因依。","自言万物有移改，始信桑田变成海。","同时獻賦人皆尽，共壁題诗君独在。","步出东城风景和，青山满眼少年多。","漢家尚壯今則老，髮短心长知奈何。","华堂舉杯白日晚，龙鍾相见誰能免。","君今已反我正来，朱顏宜笑能幾回。","借问朦朧花樹下，誰家畚插築高台。"]', '诗', 'shi', '', NULL, '贈康洽 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5785bfff-5e2a-46bf-95ef-6737f20a6993', '瘦馬行', '瘦马行', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["城傍牧馬驅未過，一馬徘徊起還臥。","眼中有淚皮有瘡，骨毛焦瘦令人傷。","朝朝放在兒童手，誰覺舉頭看故鄉。","往時漢地相馳逐，如雨如風過平陸。","豈意今朝驅不前，蚊蚋滿身泥上腹。","路人識是名馬兒，疇昔三軍不得騎。","玉勒金鞍既已遠，追奔獲獸有誰知。","終身櫪上食君草，遂與駑駘一時老。","儻借長鳴隴上風，猶期一戰安西道。"]', '["城傍牧马驱未過，一马徘徊起還臥。","眼中有泪皮有瘡，骨毛焦瘦令人傷。","朝朝放在兒童手，誰覺舉头看故乡。","往时漢地相驰逐，如雨如风過平陸。","豈意今朝驱不前，蚊蚋满身泥上腹。","路人識是名马兒，疇昔三軍不得騎。","玉勒金鞍既已远，追奔獲獸有誰知。","終身櫪上食君草，遂與駑駘一时老。","儻借长鳴隴上风，猶期一戰安西道。"]', '诗', 'shi', '', NULL, '瘦馬行 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c98ec8b-0757-420a-8171-fd439d8c150f', '雜歌呈鄭錫司空文明', '杂歌呈鄭錫司空文明', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["昨宵夢到亡何鄉，忽見一人山之陽。","高冠長劍立石堂，鬢眉颯爽瞳子方。","胡麻作飯瓊作漿，素書一帙在柏牀。","啖我還丹拍我背，令我延年在人代。","乃書數字與我持，小兒歸去須讀之。","覺來知是虛無事，山中雪平雲覆地。","東嶺啼猿三四聲，卷簾一望心堪碎。","蓬萊有梯不可躡，向海回頭淚盈睫。","且聞童子是蒼蠅，誰謂莊生異蝴蝶。","學仙去來辭故人，長安道路多風塵。"]', '["昨宵梦到亡何乡，忽见一人山之陽。","高冠长劍立石堂，鬢眉颯爽瞳子方。","胡麻作飯瓊作漿，素书一帙在柏牀。","啖我還丹拍我背，令我延年在人代。","乃书數字與我持，小兒归去須读之。","覺来知是虛無事，山中雪平云覆地。","东嶺啼猿三四声，卷簾一望心堪碎。","蓬萊有梯不可躡，向海回头泪盈睫。","且闻童子是蒼蠅，誰謂莊生異蝴蝶。","学仙去来辞故人，长安道路多风塵。"]', '诗', 'shi', '', NULL, '雜歌呈鄭錫司空文明 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd7acac-92da-4afa-b14d-010bb5e9da52', '雜歌', '杂歌', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["漢水至清泥則濁，松枝至堅蘿則弱。","十三女兒事他家，顏色如花終索寞。","蘭生當門燕巢幙，蘭芽未吐燕泥落。","爲姑偏忌諸嫂良，作婦翻嫌壻家惡。","人生照鏡須自知，無鹽何用妬西施。","秦庭野鹿忽爲馬，巧僞亂真君試思。","伯奇掇蜂賢父逐，曾參殺人慈母疑。","酒沽千日人不醉，琴弄一弦心已悲。","常聞善交無爾汝，讒口甚甘良藥苦。","山雞錦翼豈鳳凰，隴鳥人言止鸚鵡。","向栩非才徒隱竈，田文有命那關戶。","犀燭江行見鬼神，木人登席呈歌舞。","樂生東去終居趙，陽虎北轅飜適楚。","世間反覆不易陳，緘此貽君淚如雨。"]', '["漢水至清泥則濁，松枝至堅蘿則弱。","十三女兒事他家，顏色如花終索寞。","蘭生當门燕巢幙，蘭芽未吐燕泥落。","爲姑偏忌諸嫂良，作婦翻嫌壻家惡。","人生照镜須自知，無鹽何用妬西施。","秦庭野鹿忽爲马，巧僞亂真君試思。","伯奇掇蜂賢父逐，曾參殺人慈母疑。","酒沽千日人不醉，琴弄一弦心已悲。","常闻善交無爾汝，讒口甚甘良藥苦。","山雞錦翼豈鳳凰，隴鸟人言止鸚鵡。","向栩非才徒隐竈，田文有命那关戶。","犀燭江行见鬼神，木人登席呈歌舞。","乐生东去終居趙，陽虎北轅飜適楚。","世间反覆不易陳，緘此貽君泪如雨。"]', '诗', 'shi', '', NULL, '雜歌 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29349510-7c20-4105-b50d-258ce53a8523', '烏栖曲', '烏栖曲', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["白馬逐朱車，黃昏入狹斜。","狹斜柳樹烏爭宿，爭枝未得飛上屋。","東房少婦壻從軍，每聽烏啼知夜分。"]', '["白马逐朱车，黄昏入狹斜。","狹斜柳樹烏爭宿，爭枝未得飞上屋。","东房少婦壻從軍，每听烏啼知夜分。"]', '诗', 'shi', '', NULL, '烏栖曲 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12cdd629-7c39-4d78-bfcc-246cffbb7127', '送客東歸', '送客东归', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["昨夜東風吹盡雪，兩京路上梅花發。","行人相見便東西，日暮溪頭飲馬別。","把君衫袖望垂楊，兩行淚下思故鄉。"]', '["昨夜东风吹尽雪，兩京路上梅花發。","行人相见便东西，日暮溪头饮马別。","把君衫袖望垂楊，兩行泪下思故乡。"]', '诗', 'shi', '', NULL, '送客東歸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0394c9f-7d5a-4880-a96a-b9211aecc6db', '王敬伯歌', '王敬伯歌', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["妾本舟中女，聞君江上琴。","君初感妾意，妾亦感君心。","遂出合歡被，同爲交頸禽。","傳杯唯畏淺，接膝猶嫌遠。","侍婢奏箜篌，女郎歌宛轉。","宛轉怨如何，中庭霜漸多。","霜多葉可惜，昨日非今夕。","徒結萬重歡，終成一宵客。","王敬伯，綠水青山從此隔。"]', '["妾本舟中女，闻君江上琴。","君初感妾意，妾亦感君心。","遂出合歡被，同爲交頸禽。","傳杯唯畏淺，接膝猶嫌远。","侍婢奏箜篌，女郎歌宛轉。","宛轉怨如何，中庭霜漸多。","霜多葉可惜，昨日非今夕。","徒結万重歡，終成一宵客。","王敬伯，綠水青山從此隔。"]', '诗', 'shi', '', NULL, '王敬伯歌 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e321d83c-6578-4f48-a774-aa4abc5d4f9d', '救生寺望春寄暢當', '救生寺望春寄暢當', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["東西南北望，望遠悲潛蓄。","紅黃綠紫花，花開看不足。","今年與子少相隨，他年與子老相逐。"]', '["东西南北望，望远悲潛蓄。","紅黄綠紫花，花开看不足。","今年與子少相隨，他年與子老相逐。"]', '诗', 'shi', '', NULL, '救生寺望春寄暢當 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1acf8579-cac4-4305-82f6-de716ca26a76', '荆門歌送兄赴夔州', '荆门歌送兄赴夔州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["余兄佐郡經西楚，餞行因賦荆門雨。","𩆵𩆵燮燮聲漸繁，浦裏人家收市喧。","重陰大點過欲盡，碎浪柔文相與飜。","雲間悵望荆衡路，萬里青山一時暮。","琵琶寺裏響空廊，熨斗陂前濕荒戍。","沙尾長檣發漸稀，竹竿草屩涉流歸。","夷陵已遠半成燒，漢上游倡始濯衣。","船門相對多商估，葛服龍鍾篷下語。","自是湘州石燕飛，那關齊地商羊舞。","曾爲江客念江行，腸斷秋荷雨打聲。","摩天古木不可見，住岳高僧空得名。","今朝拜首臨欲別，遙憶荆門雨中發。"]', '["余兄佐郡經西楚，餞行因賦荆门雨。","𩆵𩆵燮燮声漸繁，浦裏人家收市喧。","重陰大点過欲尽，碎浪柔文相與飜。","云间悵望荆衡路，万里青山一时暮。","琵琶寺裏响空廊，熨斗陂前濕荒戍。","沙尾长檣發漸稀，竹竿草屩涉流归。","夷陵已远半成燒，漢上游倡始濯衣。","船门相对多商估，葛服龙鍾篷下語。","自是湘州石燕飞，那关齊地商羊舞。","曾爲江客念江行，腸斷秋荷雨打声。","摩天古木不可见，住岳高僧空得名。","今朝拜首臨欲別，遙憶荆门雨中發。"]', '诗', 'shi', '', NULL, '荆門歌送兄赴夔州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31db4b05-1ecc-4068-82e7-3c4681f2dcd7', '妾薄命', '妾薄命', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["憶妾初嫁君，花鬟如綠雲。","迴燈入綺帳，轉面脫羅裙。","折步教人學，偷香與客熏。","容顏南國重，名字北方聞。","一從失恩意，轉覺身顦顇。","對鏡不梳頭，倚窗空落淚。","新人莫恃新，秋至會無春。","從來閉在長門者，必是宮中第一人。"]', '["憶妾初嫁君，花鬟如綠云。","迴灯入綺帳，轉面脫羅裙。","折步教人学，偷香與客熏。","容顏南国重，名字北方闻。","一從失恩意，轉覺身顦顇。","对镜不梳头，倚窗空落泪。","新人莫恃新，秋至會無春。","從来閉在长门者，必是宮中第一人。"]', '诗', 'shi', '', NULL, '妾薄命 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15a4577a-a56a-4576-bea0-d6f64aea1199', '關山月', '关山月', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["露濕月蒼蒼，關頭榆葉黃。","迴輪照海遠，分彩上樓長。","水凍頻移幕，兵疲數望鄉。","只應城影外，萬里共胡霜。"]', '["露濕月蒼蒼，关头榆葉黄。","迴輪照海远，分彩上楼长。","水凍頻移幕，兵疲數望乡。","只應城影外，万里共胡霜。"]', '诗', 'shi', '', NULL, '關山月 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a83f524c-ef82-4bb8-a14b-f3360e7b5d2a', '度關山', '度关山', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["雁塞日初晴，狐關雪復平。","危樓緣廣漠，古竇傍長城。","拂劍金星出，彎弧玉羽鳴。","誰知係虜者，賈誼是書生。"]', '["雁塞日初晴，狐关雪复平。","危楼緣廣漠，古竇傍长城。","拂劍金星出，彎弧玉羽鳴。","誰知係虜者，賈誼是书生。"]', '诗', 'shi', '', NULL, '度關山 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd8200fc-61b8-4d38-8c30-15b54428be42', '巫山高', '巫山高', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["巫山十二峯，皆在碧虛中。","迴合雲藏月，霏微雨帶風。","猿聲寒過澗，樹色暮連空。","愁向高唐望，清秋見楚宮。"]', '["巫山十二峯，皆在碧虛中。","迴合云藏月，霏微雨带风。","猿声寒過澗，樹色暮連空。","愁向高唐望，清秋见楚宮。"]', '诗', 'shi', '', NULL, '巫山高 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('318bbfaf-054e-4d21-b82b-eb5a62c1fccf', '雨雪曲', '雨雪曲', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["天山一丈雪，雜雨夜霏霏。","濕馬胡歌亂，經烽漢火微。","丁零蘇武別，疎勒范羌歸。","若看關頭下，長榆葉定稀。"]', '["天山一丈雪，杂雨夜霏霏。","濕马胡歌亂，經烽漢火微。","丁零蘇武別，疎勒范羌归。","若看关头下，长榆葉定稀。"]', '诗', 'shi', '', NULL, '雨雪曲 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01fb9d75-9711-4b11-b58d-6d767575044b', '春遊樂', '春游乐', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["柘彈連錢馬，銀鉤妥墮鬟。","摘桑春陌上，踏草夕陽間。","意合辭先露，心誠貌却閒。","明朝若相憶，雲雨出巫山。"]', '["柘彈連錢马，銀鉤妥墮鬟。","摘桑春陌上，踏草夕陽间。","意合辞先露，心誠貌却閒。","明朝若相憶，云雨出巫山。"]', '诗', 'shi', '', NULL, '春遊樂 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8e54bab-695d-4ce2-89a8-908d28feea5d', '山下泉', '山下泉', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["碧水暎丹霞，濺濺度淺沙。","暗通山下草，流出洞中花。","淨色和雲落，喧聲遶石斜。","明朝更尋去，應到阮郎家。"]', '["碧水暎丹霞，濺濺度淺沙。","暗通山下草，流出洞中花。","淨色和云落，喧声遶石斜。","明朝更尋去，應到阮郎家。"]', '诗', 'shi', '', NULL, '山下泉 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ca4298-5f1f-4a0e-93b1-4e72caafbaee', '送客赴洪州', '送客赴洪州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["草色隨驄馬，悠悠共出秦。","水傳雲夢曉，山接洞庭春。","帆影連三峽，猿聲在四鄰。","青門一分手，難見杜陵人。"]', '["草色隨驄马，悠悠共出秦。","水傳云梦晓，山接洞庭春。","帆影連三峽，猿声在四鄰。","青门一分手，难见杜陵人。"]', '诗', 'shi', '', NULL, '送客赴洪州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37f4077e-4ef3-4815-bcf9-e8d0e177799d', '與鄭錫遊春', '與鄭錫游春', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["東門垂柳長，迴首獨心傷。","日煖臨芳草，天晴憶故鄉。","暎花鸎上下，過水蝶飛揚。","借問同行客，今朝淚幾行。"]', '["东门垂柳长，迴首独心傷。","日煖臨芳草，天晴憶故乡。","暎花鸎上下，過水蝶飞揚。","借问同行客，今朝泪幾行。"]', '诗', 'shi', '', NULL, '與鄭錫遊春 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ad223b0-9c4e-4889-9285-c32465441457', '送友人', '送友人', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["聞說湘川路，年年古木多。","猿啼巫峽夜，月照洞庭波。","窮海人還去，孤城雁與過。","青山不同賞，來往自蹉跎。"]', '["闻说湘川路，年年古木多。","猿啼巫峽夜，月照洞庭波。","窮海人還去，孤城雁與過。","青山不同賞，来往自蹉跎。"]', '诗', 'shi', '', NULL, '送友人 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31f756f8-7fbd-47f7-852b-5d15bccede9a', '題從叔沆林園', '題從叔沆林园', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["阮宅閒園暮，窗中見樹陰。","樵歌依遠草，僧語過長林。","鳥哢花間曲，人彈竹裏琴。","自嫌身未老，已有住山心。"]', '["阮宅閒园暮，窗中见樹陰。","樵歌依远草，僧語過长林。","鸟哢花间曲，人彈竹裏琴。","自嫌身未老，已有住山心。"]', '诗', 'shi', '', NULL, '題從叔沆林園 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc1cc95e-2380-4997-9a98-779a7c22b737', '送少微上人入蜀', '送少微上人入蜀', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["削髮本求道，何方不是歸。","松風開法席，江月濯禪衣。","飛閣蟬鳴早，漫天客過稀。","戴顒常執筆，不覺此身非。"]', '["削髮本求道，何方不是归。","松风开法席，江月濯禪衣。","飞閣蟬鳴早，漫天客過稀。","戴顒常執笔，不覺此身非。"]', '诗', 'shi', '', NULL, '送少微上人入蜀 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07596669-74eb-4543-adf4-0562ec1cdba4', '雨後遊輞川', '雨後游輞川', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["驟雨歸山盡，頹陽入輞川。","看虹登晚墅，踏石過春泉。","紫葛藏仙井，黃花出野田。","自知無路去，迴步就人煙。"]', '["驟雨归山尽，頹陽入輞川。","看虹登晚墅，踏石過春泉。","紫葛藏仙井，黄花出野田。","自知無路去，迴步就人煙。"]', '诗', 'shi', '', NULL, '雨後遊輞川 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c41266-d7f8-442e-bd0e-d25192e47ea3', '同皇甫侍御題惟一上人房', '同皇甫侍御題惟一上人房', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["焚香居一室，盡日見空林。","得道輕年暮，安禪愛夜深。","東西皆是夢，存沒豈關心。","唯羨諸童子，持經在竹陰。"]', '["焚香居一室，尽日见空林。","得道轻年暮，安禪愛夜深。","东西皆是梦，存沒豈关心。","唯羨諸童子，持經在竹陰。"]', '诗', 'shi', '', NULL, '同皇甫侍御題惟一上人房 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c02d9d-0d51-4e6a-8533-26f1ffafc4fd', '同苗員外宿薦福寺僧舍', '同苗員外宿薦福寺僧舍', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["潘安秋興動，涼夜宿僧房。","倚杖雲離月，垂簾竹有霜。","迴風生遠逕，落葉颯長廊。","一與交親會，空貽別後傷。"]', '["潘安秋兴动，涼夜宿僧房。","倚杖云離月，垂簾竹有霜。","迴风生远逕，落葉颯长廊。","一與交親會，空貽別後傷。"]', '诗', 'shi', '', NULL, '同苗員外宿薦福寺僧舍 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c04af040-9b5f-4954-8080-fc0e5a7feb80', '送客往湘江', '送客往湘江', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["識君年已老，孤棹向瀟湘。","素髮臨高鏡，清晨入遠鄉。","三山分夏口，五兩映涔陽。","更逐巴東客，南行淚幾行。"]', '["識君年已老，孤棹向瀟湘。","素髮臨高镜，清晨入远乡。","三山分夏口，五兩映涔陽。","更逐巴东客，南行泪幾行。"]', '诗', 'shi', '', NULL, '送客往湘江 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('480b2291-d1d9-4bd7-9851-93f4cf8192e2', '送友人遊蜀', '送友人游蜀', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["嘉陵天氣好，百里見雙流。","帆影緣巴字，鐘聲出漢州。","綠原春草晚，青木暮猿愁。","本是風流地，遊人易白頭。"]', '["嘉陵天氣好，百里见雙流。","帆影緣巴字，鐘声出漢州。","綠原春草晚，青木暮猿愁。","本是风流地，游人易白头。"]', '诗', 'shi', '', NULL, '送友人遊蜀 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce356bec-ac61-4adb-ab69-fcf465118812', '送友人遊江東', '送友人游江东', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["江上花開盡，南行見杪春。","鳥聲悲古木，雲影入通津。","返景斜連草，迴潮暗動蘋。","謝公今在郡，應喜得詩人。"]', '["江上花开尽，南行见杪春。","鸟声悲古木，云影入通津。","返景斜連草，迴潮暗动蘋。","謝公今在郡，應喜得诗人。"]', '诗', 'shi', '', NULL, '送友人遊江東 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0748bf1-95fb-4c94-882d-f60af170e41c', '送樂平苗明府得家字', '送乐平苗明府得家字', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["本自求彭澤，誰云道里賒。","山從石壁斷，江向弋陽斜。","暮色隨楓樹，陰雲暗荻花。","諸侯舊調鼎，應重宰臣家。"]', '["本自求彭澤，誰云道里賒。","山從石壁斷，江向弋陽斜。","暮色隨楓樹，陰云暗荻花。","諸侯旧調鼎，應重宰臣家。"]', '诗', 'shi', '', NULL, '送樂平苗明府得家字 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6381e1ed-6c1f-4b0a-b4aa-26fd2370c2c4', '過宋州', '過宋州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["睢陽陷虜日，外絕救兵來。","世亂忠臣死，時清明主哀。","荒郊春草徧，故壘野花開。","欲爲將軍哭，東流水不迴。"]', '["睢陽陷虜日，外絕救兵来。","世亂忠臣死，时清明主哀。","荒郊春草徧，故壘野花开。","欲爲將軍哭，东流水不迴。"]', '诗', 'shi', '', NULL, '過宋州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6805e578-f4a7-4cf3-9010-6aa77700dd2c', '茂陵山行陪韋金部', '茂陵山行陪韋金部', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["宿雨朝來歇，空山秋氣清。","盤雲雙鶴下，隔水一蟬鳴。","古道黃花落，平蕪赤燒生。","茂陵雖有病，猶得伴君行。"]', '["宿雨朝来歇，空山秋氣清。","盤云雙鹤下，隔水一蟬鳴。","古道黄花落，平蕪赤燒生。","茂陵雖有病，猶得伴君行。"]', '诗', 'shi', '', NULL, '茂陵山行陪韋金部 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e2d8a26-816a-42a0-a793-43cb68b807be', '江上逢司空曙', '江上逢司空曙', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["共爾髫年故，相逢萬里餘。","新春兩行淚，故國一封書。","夏口帆初落，涔陽雁正疎。","唯當執杯酒，暫食漢江魚。"]', '["共爾髫年故，相逢万里餘。","新春兩行泪，故国一封书。","夏口帆初落，涔陽雁正疎。","唯當執杯酒，暫食漢江鱼。"]', '诗', 'shi', '', NULL, '江上逢司空曙 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a3c8ec7-42d7-48b9-90df-b961b50d2a28', '逢王泌自東京至', '逢王泌自东京至', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["逢君自鄉至，雪涕問田園。","幾處生喬木，誰家在舊村。","山峰橫二室，水色映千門。","愁見游從處，如今花正繁。"]', '["逢君自乡至，雪涕问田园。","幾处生喬木，誰家在旧村。","山峰橫二室，水色映千门。","愁见游從处，如今花正繁。"]', '诗', 'shi', '', NULL, '逢王泌自東京至 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f5fd8d9-88ef-4407-baa9-cb359cfb0668', '山中期吉中孚', '山中期吉中孚', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["行人路不同，花落到山中。","水暗蒹葭霧，月明楊柳風。","年華驚已擲，志業颯然空。","何必龍鍾後，方期事遠公。"]', '["行人路不同，花落到山中。","水暗蒹葭霧，月明楊柳风。","年华驚已擲，志業颯然空。","何必龙鍾後，方期事远公。"]', '诗', 'shi', '', NULL, '山中期吉中孚 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f81b2b-dc25-4246-b886-3374c8e4d564', '酬前大理寺評事張芬', '酬前大理寺評事張芬', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["君家舊林壑，寄在亂峰西。","近日春雲滿，相思路亦迷。","聞鐘投野寺，待月過前溪。","悵望成幽夢，依依識故蹊。"]', '["君家旧林壑，寄在亂峰西。","近日春云满，相思路亦迷。","闻鐘投野寺，待月過前溪。","悵望成幽梦，依依識故蹊。"]', '诗', 'shi', '', NULL, '酬前大理寺評事張芬 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e36c646-625d-40db-8060-1433058bb551', '賦得山泉送房造', '賦得山泉送房造', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["泉水山邊去，高人月下看。","潤松秋色淨，落澗夜聲寒。","委曲穿深竹，潺湲過遠灘。","聖朝無隱者，早晚罷漁竿。"]', '["泉水山邊去，高人月下看。","潤松秋色淨，落澗夜声寒。","委曲穿深竹，潺湲過远灘。","聖朝無隐者，早晚罷漁竿。"]', '诗', 'shi', '', NULL, '賦得山泉送房造 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37843026-d9d5-407b-81b3-74dbfada971d', '宿興善寺後堂池', '宿兴善寺後堂池', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["草堂高樹下，月向後池生。","野客如僧靜，新荷共水平。","錦鱗沉不食，繡羽亂相鳴。","即事思江海，誰能萬里行。"]', '["草堂高樹下，月向後池生。","野客如僧静，新荷共水平。","錦鱗沉不食，繡羽亂相鳴。","即事思江海，誰能万里行。"]', '诗', 'shi', '', NULL, '宿興善寺後堂池 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5ba3afd-a08c-49e8-a13e-9c90d1d88428', '憶皎然上人', '憶皎然上人', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["未得從師去，人間萬事勞。","雲門不可見，山木已應高。","向日開柴戶，驚秋問敝袍。","何由宿峰頂，窗裏望波濤。"]', '["未得從師去，人间万事勞。","云门不可见，山木已應高。","向日开柴戶，驚秋问敝袍。","何由宿峰頂，窗裏望波濤。"]', '诗', 'shi', '', NULL, '憶皎然上人 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09e8939a-ce9c-42d6-b6d5-1d0ae752a3c6', '贈衡岳隱禪師', '贈衡岳隐禪師', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["舊住衡州寺，隨緣偶北來。","夜禪山雪下，朝汲竹門開。","半偈傳初盡，羣生意未迴。","唯當與樵者，杖錫入天台。"]', '["旧住衡州寺，隨緣偶北来。","夜禪山雪下，朝汲竹门开。","半偈傳初尽，羣生意未迴。","唯當與樵者，杖錫入天台。"]', '诗', 'shi', '', NULL, '贈衡岳隱禪師 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be3a6223-111c-4452-81ee-7483c9462f52', '雲陽觀寄袁稠', '云陽观寄袁稠', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["花洞晚陰陰，仙壇隔杏林。","漱泉春谷冷，擣藥夜窗深。","石上開仙酌，松間對玉琴。","戴家溪北住，雪後去相尋。"]', '["花洞晚陰陰，仙壇隔杏林。","漱泉春谷冷，擣藥夜窗深。","石上开仙酌，松间对玉琴。","戴家溪北住，雪後去相尋。"]', '诗', 'shi', '', NULL, '雲陽觀寄袁稠 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ea7f9d1-64cc-4496-b27a-930f2f52f905', '晚遊東田寄司空曙', '晚游东田寄司空曙', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["暮來思遠客，獨立在東田。","片雨無妨景，殘虹不映天。","別愁逢夏果，歸興入秋蟬。","莫作隳官意，陶潛未必賢。"]', '["暮来思远客，独立在东田。","片雨無妨景，殘虹不映天。","別愁逢夏果，归兴入秋蟬。","莫作隳官意，陶潛未必賢。"]', '诗', 'shi', '', NULL, '晚遊東田寄司空曙 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68d9ed9c-3785-4e67-9f3c-6e214f9a15a5', '題崔端公園林', '題崔端公园林', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["上士愛清輝，開門向翠微。","抱琴看鶴去，枕石待雲歸。","野坐苔生席，高眠竹挂衣。","舊山東望遠，惆悵暮花飛。"]', '["上士愛清輝，开门向翠微。","抱琴看鹤去，枕石待云归。","野坐苔生席，高眠竹挂衣。","旧山东望远，惆悵暮花飞。"]', '诗', 'shi', '', NULL, '題崔端公園林 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f99c8509-6d10-44bc-aa49-90dc515dd4ce', '早春雪夜寄盧綸兼呈秘書元丞', '早春雪夜寄盧綸兼呈秘书元丞', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["聞君隨謝朓，春夜宿前川。","看竹雲垂地，尋僧月滿田。","熊寒方入樹，魚樂稍離船。","獨夜羇愁客，惟知惜故年。"]', '["闻君隨謝朓，春夜宿前川。","看竹云垂地，尋僧月满田。","熊寒方入樹，鱼乐稍離船。","独夜羇愁客，惟知惜故年。"]', '诗', 'shi', '', NULL, '早春雪夜寄盧綸兼呈秘書元丞 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48463e26-4422-448c-b3fa-d1245915026d', '早春夜集耿拾遺宅', '早春夜集耿拾遺宅', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["如何逋客會，忽在侍臣家。","新草猶停雪，寒梅未放花。","銜杯雞欲唱，逗月雁應斜。","年齒俱憔悴，誰堪故國賒。"]', '["如何逋客會，忽在侍臣家。","新草猶停雪，寒梅未放花。","銜杯雞欲唱，逗月雁應斜。","年齒俱憔悴，誰堪故国賒。"]', '诗', 'shi', '', NULL, '早春夜集耿拾遺宅 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28dab00e-5163-4f57-921e-1da2b551712e', '元丞宅送胡濬及第東歸覲省', '元丞宅送胡濬及第东归覲省', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["登龍兼折桂，歸去當高車。","舊楚楓猶在，前隋柳已疎。","月中逢海客，浪裏得鄉書。","見說江邊住，知君不厭魚。"]', '["登龙兼折桂，归去當高车。","旧楚楓猶在，前隋柳已疎。","月中逢海客，浪裏得乡书。","见说江邊住，知君不厭鱼。"]', '诗', 'shi', '', NULL, '元丞宅送胡濬及第東歸覲省 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cff4d95-87c2-48bc-81d8-721f843f9a39', '送魏廣下第歸揚州寧親', '送魏廣下第归揚州寧親', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["遊宦今空返，浮淮一雁秋。","白雲陰澤國，青草遶揚州。","調膳過花下，張筵到水頭。","昆山仍有玉，歲晏莫淹留。"]', '["游宦今空返，浮淮一雁秋。","白云陰澤国，青草遶揚州。","調膳過花下，張筵到水头。","昆山仍有玉，歲晏莫淹留。"]', '诗', 'shi', '', NULL, '送魏廣下第歸揚州寧親 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2baf65cc-4604-4ccf-ac0a-94994e18e15e', '歸山與酒徒別', '归山與酒徒別', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["野客本無事，此來非有求。","煩君徵樂餞，未免憶山愁。","紅燭侵明月，青娥促白頭。","童心久已盡，豈爲豔歌留。"]', '["野客本無事，此来非有求。","煩君徵乐餞，未免憶山愁。","紅燭侵明月，青娥促白头。","童心久已尽，豈爲豔歌留。"]', '诗', 'shi', '', NULL, '歸山與酒徒別 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c340def5-21ad-4179-bfac-3007ebe37f5d', '冬夜寄韓弇', '冬夜寄韓弇', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["獨坐知霜下，開門見木衰。","壯應隨日去，老豈與人期。","廢井蟲鳴早，陰階菊發遲。","興來空憶戴，不似剡溪時。"]', '["独坐知霜下，开门见木衰。","壯應隨日去，老豈與人期。","廢井蟲鳴早，陰階菊發遲。","兴来空憶戴，不似剡溪时。"]', '诗', 'shi', '', NULL, '冬夜寄韓弇 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e839873-f7fa-477e-bbae-ba1add31be7e', '聞吉道士還俗因而有贈', '闻吉道士還俗因而有贈', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["聞有華陽客，儒裳謁紫微。","舊山連藥賣，孤鶴帶雲歸。","柳市名猶在，桃源夢已稀。","還鄉見鷗鳥，應愧背船飛。"]', '["闻有华陽客，儒裳謁紫微。","旧山連藥賣，孤鹤带云归。","柳市名猶在，桃源梦已稀。","還乡见鷗鸟，應愧背船飞。"]', '诗', 'shi', '', NULL, '聞吉道士還俗因而有贈 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e235fe0-7c45-444b-b33d-a317f79b6ec5', '韋員外東齋看花', '韋員外东斋看花', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["入花凡幾步，此樹獨相留。","發豔紅枝合，垂煙綠水幽。","倂開偏覺好，未落已成愁。","一到芳菲下，空招兩鬢秋。"]', '["入花凡幾步，此樹独相留。","發豔紅枝合，垂煙綠水幽。","倂开偏覺好，未落已成愁。","一到芳菲下，空招兩鬢秋。"]', '诗', 'shi', '', NULL, '韋員外東齋看花 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa5b58b9-029a-4cc0-856b-a2dd09cb4a74', '邊頭作', '邊头作', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["邠郊泉脉動，落日上城樓。","羊馬水草足，羌胡帳幕稠。","射鵰過海岸，傳箭怯邊州。","何事歸朝將，今年又拜侯。"]', '["邠郊泉脉动，落日上城楼。","羊马水草足，羌胡帳幕稠。","射鵰過海岸，傳箭怯邊州。","何事归朝將，今年又拜侯。"]', '诗', 'shi', '', NULL, '邊頭作 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac707a09-78f2-4230-a223-17d9173ef41a', '宿深上人院聽遠泉', '宿深上人院听远泉', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["泉聲宜遠聽，入夜對支公。","斷續來方盡，潺湲咽又通。","何年出石下，幾里在山中。","君問窮源處，禪心與此同。"]', '["泉声宜远听，入夜对支公。","斷續来方尽，潺湲咽又通。","何年出石下，幾里在山中。","君问窮源处，禪心與此同。"]', '诗', 'shi', '', NULL, '宿深上人院聽遠泉 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3c25268-b08b-4126-8e77-141cf5bbeaad', '茂陵村行贈何兆', '茂陵村行贈何兆', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["春天黃鳥囀，野逕白雲閒。","解帶依芳草，支頤想故山。","人行九州路，樹老五陵間。","誰道臨邛遠，相如自憶還。"]', '["春天黄鸟囀，野逕白云閒。","解带依芳草，支頤想故山。","人行九州路，樹老五陵间。","誰道臨邛远，相如自憶還。"]', '诗', 'shi', '', NULL, '茂陵村行贈何兆 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e58b1d3-ae22-41da-9995-93c3d985e01c', '送友人還洛', '送友人還洛', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["去國渡關河，蟬鳴古樹多。","平原正超忽，行子復蹉跎。","去事不可想，舊遊難再過。","何當嵩岳下，相見在煙蘿。"]', '["去国渡关河，蟬鳴古樹多。","平原正超忽，行子复蹉跎。","去事不可想，旧游难再過。","何當嵩岳下，相见在煙蘿。"]', '诗', 'shi', '', NULL, '送友人還洛 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3adb71b6-f985-49f8-8c0d-cda8ddd64891', '送戴徵士還山', '送戴徵士還山', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["柔桑錦臆雉，相送到煙霞。","獨隱空山裏，閒門幾樹花。","草生楊柳岸，鳥囀竹林家。","不是謀生拙，無爲末路賒。"]', '["柔桑錦臆雉，相送到煙霞。","独隐空山裏，閒门幾樹花。","草生楊柳岸，鸟囀竹林家。","不是謀生拙，無爲末路賒。"]', '诗', 'shi', '', NULL, '送戴徵士還山 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d79a7f2-2e3c-496a-b9bd-9f778aee26ee', '秋日旅舍別司空文明', '秋日旅舍別司空文明', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["涼風颯窮巷，秋思滿高雲。","吏隱俱不就，此心仍別君。","素懷宗淡泊，羈旅念功勳。","轉憶西林寺，江聲月下聞。"]', '["涼风颯窮巷，秋思满高云。","吏隐俱不就，此心仍別君。","素懷宗淡泊，羈旅念功勳。","轉憶西林寺，江声月下闻。"]', '诗', 'shi', '', NULL, '秋日旅舍別司空文明 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fbdbf12-a0c7-4e46-bca8-8d09a3dfdaa8', '旅舍對雪贈考功王員外', '旅舍对雪贈考功王員外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["楊花驚滿路，麵市忽狂風。","驟下搖蘭葉，輕飛集竹叢。","欲將瓊樹比，不共玉人同。","獨望徽之棹，青山在雪中。"]', '["楊花驚满路，麵市忽狂风。","驟下搖蘭葉，轻飞集竹叢。","欲將瓊樹比，不共玉人同。","独望徽之棹，青山在雪中。"]', '诗', 'shi', '', NULL, '旅舍對雪贈考功王員外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba0b6ed-1b47-4c35-bd39-17a4a4a069b5', '送丁少府往唐上', '送丁少府往唐上', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["因君灞陵別，故國一迴看。","共食田文飯，先之梅福官。","江風轉日暮，山月滿潮寒。","不得同舟望，淹留歲月闌。"]', '["因君灞陵別，故国一迴看。","共食田文飯，先之梅福官。","江风轉日暮，山月满潮寒。","不得同舟望，淹留歲月闌。"]', '诗', 'shi', '', NULL, '送丁少府往唐上 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28af459d-8908-4c13-ae29-d6d768ad54d4', '贈李龜年', '贈李龟年', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["青春事漢主，白首入秦城。","遍識才人字，多知舊曲名。","風流隨故事，語笑合新聲。","獨有垂楊樹，偏傷日暮情。"]', '["青春事漢主，白首入秦城。","遍識才人字，多知旧曲名。","风流隨故事，語笑合新声。","独有垂楊樹，偏傷日暮情。"]', '诗', 'shi', '', NULL, '贈李龜年 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99edd908-d72c-419a-b92f-61939a21ad4a', '送郭補闕歸江陽', '送郭補闕归江陽', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["東門春尚淺，楊柳未成陰。","雁影愁斜日，鸎聲怨故林。","隋宮江上遠，梁苑雪中深。","獨有懷歸客，難爲欲別心。"]', '["东门春尚淺，楊柳未成陰。","雁影愁斜日，鸎声怨故林。","隋宮江上远，梁苑雪中深。","独有懷归客，难爲欲別心。"]', '诗', 'shi', '', NULL, '送郭補闕歸江陽 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c119d5d1-3bd8-40af-ae71-a9f5a990ce14', '早春會王逵主人得蓬字', '早春會王逵主人得蓬字', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["今年華鬢色，半在故人中。","欲寫無窮恨，先期一醉同。","綠叢猶覆雪，紅萼已凋風。","莫負歸山契，君看陌上蓬。"]', '["今年华鬢色，半在故人中。","欲寫無窮恨，先期一醉同。","綠叢猶覆雪，紅萼已凋风。","莫負归山契，君看陌上蓬。"]', '诗', 'shi', '', NULL, '早春會王逵主人得蓬字 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('517af7f0-4487-4764-9ade-e6838c8b445f', '宿山寺思歸', '宿山寺思归', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["僧房秋雨歇，愁臥夜更深。","欹枕聞鴻雁，迴燈見竹林。","歸螢入草盡，落月映窗沉。","拭淚無人覺，長謠向壁陰。"]', '["僧房秋雨歇，愁臥夜更深。","欹枕闻鴻雁，迴灯见竹林。","归螢入草尽，落月映窗沉。","拭泪無人覺，长謠向壁陰。"]', '诗', 'shi', '', NULL, '宿山寺思歸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e4f268d-88bd-4640-9992-d20c160a1d3d', '送客赴江陵寄郢州郎士元', '送客赴江陵寄郢州郎士元', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["露下晚蟬愁，詩人舊怨秋。","沅湘莫留滯，宛洛好遨遊。","飲馬逢黃菊，離家值白頭。","竟陵明月夜，爲上庾公樓。"]', '["露下晚蟬愁，诗人旧怨秋。","沅湘莫留滯，宛洛好遨游。","饮马逢黄菊，離家值白头。","竟陵明月夜，爲上庾公楼。"]', '诗', 'shi', '', NULL, '送客赴江陵寄郢州郎士元 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a0a6ef-06f6-45dc-b9be-c94b65e8c7e5', '送客賦得巴江夜猿', '送客賦得巴江夜猿', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["巴水天邊路，啼猿傷客情。","遲遲雲外盡，杳杳樹中生。","殘月暗將落，空霜寒欲明。","楚人皆掩淚，聞到第三聲。"]', '["巴水天邊路，啼猿傷客情。","遲遲云外尽，杳杳樹中生。","殘月暗將落，空霜寒欲明。","楚人皆掩泪，闻到第三声。"]', '诗', 'shi', '', NULL, '送客賦得巴江夜猿 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('624cc745-9bec-4afc-9032-52042f103c9e', '秋日憶暕上人', '秋日憶暕上人', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["一從持鉢別，更未到人間。","好靜居貧寺，遺名棄近山。","雨前縫百衲，葉下閉重關。","若便潯陽去，須將舊客還。"]', '["一從持鉢別，更未到人间。","好静居貧寺，遺名棄近山。","雨前縫百衲，葉下閉重关。","若便潯陽去，須將旧客還。"]', '诗', 'shi', '', NULL, '秋日憶暕上人 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04fb8049-647f-44a5-b729-20ba3af1399a', '寄上舍人叔', '寄上舍人叔', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["車馬朝初下，看山憶獨尋。","會知逢水盡，且愛入雲深。","殘雨開斜日，新蟬發迥林。","阮咸雖別巷，遙識此時心。"]', '["车马朝初下，看山憶独尋。","會知逢水尽，且愛入云深。","殘雨开斜日，新蟬發迥林。","阮咸雖別巷，遙識此时心。"]', '诗', 'shi', '', NULL, '寄上舍人叔 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9013cb0-39cc-4b2a-9f1d-6b466b6a2389', '送古之奇赴安西幕', '送古之奇赴安西幕', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["疇昔十年兄，相逢五校營。","今宵舉杯酒，隴月見軍城。","堠火經陰絕，邊人接曉行。","殷勤送書記，強虜幾時平。"]', '["疇昔十年兄，相逢五校營。","今宵舉杯酒，隴月见軍城。","堠火經陰絕，邊人接晓行。","殷勤送书記，強虜幾时平。"]', '诗', 'shi', '', NULL, '送古之奇赴安西幕 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f61b4916-5970-4772-8090-8faab5cb0acf', '送張芬歸江東兼寄柳中庸', '送張芬归江东兼寄柳中庸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["久是天涯客，偏傷落木時。","如何故國見，更欲異鄉期。","鳥暮東西急，波寒上下遲。","空將滿眼淚，千里怨相思。"]', '["久是天涯客，偏傷落木时。","如何故国见，更欲異乡期。","鸟暮东西急，波寒上下遲。","空將满眼泪，千里怨相思。"]', '诗', 'shi', '', NULL, '送張芬歸江東兼寄柳中庸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8204939c-ce4f-42e9-8a0c-042d847893f3', '送丘丹歸江東', '送丘丹归江东', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["故山霜落久，才子憶荆扉。","旅舍尋人別，秋風逐雁歸。","夢愁楓葉盡，醉惜菊花稀。","肯學求名者，經年未拂衣。"]', '["故山霜落久，才子憶荆扉。","旅舍尋人別，秋风逐雁归。","梦愁楓葉尽，醉惜菊花稀。","肯学求名者，經年未拂衣。"]', '诗', 'shi', '', NULL, '送丘丹歸江東 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12676785-e9e4-4d9b-83de-ff031e56f520', '臥病寄苗員外', '臥病寄苗員外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["故人初未貴，相見得淹留。","一自朝天去，因成計日遊。","月明應獨醉，葉下肯同愁。","因恨劉楨病，空園臥見秋。"]', '["故人初未貴，相见得淹留。","一自朝天去，因成計日游。","月明應独醉，葉下肯同愁。","因恨劉楨病，空园臥见秋。"]', '诗', 'shi', '', NULL, '臥病寄苗員外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bf27b1f-061f-4463-8180-61927064aac2', '送楊臯擢第歸江東', '送楊臯擢第归江东', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["隋堤望楚國，江上一歸人。","綠氣千檣暮，青風萬里春。","試才初得桂，泊渚肯傷蘋。","拜手終悽愴，恭承中外親。"]', '["隋堤望楚国，江上一归人。","綠氣千檣暮，青风万里春。","試才初得桂，泊渚肯傷蘋。","拜手終悽愴，恭承中外親。"]', '诗', 'shi', '', NULL, '送楊臯擢第歸江東 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c326aa75-69df-42ec-b918-aacbb8d10860', '題鄭少府林園', '題鄭少府林园', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["謝家今日晚，詞客願抽毫。","櫪馬方迴影，池鵝正理毛。","竹筒傳水遠，麈尾坐僧高。","獨有宗雷賤，過君著敝袍。"]', '["謝家今日晚，词客願抽毫。","櫪马方迴影，池鵝正理毛。","竹筒傳水远，麈尾坐僧高。","独有宗雷賤，過君著敝袍。"]', '诗', 'shi', '', NULL, '題鄭少府林園 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee3750cc-563c-4bc1-be08-92cbe45ba0d1', '送吉中孚拜官歸業', '送吉中孚拜官归業', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["南入華陽洞，無人古樹寒。","吟詩開舊帙，帶綬上荒壇。","因病求歸易，霑恩更隱難。","孟宗應獻鮓，家近守漁官。"]', '["南入华陽洞，無人古樹寒。","吟诗开旧帙，带綬上荒壇。","因病求归易，霑恩更隐难。","孟宗應獻鮓，家近守漁官。"]', '诗', 'shi', '', NULL, '送吉中孚拜官歸業 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('477e1b28-8c69-4536-9442-41681596f0eb', '送楊少府赴陽翟', '送楊少府赴陽翟', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["冠帶仁兄後，光輝壽母前。","陸雲還入洛，潘岳更張筵。","井邑嵩山對，園林潁水連。","東人欲相送，旅舍已潸然。"]', '["冠带仁兄後，光輝壽母前。","陸云還入洛，潘岳更張筵。","井邑嵩山对，园林潁水連。","东人欲相送，旅舍已潸然。"]', '诗', 'shi', '', NULL, '送楊少府赴陽翟 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cbacdef-c801-4b10-b17e-05adda87211a', '慈恩寺暕上人房招耿拾遺', '慈恩寺暕上人房招耿拾遺', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["悠然對惠遠，共結故山期。","汲井樹陰下，閉門亭午時。","地閒花落厚，石淺水流遲。","願與神仙客，同來事本師。"]', '["悠然对惠远，共結故山期。","汲井樹陰下，閉门亭午时。","地閒花落厚，石淺水流遲。","願與神仙客，同来事本師。"]', '诗', 'shi', '', NULL, '慈恩寺暕上人房招耿拾遺 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10343b4e-a3ad-48f1-8bed-e0d7e4905971', '宿山寺雪夜寄吉中孚', '宿山寺雪夜寄吉中孚', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["獨愛僧房竹，春來長到池。","雲遮皆晃朗，雪壓半低垂。","不見侵山葉，空聞拂地枝。","鄙夫今夜興，唯有子猷知。"]', '["独愛僧房竹，春来长到池。","云遮皆晃朗，雪壓半低垂。","不见侵山葉，空闻拂地枝。","鄙夫今夜兴，唯有子猷知。"]', '诗', 'shi', '', NULL, '宿山寺雪夜寄吉中孚 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62178074-6682-491e-8e6f-13258a757d32', '贈趙神童', '贈趙神童', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["聖朝殊漢令，才子少登科。","每見先鳴早，常驚後進多。","獨居方寂寞，相對覺蹉跎。","不是通家舊，頻勞文舉過。"]', '["聖朝殊漢令，才子少登科。","每见先鳴早，常驚後進多。","独居方寂寞，相对覺蹉跎。","不是通家旧，頻勞文舉過。"]', '诗', 'shi', '', NULL, '贈趙神童 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90872e4-378a-48f6-b5dd-3ddf44f4af01', '宿雲際寺贈深上人', '宿云際寺贈深上人', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["暫別青藍寺，今來髮欲斑。","獨眠孤燭下，風雨在前山。","壞宅終須去，空門不易還。","支公有方便，一願啓玄關。"]', '["暫別青藍寺，今来髮欲斑。","独眠孤燭下，风雨在前山。","壞宅終須去，空门不易還。","支公有方便，一願啓玄关。"]', '诗', 'shi', '', NULL, '宿雲際寺贈深上人 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b15981cd-41a4-484b-be49-c8c92bddf5e5', '送從兄赴洪州別駕兄善琴', '送從兄赴洪州別駕兄善琴', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["援琴兼愛竹，遙夜在湘沅。","鶴舞月將下，烏啼霜正繁。","亂流喧橘岸，飛雪暗荆門。","佐郡無辭屈，其如相府恩。"]', '["援琴兼愛竹，遙夜在湘沅。","鹤舞月將下，烏啼霜正繁。","亂流喧橘岸，飞雪暗荆门。","佐郡無辞屈，其如相府恩。"]', '诗', 'shi', '', NULL, '送從兄赴洪州別駕兄善琴 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9991691b-23a6-463b-9eef-0f36027d8a9b', '山中期張芬不至', '山中期張芬不至', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["石堤春草碧，雙燕向西飛。","悵望雲天暮，佳人何處歸。","藥欄蟲網遍，苔井水痕稀。","誰道嵇康嬾，山中自掩扉。"]', '["石堤春草碧，雙燕向西飞。","悵望云天暮，佳人何处归。","藥欄蟲網遍，苔井水痕稀。","誰道嵇康嬾，山中自掩扉。"]', '诗', 'shi', '', NULL, '山中期張芬不至 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51169d5f-1218-48cf-873a-c2851aa0c9b7', '寄暢當', '寄暢當', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["麥秀草芊芊，幽人好晝眠。","雲霞生嶺上，猿鳥下牀前。","顏子方敦行，支郎久住禪。","中林輕暫別，約略已經年。"]', '["麦秀草芊芊，幽人好晝眠。","云霞生嶺上，猿鸟下牀前。","顏子方敦行，支郎久住禪。","中林轻暫別，約略已經年。"]', '诗', 'shi', '', NULL, '寄暢當 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f0445db-513b-4949-ab33-5412bcd8c074', '送義興元少府', '送義兴元少府', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["逢君惠連第，初命[便]光輝。","已得羣公祖，終妨太傅譏。","路長人反顧，草斷燕迴飛。","本是江南客，還同衣錦歸。"]', '["逢君惠連第，初命[便]光輝。","已得羣公祖，終妨太傅譏。","路长人反顧，草斷燕迴飞。","本是江南客，還同衣錦归。"]', '诗', 'shi', '', NULL, '送義興元少府 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d166bb61-1756-49af-8967-29ae96ddf592', '臥病別鄭錫', '臥病別鄭錫', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["病來喜無事，多臥竹林間。","此日一相見，明朝還掩關。","幽人愛芳草，志士惜頹顏。","歲[晏]不我棄，期君在故山。"]', '["病来喜無事，多臥竹林间。","此日一相见，明朝還掩关。","幽人愛芳草，志士惜頹顏。","歲[晏]不我棄，期君在故山。"]', '诗', 'shi', '', NULL, '臥病別鄭錫 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81acf44-ba49-457e-9735-26292f63ec3b', '書志贈暢當', '书志贈暢當', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["少喜神仙術，未去已蹉跎。","壯志一爲累，浮生事漸多。","衰顏不相識，歲暮定相過。","請問宗居士，君其奈老何。"]', '["少喜神仙術，未去已蹉跎。","壯志一爲累，浮生事漸多。","衰顏不相識，歲暮定相過。","請问宗居士，君其奈老何。"]', '诗', 'shi', '', NULL, '書志贈暢當 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90000504-3c60-4a56-8955-0760535a6d42', '送諸曁裴少府', '送諸曁裴少府', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["山公訪嵇紹，趙武見韓侯。","事去恩猶在，名成淚却流。","一官同北去，千里赴南州。","才子清風後，無貽相府憂。"]', '["山公訪嵇紹，趙武见韓侯。","事去恩猶在，名成泪却流。","一官同北去，千里赴南州。","才子清风後，無貽相府憂。"]', '诗', 'shi', '', NULL, '送諸曁裴少府 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec92b206-bff8-43a6-ae6b-977430e21bd8', '送鄭宥入蜀迎覲', '送鄭宥入蜀迎覲', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["寧親西陟險，君去異王陽。","在世誰非客，還家即是鄉。","劍門千轉盡，巴水一支長。","請語愁猿道，無煩促淚行。"]', '["寧親西陟險，君去異王陽。","在世誰非客，還家即是乡。","劍门千轉尽，巴水一支长。","請語愁猿道，無煩促泪行。"]', '诗', 'shi', '', NULL, '送鄭宥入蜀迎覲 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664aff60-36cb-4907-8842-e6717be10cce', '送耿拾遺湋使江南括圖書', '送耿拾遺湋使江南括圖书', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["驅傳草連天，回風滿樹蟬。","將過夫子宅，前問孝廉船。","漢使收三篋，周詩採百篇。","別來將有淚，不是怨流年。"]', '["驱傳草連天，回风满樹蟬。","將過夫子宅，前问孝廉船。","漢使收三篋，周诗採百篇。","別来將有泪，不是怨流年。"]', '诗', 'shi', '', NULL, '送耿拾遺湋使江南括圖書 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a24e107-6995-4aba-8051-bd14bd55e78f', '送王少府遊河南', '送王少府游河南', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["馬卿方失意，東去謁諸侯。","過宋人應少，遊梁客獨愁。","鳥翻千室暮，蟬急兩河秋。","僕本無媒者，因君淚亦流。"]', '["马卿方失意，东去謁諸侯。","過宋人應少，游梁客独愁。","鸟翻千室暮，蟬急兩河秋。","僕本無媒者，因君泪亦流。"]', '诗', 'shi', '', NULL, '送王少府遊河南 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f2f5bed-450c-40f4-b45c-4838badedf18', '送別駕赴晉陵即舍人叔之兄', '送別駕赴晉陵即舍人叔之兄', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["諸宗稱叔父，從子亦光輝。","謝脁中書直，王祥別乘歸。","江帆衝雨上，海樹隔潮微。","南阮貧無酒，唯將淚濕衣。"]', '["諸宗稱叔父，從子亦光輝。","謝脁中书直，王祥別乘归。","江帆衝雨上，海樹隔潮微。","南阮貧無酒，唯將泪濕衣。"]', '诗', 'shi', '', NULL, '送別駕赴晉陵即舍人叔之兄 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4f9fafa-98fa-4d1a-b7a7-893371caaf1b', '臥病寄閻寀', '臥病寄閻寀', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["病中貪好景，強步出幽居。","紫葛垂山徑，黃花遶野渠。","荒林飛老鶴，敗堰過遊魚。","縱憶同年友，無人可寄書。"]', '["病中貪好景，強步出幽居。","紫葛垂山徑，黄花遶野渠。","荒林飞老鹤，敗堰過游鱼。","縱憶同年友，無人可寄书。"]', '诗', 'shi', '', NULL, '臥病寄閻寀 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12235098-ffc0-49a5-bca0-0730abcbc337', '晚夏聞蟬寄廣文', '晚夏闻蟬寄廣文', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["昨日鶯囀聲，今朝蟬忽鳴。","朱顏向華髮，定是幾年程。","故國白雲遠，閒居青草生。","因垂數行淚，書報十年兄。"]', '["昨日鶯囀声，今朝蟬忽鳴。","朱顏向华髮，定是幾年程。","故国白云远，閒居青草生。","因垂數行泪，书報十年兄。"]', '诗', 'shi', '', NULL, '晚夏聞蟬寄廣文 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('616d4775-8f78-4128-ada7-4722ae705698', '歸山居寄錢起', '归山居寄錢起', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["悵望青山下，回頭淚滿巾。","故鄉多古樹，落日少行人。","髮鬢將回色，簪纓未到身。","誰知武陵路，亦有漢家臣。"]', '["悵望青山下，回头泪满巾。","故乡多古樹，落日少行人。","髮鬢將回色，簪纓未到身。","誰知武陵路，亦有漢家臣。"]', '诗', 'shi', '', NULL, '歸山居寄錢起 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3019c14-dd48-4626-8fe8-a31151f8456e', '曉發瓜州', '晓發瓜州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["曉發悲行客，停橈獨未前。","寒江半有月，野戍漸無煙。","棹唱臨高岸，鴻嘶發遠田。","誰知避徒御，對酒一潸然。"]', '["晓發悲行客，停橈独未前。","寒江半有月，野戍漸無煙。","棹唱臨高岸，鴻嘶發远田。","誰知避徒御，对酒一潸然。"]', '诗', 'shi', '', NULL, '曉發瓜州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dde43147-3d4b-4c3b-b9f8-5e45db51e046', '江上喜逢司空文明', '江上喜逢司空文明', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["秦人江上見，握手淚沾巾。","落日見秋草，暮年逢故人。","非夫長作客，多病淺謀身。","臺閣舊親友，誰曾見苦辛。"]', '["秦人江上见，握手泪沾巾。","落日见秋草，暮年逢故人。","非夫长作客，多病淺謀身。","台閣旧親友，誰曾见苦辛。"]', '诗', 'shi', '', NULL, '江上喜逢司空文明 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29b0a3bb-27ae-462d-a793-f632108d3a58', '同苗發慈恩寺避暑', '同苗發慈恩寺避暑', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["追涼尋寶剎，畏日望璇題。","臥草同鴛侶，臨池似虎溪。","樹閒人跡外，山晚鳥行西。","若問無心法，蓮花隔淤泥。"]', '["追涼尋寶剎，畏日望璇題。","臥草同鴛侶，臨池似虎溪。","樹閒人跡外，山晚鸟行西。","若问無心法，蓮花隔淤泥。"]', '诗', 'shi', '', NULL, '同苗發慈恩寺避暑 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c427bc24-14a9-4fdb-8801-ead203ab9fa2', '送潘述宏詞下第歸江外', '送潘述宏词下第归江外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["唱高人不和，此去淚難收。","上國經年住，長江滿目流。","弈棊知勝偶，射策請焚舟。","應是田囗囗，玄成許爾遊。"]', '["唱高人不和，此去泪难收。","上国經年住，长江满目流。","弈棊知勝偶，射策請焚舟。","應是田囗囗，玄成許爾游。"]', '诗', 'shi', '', NULL, '送潘述宏詞下第歸江外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d455202e-0577-4455-bf2b-0e7040ed9bf4', '送張少府赴夏縣', '送張少府赴夏縣', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["雖爲州縣職，還欲抱琴過。","樹古聞風早，山枯見雪多。","雞聲連絳市，馬色傍黃河。","太守新臨郡，還逢五袴歌。"]', '["雖爲州縣職，還欲抱琴過。","樹古闻风早，山枯见雪多。","雞声連絳市，马色傍黄河。","太守新臨郡，還逢五袴歌。"]', '诗', 'shi', '', NULL, '送張少府赴夏縣 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80c7cd27-c454-481e-b3d5-5845b4bc3627', '酬秘書元丞郊園臥疾見寄', '酬秘书元丞郊园臥疾见寄', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["聞說漳濱臥，題詩怨歲華。","求醫主高手，報疾到貧家。","撒枕銷行蟻，移杯失畫蛇。","明朝九衢上，應見玉人車。"]', '["闻说漳濱臥，題诗怨歲华。","求醫主高手，報疾到貧家。","撒枕銷行蟻，移杯失畫蛇。","明朝九衢上，應见玉人车。"]', '诗', 'shi', '', NULL, '酬秘書元丞郊園臥疾見寄 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd046c72-5c26-4565-b0cc-044e954feda6', '送成都韋丞還蜀', '送成都韋丞還蜀', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["蜀門雲樹合，高棧有猿愁。","驅傳加新命，之官向舊遊。","晨裝逢酒雨，夜夢見刀州。","遠別長相憶，當年莫滯留。"]', '["蜀门云樹合，高棧有猿愁。","驱傳加新命，之官向旧游。","晨裝逢酒雨，夜梦见刀州。","远別长相憶，當年莫滯留。"]', '诗', 'shi', '', NULL, '送成都韋丞還蜀 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ade3e4-2e64-4fb2-9b4c-0b07bcad2ffb', '晚秋旅舍寄苗員外', '晚秋旅舍寄苗員外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["爭途苦不前，貧病遂連牽。","向暮同行客，當秋獨長年。","晚花唯有菊，寒葉已無蟬。","吏部逢今日，還應甕下眠。"]', '["爭途苦不前，貧病遂連牽。","向暮同行客，當秋独长年。","晚花唯有菊，寒葉已無蟬。","吏部逢今日，還應甕下眠。"]', '诗', 'shi', '', NULL, '晚秋旅舍寄苗員外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9d73415-8fff-4c3a-8857-f49b49e3fdf1', '送惟良上人歸潤州', '送惟良上人归潤州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["擬詩偏不類，又送上人歸。","寄世同高鶴，尋仙稱壞衣。","雨行江草短，露坐海帆稀。","正被空門縛，臨岐乞解圍。"]', '["擬诗偏不類，又送上人归。","寄世同高鹤，尋仙稱壞衣。","雨行江草短，露坐海帆稀。","正被空门縛，臨岐乞解圍。"]', '诗', 'shi', '', NULL, '送惟良上人歸潤州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c804f0-03cb-4610-a809-f413608ac25e', '送何兆下第還蜀', '送何兆下第還蜀', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["重江不可涉，孤客莫晨裝。","高木莎城小，殘星棧道長。","褭猿楓子落，過雨荔枝香。","勸爾成都住，文翁有草堂。"]', '["重江不可涉，孤客莫晨裝。","高木莎城小，殘星棧道长。","褭猿楓子落，過雨荔枝香。","勸爾成都住，文翁有草堂。"]', '诗', 'shi', '', NULL, '送何兆下第還蜀 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('010728ad-02ef-48b6-a80b-1602b392a698', '送友人宰湘陰', '送友人宰湘陰', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["從宦舟行遠，浮湘又入閩。","蒹葭無朔雁，檉栝有蠻神。","傳吏閒調象，山精暗訟人。","唯須千樹橘，暫救李衡貧。"]', '["從宦舟行远，浮湘又入閩。","蒹葭無朔雁，檉栝有蠻神。","傳吏閒調象，山精暗訟人。","唯須千樹橘，暫救李衡貧。"]', '诗', 'shi', '', NULL, '送友人宰湘陰 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7378a7d0-6a90-4ab6-852b-74b8b98f09e6', '送元晟歸江東舊居', '送元晟归江东旧居', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["澤國舟車接，關門雨雪乖。","春天行故楚，夜月下清淮。","講易居山寺，論詩到郡齋。","蔣家人暫別，三路草連堦。"]', '["澤国舟车接，关门雨雪乖。","春天行故楚，夜月下清淮。","講易居山寺，論诗到郡斋。","蔣家人暫別，三路草連堦。"]', '诗', 'shi', '', NULL, '送元晟歸江東舊居 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8670e43a-7cff-4436-81ab-157afb81eac3', '送黎少府赴陽翟', '送黎少府赴陽翟', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["詩禮稱才子，神仙是丈人。","玉山那惜醉，金谷已無春。","白馬如風疾，青袍奪草新。","不嫌鳴吠客，願用百年身。"]', '["诗禮稱才子，神仙是丈人。","玉山那惜醉，金谷已無春。","白马如风疾，青袍奪草新。","不嫌鳴吠客，願用百年身。"]', '诗', 'shi', '', NULL, '送黎少府赴陽翟 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb33cc4-43fb-42b9-8e7e-2790d9a01d6b', '送夏侯審遊蜀', '送夏侯審游蜀', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["西望煙綿樹，愁君上蜀時。","同林息商客，隔棧見罛師。","石滑羊腸險，山空杜宇悲。","琴心正幽怨，莫奏鳳凰詩。"]', '["西望煙綿樹，愁君上蜀时。","同林息商客，隔棧见罛師。","石滑羊腸險，山空杜宇悲。","琴心正幽怨，莫奏鳳凰诗。"]', '诗', 'shi', '', NULL, '送夏侯審遊蜀 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe3db07-8b1c-4edf-8a8d-eefb22db972e', '單推官廳前雙桐詠', '單推官廳前雙桐詠', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["封植因高興，孤貞契素期。","由來得地早，何事結花遲。","葉重凝煙後，條寒過雨時。","還同李家樹，爭賦角弓詩。"]', '["封植因高兴，孤貞契素期。","由来得地早，何事結花遲。","葉重凝煙後，條寒過雨时。","還同李家樹，爭賦角弓诗。"]', '诗', 'shi', '', NULL, '單推官廳前雙桐詠 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed458409-9298-486a-b549-65f60c967a8b', '送宋校書赴宣州幕', '送宋校书赴宣州幕', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["浮舟壓芳草，容裔逐江春。","遠避看書吏，行當入幕賓。","夜潮衝老樹，曉雨破輕蘋。","鴛鷺多傷別，欒家德在人。"]', '["浮舟壓芳草，容裔逐江春。","远避看书吏，行當入幕賓。","夜潮衝老樹，晓雨破轻蘋。","鴛鷺多傷別，欒家德在人。"]', '诗', 'shi', '', NULL, '送宋校書赴宣州幕 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('313f41fa-0152-4b99-81d2-ee96ff20a074', '送趙給事姪尉丹陽', '送趙給事姪尉丹陽', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["太傅憐羣從，門人亦賤回。","入官先愛子，賜酒許同杯。","淮海春多雨，蒹葭夜有雷。","遙知拜慶後，梅尉稱仙才。"]', '["太傅怜羣從，门人亦賤回。","入官先愛子，賜酒許同杯。","淮海春多雨，蒹葭夜有雷。","遙知拜慶後，梅尉稱仙才。"]', '诗', 'shi', '', NULL, '送趙給事姪尉丹陽 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2213a457-daa0-4b8c-8576-928ab743e4cd', '宿瓜洲寄柳中庸', '宿瓜洲寄柳中庸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["懷人同不寐，清夜起論文。","月魄正出海，雁行斜上雲。","寒潮來灩灩，秋葉下紛紛。","便送江東去，徘徊祗待君。"]', '["懷人同不寐，清夜起論文。","月魄正出海，雁行斜上云。","寒潮来灩灩，秋葉下紛紛。","便送江东去，徘徊祗待君。"]', '诗', 'shi', '', NULL, '宿瓜洲寄柳中庸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c1885e2-fc93-4291-82ab-c2c92055a909', '夜宴虢縣張明府宅逢宇文評事', '夜宴虢縣張明府宅逢宇文評事', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["虢田留古宅，入夜足秋風。","月影來窗裏，燈光落水中。","徵詩逢謝客，飲酒得陶公。","更愛疎籬下，繁霜濕菊叢。"]', '["虢田留古宅，入夜足秋风。","月影来窗裏，灯光落水中。","徵诗逢謝客，饮酒得陶公。","更愛疎籬下，繁霜濕菊叢。"]', '诗', 'shi', '', NULL, '夜宴虢縣張明府宅逢宇文評事 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b0f0da9-2461-4e36-9044-1b49a44efbe7', '冬夜集張尹後閣', '冬夜集張尹後閣', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["乘龜兼戴豸，白面映朱衣。","安石還須起，泉明不得歸。","譍門常吏在，登席舊寮稀。","遠客長先醉，那知亞相威。"]', '["乘龟兼戴豸，白面映朱衣。","安石還須起，泉明不得归。","譍门常吏在，登席旧寮稀。","远客长先醉，那知亞相威。"]', '诗', 'shi', '', NULL, '冬夜集張尹後閣 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05bce030-82e2-495c-a8a3-20ae16cc7564', '將之澤潞留別王郎中', '將之澤潞留別王郎中', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["弱年知己少，前路主人稀。","貧病期相惜，艱難又憶歸。","事成應未卜，身賤又無機。","幸到龍門下，須因羽翼飛。"]', '["弱年知己少，前路主人稀。","貧病期相惜，艱难又憶归。","事成應未卜，身賤又無機。","幸到龙门下，須因羽翼飞。"]', '诗', 'shi', '', NULL, '將之澤潞留別王郎中 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bf914dc-5c7f-4d9f-abe7-b5b2e1b10186', '晚次巴陵', '晚次巴陵', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["雪後柳條新，巴陵城下人。","烹魚邀水客，載酒奠山神。","雲去低斑竹，波迴動白蘋。","不堪逢楚老，日暮正江春。"]', '["雪後柳條新，巴陵城下人。","烹鱼邀水客，載酒奠山神。","云去低斑竹，波迴动白蘋。","不堪逢楚老，日暮正江春。"]', '诗', 'shi', '', NULL, '晚次巴陵 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de08789e-f931-4c88-aece-d70d5c5aa197', '送荀道士歸廬山', '送荀道士归廬山', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["先生歸有處，欲別笑無言。","綠水到山口，青林連洞門。","月明尋石路，雲霽望花源。","早晚還乘鶴，悲歌向故園。"]', '["先生归有处，欲別笑無言。","綠水到山口，青林連洞门。","月明尋石路，云霽望花源。","早晚還乘鹤，悲歌向故园。"]', '诗', 'shi', '', NULL, '送荀道士歸廬山 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5774b6-2822-479b-92ab-c4028ec564bd', '送張淑歸覲叔父', '送張淑归覲叔父', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["日慘長亭暮，天高大澤閒。","風中聞草木，雪裏見江山。","馬向塞雲去，人隨古道還。","阮家今夜樂，應在竹林間。"]', '["日慘长亭暮，天高大澤閒。","风中闻草木，雪裏见江山。","马向塞云去，人隨古道還。","阮家今夜乐，應在竹林间。"]', '诗', 'shi', '', NULL, '送張淑歸覲叔父 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b59eecb-8e64-4f62-8642-9d154a869838', '送郭參軍赴絳州', '送郭參軍赴絳州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["登車君莫望，故絳柳條春。","蒲澤逢胡雁，桃源見晉人。","佐軍髯尚短，擲地思還新。","小謝常攜手，因之醉路塵。"]', '["登车君莫望，故絳柳條春。","蒲澤逢胡雁，桃源见晉人。","佐軍髯尚短，擲地思還新。","小謝常携手，因之醉路塵。"]', '诗', 'shi', '', NULL, '送郭參軍赴絳州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da1f200e-5c0e-47f3-a256-793110d7b716', '送袁稠游江南', '送袁稠游江南', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["江南衰草遍，十里見長亭。","客去逢搖落，鴻飛入杳冥。","空城寒雨細，深院曉燈青。","欲去行人起，徘徊恨酒醒。"]', '["江南衰草遍，十里见长亭。","客去逢搖落，鴻飞入杳冥。","空城寒雨細，深院晓灯青。","欲去行人起，徘徊恨酒醒。"]', '诗', 'shi', '', NULL, '送袁稠游江南 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c365aaf-f2df-4a07-adf6-dd460903675d', '送夏中丞赴寧國任', '送夏中丞赴寧国任', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["楚縣入青楓，長江一派通。","板橋尋謝客，古邑事陶公。","片雨收山外，連雲上漢東。","陸機猶滯洛，念子望南鴻。"]', '["楚縣入青楓，长江一派通。","板橋尋謝客，古邑事陶公。","片雨收山外，連云上漢东。","陸機猶滯洛，念子望南鴻。"]', '诗', 'shi', '', NULL, '送夏中丞赴寧國任 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8abbcf9-6e8c-474c-a9e0-cdf19686d015', '送衞雄下第歸同州', '送衞雄下第归同州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["不才先上第，詞客却空還。","邊地行人少，平蕪盡日閒。","一蟬陂樹裏，衆火隴雲間。","羨汝歸茅屋，書窗見遠山。"]', '["不才先上第，词客却空還。","邊地行人少，平蕪尽日閒。","一蟬陂樹裏，衆火隴云间。","羨汝归茅屋，书窗见远山。"]', '诗', 'shi', '', NULL, '送衞雄下第歸同州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a64c0e34-2b67-4ae9-95a3-6603562da624', '送單少府赴扶風', '送單少府赴扶风', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["少年趨盛府，顏色比花枝。","范匄非童子，楊修豈小兒。","叨陪丈人行，常恐阿戎欺。","此去雲霄近，看君逸足馳。"]', '["少年趨盛府，顏色比花枝。","范匄非童子，楊修豈小兒。","叨陪丈人行，常恐阿戎欺。","此去云霄近，看君逸足驰。"]', '诗', 'shi', '', NULL, '送單少府赴扶風 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95d54531-dd2a-4f05-8064-c28224919dfc', '題山中別業', '題山中別業', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["舊宅在山中，閒門與寺通。","往來黃葉路，交結白頭翁。","晚笋難成竹，秋花不滿叢。","生涯祗麤糲，吾豈諱言窮。"]', '["旧宅在山中，閒门與寺通。","往来黄葉路，交結白头翁。","晚笋难成竹，秋花不满叢。","生涯祗麤糲，吾豈諱言窮。"]', '诗', 'shi', '', NULL, '題山中別業 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf8b3b5-c0a1-4b65-945a-1f8cbcc10770', '送司空文明歸江上舊居', '送司空文明归江上旧居', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["野菊有黃花，送君千里還。","鴻來燕又去，離別惜容顏。","流水通歸夢，行雲失故關。","江風正搖落，宋玉莫登山。"]', '["野菊有黄花，送君千里還。","鴻来燕又去，離別惜容顏。","流水通归梦，行云失故关。","江风正搖落，宋玉莫登山。"]', '诗', 'shi', '', NULL, '送司空文明歸江上舊居 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b065477a-bb08-4ce1-b740-c736fd542d1c', '送新城戴叔倫明府', '送新城戴叔倫明府', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["遙想隋堤路，春天楚國情。","白雲當海斷，青草隔淮生。","雁起斜還直，潮回遠復平。","萊蕪不可到，一醉送君行。"]', '["遙想隋堤路，春天楚国情。","白云當海斷，青草隔淮生。","雁起斜還直，潮回远复平。","萊蕪不可到，一醉送君行。"]', '诗', 'shi', '', NULL, '送新城戴叔倫明府 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b476bd50-8790-464f-9141-8c9d88097745', '送雍丘任少府', '送雍丘任少府', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["叢車餞才子，路走許東偏。","遠水同春色，繁花勝雪天。","鳥行侵楚邑，樹影向殷田。","莫學生鄉思，梅真正少年。"]', '["叢车餞才子，路走許东偏。","远水同春色，繁花勝雪天。","鸟行侵楚邑，樹影向殷田。","莫学生乡思，梅真正少年。"]', '诗', 'shi', '', NULL, '送雍丘任少府 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b2b15c-601a-479b-a00a-f4dcd6f88b13', '送雍郢州', '送雍郢州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["厭郎思出守，遂領漢東軍。","望月逢殷浩，緣江送范雲。","城閒煙草遍，浦逈雪林分。","誰伴樓中宿，吟詩估客聞。"]', '["厭郎思出守，遂領漢东軍。","望月逢殷浩，緣江送范云。","城閒煙草遍，浦逈雪林分。","誰伴楼中宿，吟诗估客闻。"]', '诗', 'shi', '', NULL, '送雍郢州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfa9216e-b1c0-459d-94c9-972427733c96', '寄王密卿', '寄王密卿', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["酒樂今年少，僧期近日頻。","買山多爲竹，卜宅不緣貧。","志業歸初地，文章寄此身。","嵇康雖有病，猶得見情人。"]', '["酒乐今年少，僧期近日頻。","買山多爲竹，卜宅不緣貧。","志業归初地，文章寄此身。","嵇康雖有病，猶得见情人。"]', '诗', 'shi', '', NULL, '寄王密卿 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af45c65-e023-4d75-9d16-11c31976c68d', '與蕭遠上人游少華山寄皇甫侍御', '與蕭远上人游少华山寄皇甫侍御', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["尋危兼採藥，渡水又登山。","獨與高僧去，逍遙落日間。","漸看閭里遠，自覺性情閒。","廻首知音在，因令悵望還。"]', '["尋危兼採藥，渡水又登山。","独與高僧去，逍遙落日间。","漸看閭里远，自覺性情閒。","廻首知音在，因令悵望還。"]', '诗', 'shi', '', NULL, '與蕭遠上人游少華山寄皇甫侍御 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8711802-5f93-4354-8422-a634ba2213e4', '代村中老人答', '代村中老人答', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["京洛風塵後，村鄉煙火稀。","少年曾失所，衰暮欲何依。","夜靜臨江哭，天寒踏雪歸。","時清應不見，言罷淚盈衣。"]', '["京洛风塵後，村乡煙火稀。","少年曾失所，衰暮欲何依。","夜静臨江哭，天寒踏雪归。","时清應不见，言罷泪盈衣。"]', '诗', 'shi', '', NULL, '代村中老人答 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c37df28-5999-4773-bc0a-5927ec7a278f', '贈故將軍', '贈故將軍', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["平生在邊日，鞍馬若星流。","獨出間千里，相知滿九州。","恃功凌主將，作氣見王侯。","誰道廉頗老，猶能報遠讐。"]', '["平生在邊日，鞍马若星流。","独出间千里，相知满九州。","恃功凌主將，作氣见王侯。","誰道廉頗老，猶能報远讐。"]', '诗', 'shi', '', NULL, '贈故將軍 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49676c14-b0aa-4ff9-b221-0479c049aa25', '送陸郎中歸田司空幕', '送陸郎中归田司空幕', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["漢家分列宿，東土佐諸侯。","結束還軍府，光輝過御溝。","農桑連紫陌，分野入青州。","覆被恩難報，西看成白頭。"]', '["漢家分列宿，东土佐諸侯。","結束還軍府，光輝過御溝。","農桑連紫陌，分野入青州。","覆被恩难報，西看成白头。"]', '诗', 'shi', '', NULL, '送陸郎中歸田司空幕 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b4af0a9-b307-4092-bb74-859934b5e429', '酬晉侍御見寄', '酬晉侍御见寄', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["野客蒙詩贈，殊恩欲報難。","本求文舉識，不在子真官。","細雨雙林暮，重陽九日寒。","貧齋一叢菊，願與上賓看。"]', '["野客蒙诗贈，殊恩欲報难。","本求文舉識，不在子真官。","細雨雙林暮，重陽九日寒。","貧斋一叢菊，願與上賓看。"]', '诗', 'shi', '', NULL, '酬晉侍御見寄 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae54e684-8316-4298-b04d-1ad47322262b', '送銅澤王歸城', '送銅澤王归城', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["昔聞公族出，其從亦高車。","爲善唯求樂，分貧必及疎。","身承漢枝葉，手習魯詩書。","尚說無功德，三年在石渠。"]', '["昔闻公族出，其從亦高车。","爲善唯求乐，分貧必及疎。","身承漢枝葉，手習魯诗书。","尚说無功德，三年在石渠。"]', '诗', 'shi', '', NULL, '送銅澤王歸城 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ce098bc-1f0b-4e01-95fb-d0eba63ef813', '江上別柳中庸', '江上別柳中庸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["秦人江上見，握手便霑衣。","近日相知少，往年親故稀。","遠遊何處去，舊業幾時歸。","更向巴陵宿，堪聞雁北飛。"]', '["秦人江上见，握手便霑衣。","近日相知少，往年親故稀。","远游何处去，旧業幾时归。","更向巴陵宿，堪闻雁北飞。"]', '诗', 'shi', '', NULL, '江上別柳中庸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9345bb4c-1059-4af4-9c1e-c75839490a66', '喜皇甫郎中拜諭德兼集賢學士', '喜皇甫郎中拜諭德兼集賢学士', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["爲郎三載後，寵命一朝新。","望苑遷詞客，儒林拜丈人。","鶯飛綺閣曙，柳拂畫堂春。","幾日調金鼎，諸君欲望塵。"]', '["爲郎三載後，寵命一朝新。","望苑遷词客，儒林拜丈人。","鶯飞綺閣曙，柳拂畫堂春。","幾日調金鼎，諸君欲望塵。"]', '诗', 'shi', '', NULL, '喜皇甫郎中拜諭德兼集賢學士 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e114210-7201-44d1-a969-2afc1146136c', '送黎兵曹往陝府結婚', '送黎兵曹往陝府結婚', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["東方發車騎，君是上頭人。","奠雁逢良日，行媒及仲春。","時稱渡河婦，宜配坦牀賓。","安得同門吏，揚鞭入後塵。"]', '["东方發车騎，君是上头人。","奠雁逢良日，行媒及仲春。","时稱渡河婦，宜配坦牀賓。","安得同门吏，揚鞭入後塵。"]', '诗', 'shi', '', NULL, '送黎兵曹往陝府結婚 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8b648ab-64a5-4200-9a19-f721ca120ffb', '送竇兵曹', '送竇兵曹', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["梨花開上苑，遊女著羅衣。","聞道情人怨，應須走馬歸。","御橋遲日暖，官渡早鶯稀。","莫遣佳期過，看看蝴蝶飛。"]', '["梨花开上苑，游女著羅衣。","闻道情人怨，應須走马归。","御橋遲日暖，官渡早鶯稀。","莫遣佳期過，看看蝴蝶飞。"]', '诗', 'shi', '', NULL, '送竇兵曹 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f66715b5-7e80-4014-acb6-6bed68d6a4f4', '留別故人', '留別故人', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["此別不可道，此心當語誰。","春風灞水上，飲馬桃花時。","誤作好文士，祗應遊宦遲。","留書下朝客，我有故山期。"]', '["此別不可道，此心當語誰。","春风灞水上，饮马桃花时。","誤作好文士，祗應游宦遲。","留书下朝客，我有故山期。"]', '诗', 'shi', '', NULL, '留別故人 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6ff7f8-433b-4dc6-b98f-d78991d0b06f', '奉送宋中丞使河源', '奉送宋中丞使河源', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["東周遣戍役，才子欲離羣。","部領河源去，悠悠隴水分。","笳聲悲塞草，馬首渡關雲。","辛苦逢炎熱，何時及漢軍。"]', '["东周遣戍役，才子欲離羣。","部領河源去，悠悠隴水分。","笳声悲塞草，马首渡关云。","辛苦逢炎熱，何时及漢軍。"]', '诗', 'shi', '', NULL, '奉送宋中丞使河源 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89a5fd37-28dd-45c0-8b3f-b9165559b092', '都亭驛送郭判官之幽州幕府', '都亭驛送郭判官之幽州幕府', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["幕府參戎事，承明伏奏歸。","都亭使者出，杯酒故人違。","細雨霑官騎，輕風拂客衣。","還從大夫後，吾黨亦光輝。"]', '["幕府參戎事，承明伏奏归。","都亭使者出，杯酒故人違。","細雨霑官騎，轻风拂客衣。","還從大夫後，吾黨亦光輝。"]', '诗', 'shi', '', NULL, '都亭驛送郭判官之幽州幕府 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afe5ec61-08a5-47a6-8e03-dd06e917592b', '送王羽林往秦州', '送王羽林往秦州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["秦州貴公子，漢日羽林郎。","事主來中禁，榮親上北堂。","輶車花擁路，寶劒雪生光。","直掃三邊靖，承恩向建章。"]', '["秦州貴公子，漢日羽林郎。","事主来中禁，榮親上北堂。","輶车花擁路，寶劒雪生光。","直掃三邊靖，承恩向建章。"]', '诗', 'shi', '', NULL, '送王羽林往秦州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afb2ce80-73ac-47b6-bc68-bbcb083c31a3', '送友入關', '送友入关', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["聞君帝城去，西望一沾巾。","落日見秋草，暮年逢故人。","非才長作客，有命懶謀身。","近更嬰衰疾，空思老漢濱。"]', '["闻君帝城去，西望一沾巾。","落日见秋草，暮年逢故人。","非才长作客，有命懶謀身。","近更嬰衰疾，空思老漢濱。"]', '诗', 'shi', '', NULL, '送友入關 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b8d0786-3a7f-4231-8180-2e7706ef4fc8', '代宗輓歌', '代宗輓歌', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["祖庭三獻罷，嚴衞百靈朝。","警蹕移前殿，宮車上渭橋。","寒霜凝羽葆，野吹咽笳簫。","已向新京兆，誰云天路遙。"]', '["祖庭三獻罷，嚴衞百靈朝。","警蹕移前殿，宮车上渭橋。","寒霜凝羽葆，野吹咽笳簫。","已向新京兆，誰云天路遙。"]', '诗', 'shi', '', NULL, '代宗輓歌 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58dc279b-eebd-40eb-8ab6-ff1401504150', '張左丞輓歌二首 一', '張左丞輓歌二首 一', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["素斾低寒水，清笳出曉風。","鳥來傷賈傅，馬立葬滕公。","松柏青山上，城池白日中。","一朝今古隔，唯有月明同。"]', '["素斾低寒水，清笳出晓风。","鸟来傷賈傅，马立葬滕公。","松柏青山上，城池白日中。","一朝今古隔，唯有月明同。"]', '诗', 'shi', '', NULL, '張左丞輓歌二首 一 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eb64614-d5a4-43a5-a796-a485efaeaced', '張左丞輓歌二首 二', '張左丞輓歌二首 二', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["禍集鉤方失，災生劒忽飛。","無由就日拜，空憶自天歸。","門吏看還葬，宮官識賜衣。","東堂哀贈畢，從此故臣稀。"]', '["禍集鉤方失，災生劒忽飞。","無由就日拜，空憶自天归。","门吏看還葬，宮官識賜衣。","东堂哀贈畢，從此故臣稀。"]', '诗', 'shi', '', NULL, '張左丞輓歌二首 二 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc44e3c3-935e-466d-9741-9fdffaaccba6', '奉和王元二相避暑懷杜太尉', '奉和王元二相避暑懷杜太尉', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["艱難嘗共理，海晏更相悲。","況復登堂處，分明避暑時。","綠槐千穗綻，丹藥一番遲。","蓬蓽今何幸，先朝大雅詩。"]', '["艱难嘗共理，海晏更相悲。","況复登堂处，分明避暑时。","綠槐千穗綻，丹藥一番遲。","蓬蓽今何幸，先朝大雅诗。"]', '诗', 'shi', '', NULL, '奉和王元二相避暑懷杜太尉 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f92902f3-cfd7-4e89-bfec-3d439a6bf9b8', '青龍寺題故曇上人房', '青龙寺題故曇上人房', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["遠公留故院，一徑雪中微。","童子逢皆老，門人問亦稀。","飜經徒有處，攜履遂無歸。","空念尋巢鶴，時來傍影飛。"]', '["远公留故院，一徑雪中微。","童子逢皆老，门人问亦稀。","飜經徒有处，携履遂無归。","空念尋巢鹤，时来傍影飞。"]', '诗', 'shi', '', NULL, '青龍寺題故曇上人房 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85eadf60-2f98-41b2-88bf-b6337fa120e4', '早春夜望', '早春夜望', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["舊雪逐泥沙，新雷發草芽。","曉霜應傍鬢，夜雨莫催花。","行矣前途晚，歸歟故國賒。","不勞報春盡，從此惜年華。"]', '["旧雪逐泥沙，新雷發草芽。","晓霜應傍鬢，夜雨莫催花。","行矣前途晚，归歟故国賒。","不勞報春尽，從此惜年华。"]', '诗', 'shi', '', NULL, '早春夜望 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0ba3e7-f201-4fa9-8caa-ff18105e927a', '宴伊東岸', '宴伊东岸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["晴洲無遠近，一樹一潭春。","芳草留歸騎，朱櫻擲舞人。","空花對酒落，小翠隔林新。","竟日皆攜手，何由遇此辰。"]', '["晴洲無远近，一樹一潭春。","芳草留归騎，朱櫻擲舞人。","空花对酒落，小翠隔林新。","竟日皆携手，何由遇此辰。"]', '诗', 'shi', '', NULL, '宴伊東岸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c2627a-cb2c-427e-a74c-e753682fa41c', '雲際中峰居喜見苗發', '云際中峰居喜见苗發', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["自得中峰住，深林亦閉關。","經秋無客到，入夜有僧還。","暗澗泉聲小，荒村樹影閑。","高窗不可望，星月滿空山。"]', '["自得中峰住，深林亦閉关。","經秋無客到，入夜有僧還。","暗澗泉声小，荒村樹影闲。","高窗不可望，星月满空山。"]', '诗', 'shi', '', NULL, '雲際中峰居喜見苗發 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81493d1-0362-481b-9249-42674555c65c', '宿洞庭', '宿洞庭', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["白水連天暮，洪波帶日流。","風高雲夢夕，月滿洞庭秋。","沙上漁人火，煙中賈客舟。","西園與南浦，萬里共悠悠。"]', '["白水連天暮，洪波带日流。","风高云梦夕，月满洞庭秋。","沙上漁人火，煙中賈客舟。","西园與南浦，万里共悠悠。"]', '诗', 'shi', '', NULL, '宿洞庭 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d4eccc-5f8b-483a-81ff-f610464ab4ea', '江上賽神', '江上賽神', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["疎鼓應繁絲，送神歸九疑。","蒼龍隨赤鳳，帝子上天時。","驟雨歸山疾，長江下日遲。","獨憐遊宦子，今夜泊天涯。"]', '["疎鼓應繁絲，送神归九疑。","蒼龙隨赤鳳，帝子上天时。","驟雨归山疾，长江下日遲。","独怜游宦子，今夜泊天涯。"]', '诗', 'shi', '', NULL, '江上賽神 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39fdb908-0035-476f-b871-31447e4f7af1', '奉和元丞侍從遊南城別業', '奉和元丞侍從游南城別業', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["垂朱領孫子，從宴在池塘。","獻壽回龜顧，和羹躍鯉香。","高松先草晚，平石助泉涼。","餘橘期相及，門生有陸郎。"]', '["垂朱領孫子，從宴在池塘。","獻壽回龟顧，和羹躍鯉香。","高松先草晚，平石助泉涼。","餘橘期相及，门生有陸郎。"]', '诗', 'shi', '', NULL, '奉和元丞侍從遊南城別業 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b6f6d7f-30d6-4ca9-955c-d5afe32401bb', '送從舅成都丞廣南歸蜀', '送從舅成都丞廣南归蜀', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["巴字天邊水，秦人去是歸。","棧長山雨響，溪亂火田稀。","俗富行應樂，官雄祿豈微。","魏舒終有淚，還濕甯家衣。"]', '["巴字天邊水，秦人去是归。","棧长山雨响，溪亂火田稀。","俗富行應乐，官雄祿豈微。","魏舒終有泪，還濕甯家衣。"]', '诗', 'shi', '', NULL, '送從舅成都丞廣南歸蜀 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d119e9a6-56b9-499a-a23a-3e76c0a12e99', '贈郭駙馬 一', '贈郭駙马 一', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["青春都尉最風流，二十功成便拜侯。","金距鬬雞過上苑，玉鞭騎馬出長楸。","熏香荀令偏憐少，傅粉何郎不解愁。","日暮吹簫楊柳陌，路人遙指鳳凰樓。"]', '["青春都尉最风流，二十功成便拜侯。","金距鬬雞過上苑，玉鞭騎马出长楸。","熏香荀令偏怜少，傅粉何郎不解愁。","日暮吹簫楊柳陌，路人遙指鳳凰楼。"]', '诗', 'shi', '', NULL, '贈郭駙馬 一 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a1494a-7c0a-4513-a828-6443abe9db0a', '贈郭駙馬 二', '贈郭駙马 二', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["方塘似鏡草芊芊，初月如鉤未上弦。","新開金埒看調馬，舊賜銅山許鑄錢。","楊柳入樓吹玉笛，芙蓉出水妬花鈿。","今朝都尉如相顧，願脫長裾學少年。"]', '["方塘似镜草芊芊，初月如鉤未上弦。","新开金埒看調马，旧賜銅山許鑄錢。","楊柳入楼吹玉笛，芙蓉出水妬花鈿。","今朝都尉如相顧，願脫长裾学少年。"]', '诗', 'shi', '', NULL, '贈郭駙馬 二 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7b59ce3-5d91-4ee2-b8ef-32416721d445', '宿淮浦憶司空文明', '宿淮浦憶司空文明', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["愁心一倍長離憂，夜思千重戀舊遊。","秦地故人成遠夢，楚天涼雨在孤舟。","諸溪近海潮皆應，獨樹邊淮葉盡流。","別恨轉深何處寫，前程唯有一登樓。"]', '["愁心一倍长離憂，夜思千重戀旧游。","秦地故人成远梦，楚天涼雨在孤舟。","諸溪近海潮皆應，独樹邊淮葉尽流。","別恨轉深何处寫，前程唯有一登楼。"]', '诗', 'shi', '', NULL, '宿淮浦憶司空文明 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('898151bf-b3b7-4387-b41c-f56da1575e2e', '送濮陽錄事赴忠州', '送濮陽錄事赴忠州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["成名不遂雙旌遠，主印還爲一郡雄。","赤葉黃花隨野岸，青山白水映江楓。","巴人夜語孤舟裏，越鳥春啼萬壑中。","聞說古書多未校，肯令才子久西東。"]', '["成名不遂雙旌远，主印還爲一郡雄。","赤葉黄花隨野岸，青山白水映江楓。","巴人夜語孤舟裏，越鸟春啼万壑中。","闻说古书多未校，肯令才子久西东。"]', '诗', 'shi', '', NULL, '送濮陽錄事赴忠州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a35d2a45-1ce1-4455-a251-7398f204aecd', '送馬尊師', '送马尊師', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["南入商山松路深，石牀溪水晝陰陰。","雲中採藥隨青節，洞裏耕田映綠林。","直上煙霞空舉手，迴經丘壠自傷心。","武陵花木應長在，願與漁人更一尋。"]', '["南入商山松路深，石牀溪水晝陰陰。","云中採藥隨青節，洞裏耕田映綠林。","直上煙霞空舉手，迴經丘壠自傷心。","武陵花木應长在，願與漁人更一尋。"]', '诗', 'shi', '', NULL, '送馬尊師 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72e511e9-1a49-4cf9-a2fe-c5456af41343', '題元注林園', '題元注林园', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["謝家門館似山林，碧石青苔滿樹陰。","乳鵲眄巢花巷靜，鳴鳩鼓翼竹園深。","桔槔轉水兼通藥，方丈留僧共聽琴。","獨有野人箕踞慣，過君始得一長吟。"]', '["謝家门館似山林，碧石青苔满樹陰。","乳鵲眄巢花巷静，鳴鳩鼓翼竹园深。","桔槔轉水兼通藥，方丈留僧共听琴。","独有野人箕踞慣，過君始得一长吟。"]', '诗', 'shi', '', NULL, '題元注林園 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39640e40-b5f6-4ca0-8106-235b98251880', '野寺病居喜盧綸見訪', '野寺病居喜盧綸见訪', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["青青麥壠白雲陰，古寺無人新草深。","乳燕拾泥依古井，鳴鳩拂羽歷花林。","千年駁蘚明山履，萬尺垂蘿入水心。","一臥漳濱今欲老，誰知才子忽相尋。"]', '["青青麦壠白云陰，古寺無人新草深。","乳燕拾泥依古井，鳴鳩拂羽歷花林。","千年駁蘚明山履，万尺垂蘿入水心。","一臥漳濱今欲老，誰知才子忽相尋。"]', '诗', 'shi', '', NULL, '野寺病居喜盧綸見訪 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b9e4720-2ced-46a8-8cd2-be4575f67658', '送皎然上人歸山', '送皎然上人归山', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["適來世上豈緣名，適去人間豈爲情。","古寺山中幾日到，高松月下一僧行。","雲陰鳥道苔方合，雪映龍潭水更清。","法主欲歸須有說，門人流淚厭浮生。"]', '["適来世上豈緣名，適去人间豈爲情。","古寺山中幾日到，高松月下一僧行。","云陰鸟道苔方合，雪映龙潭水更清。","法主欲归須有说，门人流泪厭浮生。"]', '诗', 'shi', '', NULL, '送皎然上人歸山 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97d8a9f6-e9da-443f-8e24-4003ee81123e', '贈道士', '贈道士', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["姓氏不書高士傳，形神自得逸人風。","已傳花洞將秦接，更指茅山與蜀通。","嬾說歲年齊絳老，甘爲鄉曲號涪翁。","終朝賣卜無人識，敝服徒行入市中。"]', '["姓氏不书高士傳，形神自得逸人风。","已傳花洞將秦接，更指茅山與蜀通。","嬾说歲年齊絳老，甘爲乡曲號涪翁。","終朝賣卜無人識，敝服徒行入市中。"]', '诗', 'shi', '', NULL, '贈道士 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7943654f-0f18-46ff-a747-e667525eb8f2', '題雲際寺準上人房', '題云際寺準上人房', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["高僧居處似天台，錫杖銅瓶對綠苔。","竹巷雨晴春鳥囀，山房日午老人來。","園中鹿過椒枝動，潭底龍遊水沫開。","獨夜焚香禮遺像，空林月出始應迴。"]', '["高僧居处似天台，錫杖銅瓶对綠苔。","竹巷雨晴春鸟囀，山房日午老人来。","园中鹿過椒枝动，潭底龙游水沫开。","独夜焚香禮遺像，空林月出始應迴。"]', '诗', 'shi', '', NULL, '題雲際寺準上人房 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e83897d9-af00-4337-bd76-3679065976e9', '山中寄苗員外', '山中寄苗員外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["鳥鳴花發空山裏，衡岳幽人藉草時。","既近淺流安筆硯，還因平石布蓍龜。","千尋楚水橫琴望，萬里秦城帶酒思。","聞說潘安方寓直，與君相見漸難期。"]', '["鸟鳴花發空山裏，衡岳幽人藉草时。","既近淺流安笔硯，還因平石布蓍龟。","千尋楚水橫琴望，万里秦城带酒思。","闻说潘安方寓直，與君相见漸难期。"]', '诗', 'shi', '', NULL, '山中寄苗員外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855456e2-f8a8-4344-b207-b764395bda19', '憶故山贈司空曙', '憶故山贈司空曙', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["漢主金門正召才，馬卿多病自遲迴。","舊山蹔別老將至，芳草欲闌歸去來。","雲在高天風會起，年如流水日長催。","知君素有棲禪意，歲晏蓬門遲爾開。"]', '["漢主金门正召才，马卿多病自遲迴。","旧山蹔別老將至，芳草欲闌归去来。","云在高天风會起，年如流水日长催。","知君素有棲禪意，歲晏蓬门遲爾开。"]', '诗', 'shi', '', NULL, '憶故山贈司空曙 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb090f98-6185-4fba-8fe0-6bb295821b61', '閑園即事贈考功王員外', '闲园即事贈考功王員外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["南陌晴雲稍變霞，東風動柳水紋斜。","園林帶雪潛生草，桃李雖春未有花。","幸接上賓登鄭驛，羞爲長女似黃家。","今朝一望還成暮，欲別芳菲戀歲華。"]', '["南陌晴云稍变霞，东风动柳水紋斜。","园林带雪潛生草，桃李雖春未有花。","幸接上賓登鄭驛，羞爲长女似黄家。","今朝一望還成暮，欲別芳菲戀歲华。"]', '诗', 'shi', '', NULL, '閑園即事贈考功王員外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c23fcb9d-ed9e-4289-b0bb-c54e2b39ca6e', '寄廬山真上人', '寄廬山真上人', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["高僧無跡本難尋，更得禪行去轉深。","青草湖中看五老，白雲山上宿雙林。","月明潭色澄空性，夜靜猨聲證道心。","更[說謝]公南座好，煙蘿到地幾重陰。"]', '["高僧無跡本难尋，更得禪行去轉深。","青草湖中看五老，白云山上宿雙林。","月明潭色澄空性，夜静猨声證道心。","更[说謝]公南座好，煙蘿到地幾重陰。"]', '诗', 'shi', '', NULL, '寄廬山真上人 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5280a77-ac56-47b6-b489-76f03fc8fb5a', '題覺公新蘭若', '題覺公新蘭若', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["頭白禪師何處還，獨開蘭若樹林間。","鬼因巫祝傳移社，神見天人請施山。","猛虎聽經金磬動，獼猴獻蜜雪窗閒。","新齋結誓如相許，願與雷宗永閉關。"]', '["头白禪師何处還，独开蘭若樹林间。","鬼因巫祝傳移社，神见天人請施山。","猛虎听經金磬动，獼猴獻蜜雪窗閒。","新斋結誓如相許，願與雷宗永閉关。"]', '诗', 'shi', '', NULL, '題覺公新蘭若 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57de89d2-d4bc-4d67-b88a-2cea34883ed5', '贈道者', '贈道者', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["窗中忽有鶴飛聲，方士因知道欲成。","來取圖書安枕裏，便驅雞犬向山行。","花開深洞仙門小，路過懸橋羽節輕。"]', '["窗中忽有鹤飞声，方士因知道欲成。","来取圖书安枕裏，便驱雞犬向山行。","花开深洞仙门小，路過懸橋羽節轻。"]', '诗', 'shi', '', NULL, '贈道者 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a15caa6f-dbca-4eec-8445-a1ece443d115', '代棄婦答賈客', '代棄婦答賈客', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["玉壘城邊爭走馬，銅鞮市裏共乘舟。","鳴環動珮恩無盡，掩袖低巾淚不流。","疇昔將歌邀客醉，如今欲舞對君羞。","忍懷賤妾平生曲，獨上襄陽舊酒樓。"]', '["玉壘城邊爭走马，銅鞮市裏共乘舟。","鳴环动珮恩無尽，掩袖低巾泪不流。","疇昔將歌邀客醉，如今欲舞对君羞。","忍懷賤妾平生曲，独上襄陽旧酒楼。"]', '诗', 'shi', '', NULL, '代棄婦答賈客 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('668bda10-2fcd-45a3-9795-a8393e22ae00', '和李舍人直中書對月見寄', '和李舍人直中书对月见寄', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["名卿步月正淹留，上客裁詩怨別遊。","素魄近成班女扇，清光遠似庾公樓。","嬋娟更稱凭高望，皎潔能傳自古愁。","盈手入懷皆不見，陽春曲麗轉難酬。"]', '["名卿步月正淹留，上客裁诗怨別游。","素魄近成班女扇，清光远似庾公楼。","嬋娟更稱凭高望，皎潔能傳自古愁。","盈手入懷皆不见，陽春曲丽轉难酬。"]', '诗', 'shi', '', NULL, '和李舍人直中書對月見寄 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62ecb6aa-2aeb-41c1-9b6c-78784005f52d', '臥病聞吉中孚拜官寄元秘書昆季', '臥病闻吉中孚拜官寄元秘书昆季', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["漢家採使不求聲，自慰文章道欲行。","毛遂登門雖異賞，韓非入傳濫齊名。","雲歸暫愛青山出，客去還愁白髮生。","年少奉親皆願達，敢將心事向玄成。"]', '["漢家採使不求声，自慰文章道欲行。","毛遂登门雖異賞，韓非入傳濫齊名。","云归暫愛青山出，客去還愁白髮生。","年少奉親皆願達，敢將心事向玄成。"]', '诗', 'shi', '', NULL, '臥病聞吉中孚拜官寄元秘書昆季 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('967ac6e2-b5ec-4d6c-b3e3-51ed1e9711d6', '江上逢柳中庸', '江上逢柳中庸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["舊住衡山曾夜歸，見君江客憶荆扉。","星沉嶺上人行早，月過湖西鶴唳稀。","弱竹萬株頻礙幘，新泉數步一褰衣。","今來唯有禪心在，鄉路翻成向翠微。"]', '["旧住衡山曾夜归，见君江客憶荆扉。","星沉嶺上人行早，月過湖西鹤唳稀。","弱竹万株頻礙幘，新泉數步一褰衣。","今来唯有禪心在，乡路翻成向翠微。"]', '诗', 'shi', '', NULL, '江上逢柳中庸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fa3ea71-5f33-42c7-8b83-2b96734e20cd', '戲贈韓判官紳卿', '戲贈韓判官紳卿', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["少尋道士居嵩嶺，晚事高僧住沃洲。","齒發未知何處老，身名且被外人愁。","欲隨山水居茅洞，已有田園在虎丘。","獨怪子猷緣掌馬，雪時不肯更乘舟。"]', '["少尋道士居嵩嶺，晚事高僧住沃洲。","齒發未知何处老，身名且被外人愁。","欲隨山水居茅洞，已有田园在虎丘。","独怪子猷緣掌马，雪时不肯更乘舟。"]', '诗', 'shi', '', NULL, '戲贈韓判官紳卿 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86e50e91-b337-47f9-bfee-4899b4ac4a84', '送周長史', '送周长史', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["青楓樹裏宣城郡，獨佐諸侯上板橋。","江客亦能傳好信，山僧多解說南朝。","雲陰出浦看帆小，草色連天見雁遙。","別有空園落桃杏，知將絲組繫蘭橈。"]', '["青楓樹裏宣城郡，独佐諸侯上板橋。","江客亦能傳好信，山僧多解说南朝。","云陰出浦看帆小，草色連天见雁遙。","別有空园落桃杏，知將絲組繫蘭橈。"]', '诗', 'shi', '', NULL, '送周長史 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad6b3e0-61b6-4182-a4f5-2076f8cb940d', '題故將軍莊', '題故將軍莊', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["曾將數騎過桑乾，遙對單于飭馬鞍。","塞北征兒諳用劍，關西宿將許登壇。","田園蕪沒歸耕晚，弓箭開離出獵難。","唯有老身如刻畫，猶期聖主解衣看。"]', '["曾將數騎過桑乾，遙对單于飭马鞍。","塞北征兒諳用劍，关西宿將許登壇。","田园蕪沒归耕晚，弓箭开離出獵难。","唯有老身如刻畫，猶期聖主解衣看。"]', '诗', 'shi', '', NULL, '題故將軍莊 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8b54726-0666-42fb-82ea-f60b2deff99c', '夜投豐德寺謁海上人', '夜投豐德寺謁海上人', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["半夜中峰有磬聲，偶尋樵者問山名。","上方月曉聞僧語，下界林疎見客行。","野鶴巢邊松最老，毒龍潛處水偏清。","願得遠山知姓字，焚香洗鉢過餘生。"]', '["半夜中峰有磬声，偶尋樵者问山名。","上方月晓闻僧語，下界林疎见客行。","野鹤巢邊松最老，毒龙潛处水偏清。","願得远山知姓字，焚香洗鉢過餘生。"]', '诗', 'shi', '', NULL, '夜投豐德寺謁海上人 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d1f6a8f-dd04-4527-a631-86238208076f', '塞上', '塞上', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["二十在邊城，軍中得勇名。","卷旗收敗馬，占磧擁殘兵。","覆陣烏鳶起，燒山草木明。","塞閑思遠獵，師老厭分營。","雪嶺無人跡，冰河足雁聲。","李陵甘此沒，惆悵漢公卿。"]', '["二十在邊城，軍中得勇名。","卷旗收敗马，占磧擁殘兵。","覆陣烏鳶起，燒山草木明。","塞闲思远獵，師老厭分營。","雪嶺無人跡，冰河足雁声。","李陵甘此沒，惆悵漢公卿。"]', '诗', 'shi', '', NULL, '塞上 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc48a2e-dbd3-4862-8c5d-8e979f418df7', '送彭將軍雲中覲兄', '送彭將軍云中覲兄', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["聞說蒼鷹守，今朝欲下韛。","因令白馬將，兼道覓封侯。","略地關山冷，防河雨雪稠。","飜弓騁猨臂，承箭惜貂裘。","設伏軍謀密，坑降塞邑愁。","報恩唯有死，莫使漢家羞。"]', '["闻说蒼鷹守，今朝欲下韛。","因令白马將，兼道覓封侯。","略地关山冷，防河雨雪稠。","飜弓騁猨臂，承箭惜貂裘。","設伏軍謀密，坑降塞邑愁。","報恩唯有死，莫使漢家羞。"]', '诗', 'shi', '', NULL, '送彭將軍雲中覲兄 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0229d4a7-2410-41e2-ab77-0022f9a70c38', '奉贈苗員外', '奉贈苗員外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["朱戶敞高扉，青槐礙落暉。","八龍承慶重，三虎遞朝歸。","坐竹人聲絕，橫琴鳥語稀。","花慙潘岳貌，年稱老萊衣。","葉暗新櫻熟，絲長粉蝶飛。","應憐魯儒賤，空與故山違。"]', '["朱戶敞高扉，青槐礙落暉。","八龙承慶重，三虎遞朝归。","坐竹人声絕，橫琴鸟語稀。","花慙潘岳貌，年稱老萊衣。","葉暗新櫻熟，絲长粉蝶飞。","應怜魯儒賤，空與故山違。"]', '诗', 'shi', '', NULL, '奉贈苗員外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a76e84bc-e1e1-459a-90bb-e2185b4a4ba3', '酬丘拱外甥覽余舊文見寄', '酬丘拱外甥覽余旧文见寄', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["丘遲本才子，始冠即周旋。","舅乏郄鑒愛，君如衞玠賢。","禮將金友等，情向玉人偏。","鄙俗那勞似，龍鍾却要憐。","投甎聊取笑，贈綺一何妍。","野坐臨黃菊，溪行踏綠錢。","巖高雲反下，洞黑水潛穿。","僻嶺猿偷栗，枯池雁唼蓮。","身居霞外寺，思發月明田。","猶恨縈塵網，昏昏過幾年。"]', '["丘遲本才子，始冠即周旋。","舅乏郄鑒愛，君如衞玠賢。","禮將金友等，情向玉人偏。","鄙俗那勞似，龙鍾却要怜。","投甎聊取笑，贈綺一何妍。","野坐臨黄菊，溪行踏綠錢。","巖高云反下，洞黑水潛穿。","僻嶺猿偷栗，枯池雁唼蓮。","身居霞外寺，思發月明田。","猶恨縈塵網，昏昏過幾年。"]', '诗', 'shi', '', NULL, '酬丘拱外甥覽余舊文見寄 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60bd6be-1b14-4468-8178-3c55883594d5', '贈岐山姜明府', '贈岐山姜明府', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["昨夜聞山雨，歸心便似遲。","幾迴驚葉落，即到白頭時。","雁影將魂去，蟲聲與淚期。","馬卿兼病老，宋玉對秋悲。","謝客纔爲別，陶公已見思。","非關口腹累，自是雪霜姿。","釀酒栽黃菊，炊粳折綠葵。","山河方入望，風日正宜詩。","牧豎寒騎馬，邊烽晚立旗。","蘭凋猶有氣，柳脆不成絲。","別後如相問，高僧知所之。"]', '["昨夜闻山雨，归心便似遲。","幾迴驚葉落，即到白头时。","雁影將魂去，蟲声與泪期。","马卿兼病老，宋玉对秋悲。","謝客纔爲別，陶公已见思。","非关口腹累，自是雪霜姿。","釀酒栽黄菊，炊粳折綠葵。","山河方入望，风日正宜诗。","牧豎寒騎马，邊烽晚立旗。","蘭凋猶有氣，柳脆不成絲。","別後如相问，高僧知所之。"]', '诗', 'shi', '', NULL, '贈岐山姜明府 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90c22c3-4ea6-4839-b4c1-f01f10e03d19', '下第上薛侍郎', '下第上薛侍郎', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["蓬蓽春風起，開簾却自悲。","如何飄梗處，又到採蘭時。","明鏡方重照，微城寄一辭。","家貧求祿早，身賤報恩遲。","幸得皮存矣，須勞翼長之。","銘肌非厚荅，肉骨是前期。","縱覺新人好，寧忘舊主疑。","終慙太丘道，不爲小生私。"]', '["蓬蓽春风起，开簾却自悲。","如何飄梗处，又到採蘭时。","明镜方重照，微城寄一辞。","家貧求祿早，身賤報恩遲。","幸得皮存矣，須勞翼长之。","銘肌非厚荅，肉骨是前期。","縱覺新人好，寧忘旧主疑。","終慙太丘道，不爲小生私。"]', '诗', 'shi', '', NULL, '下第上薛侍郎 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b478b1-bef3-4398-ab4d-02f480749554', '奉和秘書元丞杪秋憶終南舊居', '奉和秘书元丞杪秋憶終南旧居', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["高門有才子，能履古人蹤。","白社陶元亮，青雲阮仲容。","田園忽歸去，車馬杳難逢。","廢巷臨秋水，支頤向暮峰。","行魚避楊柳，驚鴨觸芙蓉。","石竇紅泉細，山橋紫菜重。","鳳雛終食竹，鶴侶暫巢松。","願接煙霞賞，羈離計不從。"]', '["高门有才子，能履古人蹤。","白社陶元亮，青云阮仲容。","田园忽归去，车马杳难逢。","廢巷臨秋水，支頤向暮峰。","行鱼避楊柳，驚鴨觸芙蓉。","石竇紅泉細，山橋紫菜重。","鳳雛終食竹，鹤侶暫巢松。","願接煙霞賞，羈離計不從。"]', '诗', 'shi', '', NULL, '奉和秘書元丞杪秋憶終南舊居 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd2ab416-81a4-4e12-a9b4-1dec6b86ac43', '送歸中丞使新羅', '送归中丞使新羅', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["東望扶桑日，何年是到時。","片帆通雨露，積水隔華夷。","浩淼風來遠，虛冥鳥去遲。","長波靜雲月，孤島宿旌旗。","別葉傳秋意，迴潮動客思。","滄溟無舊路，何處問前期。"]', '["东望扶桑日，何年是到时。","片帆通雨露，積水隔华夷。","浩淼风来远，虛冥鸟去遲。","长波静云月，孤島宿旌旗。","別葉傳秋意，迴潮动客思。","滄溟無旧路，何处问前期。"]', '诗', 'shi', '', NULL, '送歸中丞使新羅 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6283b73-915a-4959-8579-19cc7e057f69', '暮春尋終南柳處士', '暮春尋終南柳处士', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["龐眉一居士，鶉服隱堯時。","種荳初成畝，還丹舊日師。","入溪花徑遠，向嶺鳥行遲。","紫葛垂苔壁，青菰映柳絲。","偶來塵外事，暫與素心期。","終恨遊春宮，同爲歲月悲。"]', '["龐眉一居士，鶉服隐堯时。","種荳初成畝，還丹旧日師。","入溪花徑远，向嶺鸟行遲。","紫葛垂苔壁，青菰映柳絲。","偶来塵外事，暫與素心期。","終恨游春宮，同爲歲月悲。"]', '诗', 'shi', '', NULL, '暮春尋終南柳處士 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29913307-4c08-4df9-baa4-89954f13172a', '雪夜尋太白道士', '雪夜尋太白道士', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["雪路夜朦朧，尋師杏樹東。","石壇連竹靜，醮火照山紅。","再拜開金籙，焚香使玉童。","篷瀛三島至，天地一壺通。","別客曾留藥，逢舟或借風。","出遊居鶴上，避禍入羊中。","過洞偏迴首，登門未發蒙。","桑田如可見，滄海幾時空。"]', '["雪路夜朦朧，尋師杏樹东。","石壇連竹静，醮火照山紅。","再拜开金籙，焚香使玉童。","篷瀛三島至，天地一壺通。","別客曾留藥，逢舟或借风。","出游居鹤上，避禍入羊中。","過洞偏迴首，登门未發蒙。","桑田如可见，滄海幾时空。"]', '诗', 'shi', '', NULL, '雪夜尋太白道士 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18970206-4b28-4c5e-974f-a9ef44cbc9a7', '得山中道友書寄苗銭二員外', '得山中道友书寄苗銭二員外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["有謀皆轗軻，非病亦遲迴。","壯志年年減，馳暉日日催。","還山不及伴，到闕又無媒。","高臥成長策，微官稱下才。","詩人識何謝，居士別宗雷。","跡向塵中隱，書從谷口來。","藥欄遭鹿踐，澗戶被猿開。","野鶴巢雲竇，遊龜上水苔。","新歡追易失，故思渺難裁。","自有歸期在，勞君示劫灰。"]', '["有謀皆轗軻，非病亦遲迴。","壯志年年減，驰暉日日催。","還山不及伴，到闕又無媒。","高臥成长策，微官稱下才。","诗人識何謝，居士別宗雷。","跡向塵中隐，书從谷口来。","藥欄遭鹿踐，澗戶被猿开。","野鹤巢云竇，游龟上水苔。","新歡追易失，故思渺难裁。","自有归期在，勞君示劫灰。"]', '诗', 'shi', '', NULL, '得山中道友書寄苗銭二員外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1912131c-ca0a-497b-86b8-c4ce48a644a0', '酬前駕部員外郎苗發', '酬前駕部員外郎苗發', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["馬融方直校，閱簡復持鉛。","素業高風繼，青春壯思全。","論文多在夜，宿寺不虛年。","自署區中職，同荒郭外田。","山鄰三徑絕，野意八行傳。","煮玉矜新法，留符識舊仙。","涵苔溪溜淺，搖浪竹橋懸。","複洞潛棲燕，疎楊半翳蟬。","詠歌雖有和，雲錦獨成妍。","應以馮唐老，相譏示此篇。"]', '["马融方直校，閱簡复持鉛。","素業高风繼，青春壯思全。","論文多在夜，宿寺不虛年。","自署區中職，同荒郭外田。","山鄰三徑絕，野意八行傳。","煮玉矜新法，留符識旧仙。","涵苔溪溜淺，搖浪竹橋懸。","複洞潛棲燕，疎楊半翳蟬。","詠歌雖有和，云錦独成妍。","應以馮唐老，相譏示此篇。"]', '诗', 'shi', '', NULL, '酬前駕部員外郎苗發 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eadc463-caa7-4df0-ac58-a91ae885fe42', '宿薦福寺東池有懷故園因寄元校書', '宿薦福寺东池有懷故园因寄元校书', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["暮雨風吹盡，東池一夜涼。","伏流迴弱荇，明月入垂楊。","石竹閒開碧，薔薇暗吐黃。","倚琴看鶴舞，搖扇引桐香。","舊筍方辭籜，新蓮未滿房。","林幽花晚發，地遠草先長。","撫枕愁華鬢，凭欄想故鄉。","露餘清漢直，雲卷白榆行。","驚鵲仍依樹，遊魚不過粱。","繫舟偏憶戴，炊黍願期張。","末路還思借，前恩詎敢忘。","從來叔夜嬾，非是接輿狂。","衆病嬰公幹，羣憂集孝璋。","慙將多誤曲，今日獻周郎。"]', '["暮雨风吹尽，东池一夜涼。","伏流迴弱荇，明月入垂楊。","石竹閒开碧，薔薇暗吐黄。","倚琴看鹤舞，搖扇引桐香。","旧筍方辞籜，新蓮未满房。","林幽花晚發，地远草先长。","撫枕愁华鬢，凭欄想故乡。","露餘清漢直，云卷白榆行。","驚鵲仍依樹，游鱼不過粱。","繫舟偏憶戴，炊黍願期張。","末路還思借，前恩詎敢忘。","從来叔夜嬾，非是接輿狂。","衆病嬰公幹，羣憂集孝璋。","慙將多誤曲，今日獻周郎。"]', '诗', 'shi', '', NULL, '宿薦福寺東池有懷故園因寄元校書 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d047c01e-d574-42f8-a69e-b246ecc3c20d', '送王副使還幷州', '送王副使還幷州', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["幷州近胡地，此去事風沙。","鐵馬垂金絡，貂裘犯雪花。","曾持兩郡印，多比五侯家。","繼世新恩厚，從軍舊國賒。","戍煙千里直，邊雁一行斜。","想到清油幕，長謀出左軍。"]', '["幷州近胡地，此去事风沙。","鐵马垂金絡，貂裘犯雪花。","曾持兩郡印，多比五侯家。","繼世新恩厚，從軍旧国賒。","戍煙千里直，邊雁一行斜。","想到清油幕，长謀出左軍。"]', '诗', 'shi', '', NULL, '送王副使還幷州 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73ee65f1-307b-4978-bc2e-61918e3c6652', '晚春过夏侯校書值其沉醉戲贈', '晚春过夏侯校书值其沉醉戲贈', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["欹冠枕如意，獨寢落花前。","姚馥清時醉，邊韶白日眠。","曝褌還當屋，張幕便成天。","謁客唯題鳳，偷兒欲覘氈。","失杯猶離席，墜履反登筵。","本是牆東隱，今爲甕下僊。","臥龍髯乍磔，栖蝶腹何便。","阮籍供琴韻，陶潛餘秫田。","人逢轂陽望，春似永和年。","願我非工飲，期君行見憐。","嘗知渴羌好，亦覺醉胡賢。","炙熟樽方竭，車回轄且全。","噀風仍作雨，灑地即成泉。","自鄙新豐過，遲迴惜十年。"]', '["欹冠枕如意，独寢落花前。","姚馥清时醉，邊韶白日眠。","曝褌還當屋，張幕便成天。","謁客唯題鳳，偷兒欲覘氈。","失杯猶離席，墜履反登筵。","本是牆东隐，今爲甕下僊。","臥龙髯乍磔，栖蝶腹何便。","阮籍供琴韻，陶潛餘秫田。","人逢轂陽望，春似永和年。","願我非工饮，期君行见怜。","嘗知渴羌好，亦覺醉胡賢。","炙熟樽方竭，车回轄且全。","噀风仍作雨，灑地即成泉。","自鄙新豐過，遲迴惜十年。"]', '诗', 'shi', '', NULL, '晚春过夏侯校書值其沉醉戲贈 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('826e14b6-7575-46f7-86f5-444474771d12', '哭張南史因寄南史姪叔宗', '哭張南史因寄南史姪叔宗', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["爭路忽摧車，沈鉤未得魚。","結交唯我少，喪舊自君初。","諫草文難似，圍棊智不如。","仲宣新有賦，叔夜近無書。","地閉滕公宅，山荒謝客廬。","殲良從此恨，福善竟成虛。","釀酒多同醉，烹雞或取餘。","阮咸雖永別，豈共仲容疎。"]', '["爭路忽摧车，沈鉤未得鱼。","結交唯我少，喪旧自君初。","諫草文难似，圍棊智不如。","仲宣新有賦，叔夜近無书。","地閉滕公宅，山荒謝客廬。","殲良從此恨，福善竟成虛。","釀酒多同醉，烹雞或取餘。","阮咸雖永別，豈共仲容疎。"]', '诗', 'shi', '', NULL, '哭張南史因寄南史姪叔宗 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13bedf8d-9714-4c81-99a6-4de25b2e9845', '長安感事呈盧綸', '长安感事呈盧綸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["十五事文翰，大兒輕孔融。","長裾遊邸第，笑傲五侯中。","諫獵一朝寢，論邊素未工。","蹉跎潘鬢至，蹭蹬阮途窮。","貸布憐寧興，無金命未通。","王陵固似戇，郭最遂非雄。","斂板辭羣彥，回車訪老農。","詠詩懷洛下，送客憶山東。","沈病魂神濁，清齋思慮空。","羸將衞玠比，冷共鄴侯同。","草舍纔遮雨，荆窗不礙風。","梨教通子守，酒是遠師供。","捫虱欣時泰，迎猫達歲豐。","原門唯有席，井飲但加葱。","少壯衿齊德，高年覺宋聾。","寓書先論嬾，讀易反求蒙。","昔慕能鳴雁，今憐半死桐。","秉心猶似矢，搔首忽如蓬。","赤葉翻藤架，黃花蓋菊叢。","聊將呈匠伯，今已學愚公。"]', '["十五事文翰，大兒轻孔融。","长裾游邸第，笑傲五侯中。","諫獵一朝寢，論邊素未工。","蹉跎潘鬢至，蹭蹬阮途窮。","貸布怜寧兴，無金命未通。","王陵固似戇，郭最遂非雄。","斂板辞羣彥，回车訪老農。","詠诗懷洛下，送客憶山东。","沈病魂神濁，清斋思慮空。","羸將衞玠比，冷共鄴侯同。","草舍纔遮雨，荆窗不礙风。","梨教通子守，酒是远師供。","捫虱欣时泰，迎猫達歲豐。","原门唯有席，井饮但加葱。","少壯衿齊德，高年覺宋聾。","寓书先論嬾，读易反求蒙。","昔慕能鳴雁，今怜半死桐。","秉心猶似矢，搔首忽如蓬。","赤葉翻藤架，黄花蓋菊叢。","聊將呈匠伯，今已学愚公。"]', '诗', 'shi', '', NULL, '長安感事呈盧綸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a13d5995-b530-465b-84bc-b3c847dd1c44', '遊終南山因寄蘇奉禮士尊師苗員外', '游終南山因寄蘇奉禮士尊師苗員外', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["半嶺逢仙駕，清晨獨採芝。","壺中開白日，霧裏捲朱旂。","猨鳥知歸路，松蘿見會時。","雞聲傳洞遠，鶴語報家遲。","童子閑驅石，樵夫樂看棊。","依稀醉後拜，恍惚夢中辭。","海上終難接，人間益自疑。","風塵甘獨老，山水但相思。","願得燒丹訣，流沙永待師。"]', '["半嶺逢仙駕，清晨独採芝。","壺中开白日，霧裏捲朱旂。","猨鸟知归路，松蘿见會时。","雞声傳洞远，鹤語報家遲。","童子闲驱石，樵夫乐看棊。","依稀醉後拜，恍惚梦中辞。","海上終难接，人间益自疑。","风塵甘独老，山水但相思。","願得燒丹訣，流沙永待師。"]', '诗', 'shi', '', NULL, '遊終南山因寄蘇奉禮士尊師苗員外 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('017cc40c-e1e0-492e-9e35-f19cb643ad13', '長安書事寄盧綸', '长安书事寄盧綸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["弱冠家廬岳，從師歲月深。","翻同老夫見，殊寡少年心。","及此時方晏，因之名亦沈。","趨途非要路，避事樂空林。","素業在山下，青泉當樹陰。","交遊有凋喪，離別代追尋。","向秀初聞笛，鍾期久罷琴。","殘愁猶滿貌，餘淚可霑襟。","勿以朱顏好，而忘白髮侵。","終期入靈洞，相與鍊黃金。"]', '["弱冠家廬岳，從師歲月深。","翻同老夫见，殊寡少年心。","及此时方晏，因之名亦沈。","趨途非要路，避事乐空林。","素業在山下，青泉當樹陰。","交游有凋喪，離別代追尋。","向秀初闻笛，鍾期久罷琴。","殘愁猶满貌，餘泪可霑襟。","勿以朱顏好，而忘白髮侵。","終期入靈洞，相與鍊黄金。"]', '诗', 'shi', '', NULL, '長安書事寄盧綸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('999dbf81-f5a8-4f71-87b3-54bd70dbeab0', '送郭良輔下第東歸', '送郭良輔下第东归', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["獻策不得意，馳車東出秦。","暮年千里客，落日萬家春。"]', '["獻策不得意，驰车东出秦。","暮年千里客，落日万家春。"]', '诗', 'shi', '', NULL, '送郭良輔下第東歸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9816ff60-fc81-4291-8d05-cad5e5541933', '妾薄命', '妾薄命', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["自從君棄妾，憔悴不羞人。","唯餘壞粉淚，未免映衫勻。"]', '["自從君棄妾，憔悴不羞人。","唯餘壞粉泪，未免映衫勻。"]', '诗', 'shi', '', NULL, '妾薄命 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ca2c1c-1daa-495e-9796-f1e31472bdb2', '送暕上人遊春', '送暕上人游春', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["獨將支遁去，欲往戴顒家。","晴野人臨水，春山樹發花。"]', '["独將支遁去，欲往戴顒家。","晴野人臨水，春山樹發花。"]', '诗', 'shi', '', NULL, '送暕上人遊春 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69fc549b-654d-4ce7-8de6-8b9b6d6bd895', '晦日同苗員外遊曲江', '晦日同苗員外游曲江', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["晦日同攜手，臨流一望春。","可憐楊柳陌，愁殺故鄉人。"]', '["晦日同携手，臨流一望春。","可怜楊柳陌，愁殺故乡人。"]', '诗', 'shi', '', NULL, '晦日同苗員外遊曲江 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d822a7d-7393-42c5-9366-263c627b8403', '溪行逢雨與柳中庸', '溪行逢雨與柳中庸', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["日落衆山昏，蕭蕭暮雨繁。","那堪兩處宿，共聽一聲猨。"]', '["日落衆山昏，蕭蕭暮雨繁。","那堪兩处宿，共听一声猨。"]', '诗', 'shi', '', NULL, '溪行逢雨與柳中庸 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa36cc8-fec9-455c-91b7-23fc83cdddb1', '和張尹憶東籬菊', '和張尹憶东籬菊', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["傳書報劉尹，何事憶陶家。","若爲籬邊菊，山中有此花。"]', '["傳书報劉尹，何事憶陶家。","若爲籬邊菊，山中有此花。"]', '诗', 'shi', '', NULL, '和張尹憶東籬菊 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0737190-4461-4ec7-b548-8b1534b87e47', '幽居作', '幽居作', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["山舍千年樹，江亭萬里雲。","回潮迎伍相，驟雨送湘君。"]', '["山舍千年樹，江亭万里云。","回潮迎伍相，驟雨送湘君。"]', '诗', 'shi', '', NULL, '幽居作 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b4365f7-5f12-44bf-aef1-b30e2762fe41', '題雲際寺暕上人故院', '題云際寺暕上人故院', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["白髮怱怱色，青山草草心。","遠公仍下世，從此別東林。"]', '["白髮怱怱色，青山草草心。","远公仍下世，從此別东林。"]', '诗', 'shi', '', NULL, '題雲際寺暕上人故院 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a9e58d6-e9a2-4b7a-87b1-25f114878049', '觀鄰老栽松', '观鄰老栽松', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["雖過老人宅，不解老人心。","何事殘陽裏，栽松欲待陰。"]', '["雖過老人宅，不解老人心。","何事殘陽裏，栽松欲待陰。"]', '诗', 'shi', '', NULL, '觀鄰老栽松 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f9b6ea2-3e56-453a-9d39-5e9bef673fb9', '贈胡居士', '贈胡居士', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["孔融過五十，海內故人稀。","相府恩猶在，知君未拂衣。"]', '["孔融過五十，海內故人稀。","相府恩猶在，知君未拂衣。"]', '诗', 'shi', '', NULL, '贈胡居士 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba05573-8aed-4481-8905-cabca7a82160', '薦福寺送元偉', '薦福寺送元偉', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["送客攀花後，尋僧坐竹時。","明朝莫回望，青草馬行遲。"]', '["送客攀花後，尋僧坐竹时。","明朝莫回望，青草马行遲。"]', '诗', 'shi', '', NULL, '薦福寺送元偉 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc4c2a7c-919c-4f80-b76c-3e0f6623133c', '哭苗垂', '哭苗垂', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["舊友無由見，孤墳草欲長。","月斜鄰笛盡，車馬出山陽。"]', '["旧友無由见，孤墳草欲长。","月斜鄰笛尽，车马出山陽。"]', '诗', 'shi', '', NULL, '哭苗垂 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b3a08a6-de60-42f3-8b7b-bc949c34ad21', '客行贈馮著', '客行贈馮著', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["旅行雖別路，日暮各思歸。","欲下今朝淚，知君亦濕衣。"]', '["旅行雖別路，日暮各思归。","欲下今朝泪，知君亦濕衣。"]', '诗', 'shi', '', NULL, '客行贈馮著 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c77e523-20ae-4f4d-a181-74127bbb9af0', '蕪城', '蕪城', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["風吹城上樹，草沒城邊路。","城裏月明時，精靈自來去。"]', '["风吹城上樹，草沒城邊路。","城裏月明时，精靈自来去。"]', '诗', 'shi', '', NULL, '蕪城 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a8459fb-eaeb-4ba3-8d3d-f12cbfe3f11c', '贈山中老人', '贈山中老人', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["白首獨一身，青山爲四鄰。","雖行故鄉陌，不見故鄉人。"]', '["白首独一身，青山爲四鄰。","雖行故乡陌，不见故乡人。"]', '诗', 'shi', '', NULL, '贈山中老人 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f166bcbd-1129-4a26-957a-30cd0f7d9389', '拜新月', '拜新月', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["開簾見新月，便即下階拜。","細語人不聞，北風吹裙帶。"]', '["开簾见新月，便即下階拜。","細語人不闻，北风吹裙带。"]', '诗', 'shi', '', NULL, '拜新月 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3799de-78b4-49bc-b6d8-a5fa3ecacd33', '聽箏', '听箏', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["鳴箏金粟柱，素手玉房前。","欲得周郎顧，時時誤拂弦。"]', '["鳴箏金粟柱，素手玉房前。","欲得周郎顧，时时誤拂弦。"]', '诗', 'shi', '', NULL, '聽箏 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6144e081-33f1-4157-a71f-dad2502278d2', '贈何兆', '贈何兆', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["文章似揚馬，風骨又清羸。","江漢君猶在，英靈信未衰。"]', '["文章似揚马，风骨又清羸。","江漢君猶在，英靈信未衰。"]', '诗', 'shi', '', NULL, '贈何兆 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e28a30-bd37-43c6-be88-a08d29b4f571', '同司空文明過堅上人故院', '同司空文明過堅上人故院', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["我與雷居士，平生事遠公。","無人知是舊，共到影堂中。"]', '["我與雷居士，平生事远公。","無人知是旧，共到影堂中。"]', '诗', 'shi', '', NULL, '同司空文明過堅上人故院 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('889c97a7-a749-41f9-8441-2001b4b60fa9', '雜詩', '杂诗', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["主第辭高飲，石家赴宵會。","金谷走車來，玉人騎馬待。"]', '["主第辞高饮，石家赴宵會。","金谷走车来，玉人騎马待。"]', '诗', 'shi', '', NULL, '雜詩 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e75600-f50b-4254-a731-ea10c358b148', '感興', '感兴', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["香爐最高頂，中有高人住。","日暮下山來，月明上山去。"]', '["香爐最高頂，中有高人住。","日暮下山来，月明上山去。"]', '诗', 'shi', '', NULL, '感興 李端 shi');
